/* テキストの「さらに深く」拡充(担当:地理・倫理・政治経済) */
(function (L) {
  function add(id, o) {
    var x = L[id]; if (!x) return;
    ['secs', 'drill', 'faq'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); });
  }

  add('gg_map', {
    secs: [
      { h: 'さらに深く:メルカトル図法は、なぜ高緯度ほど大きくなるのか', t: '地球儀の上では、経線は北極と南極の1点に集まります。そのため、緯線の長さは緯度が高くなるほど短くなります。緯度φの緯線の長さは、赤道の長さ(約4万km)に【cosφ】をかけた長さです。北緯60度では cos60°=0.5 なので、緯線の長さは約2万kmで、赤道のちょうど半分しかありません。\nところがメルカトル図法では、経線を平行な直線にするので、どの緯線も赤道と同じ長さにえがかれます。つまり、緯度60度の緯線は東西方向に【2倍】に引きのばされています。一般に、緯度φの所では東西方向に【1/cosφ倍】にのびます。\n東西だけをのばすと、形が横につぶれて角度がくるいます。そこでメルカトル図法は、南北方向も同じ倍率だけのばしています。こうすると、せまい範囲では形と角度が正しく保たれます。高緯度ほど緯線と緯線の間隔が広がっていくのは、このためです。\n東西にも南北にも1/cosφ倍にのびるので、面積は【1/cos²φ倍】になります。緯度60度では長さが2倍、面積は【4倍】です。グリーンランドがアフリカ大陸と同じくらいに見えるのは、このしくみのためです。極では cos90°=0 なので倍率が無限大になり、極そのものはえがけません。\nこのように、メルカトル図法の「面積のゆがみ」は、「角度を正しくする」ために、わざと引き受けたものなのです。', key: 'メルカトル図法は、緯度φで東西・南北とも1/cosφ倍にのばして角度を守っている。その代わり、面積は1/cos²φ倍にふくらむ。', ex: [{ q: '北緯60度の緯線にそって、東経10度から東経100度まで進んだ。実際の距離はおよそ何kmか。また、メルカトル図法の地図上では、この区間は赤道上で経度差が同じ区間と比べて、何倍の長さにえがかれているか。(地球一周を4万kmとする)', hint: 'まず北緯60度の緯線1周の長さを求めます。メルカトル図法では、経線は平行な直線です。', steps: ['経度差は100−10=90度で、緯線1周(360度)の4分の1にあたる。', '北緯60度の緯線1周の長さは、4万km×cos60°=4万×0.5=2万km。', 'したがって実際の距離は、2万km×(90÷360)=5000km。', 'メルカトル図法では経線が平行な直線なので、経度差が同じなら、どの緯度でも地図上の長さは同じ(1倍)にえがかれる。', '赤道上の同じ区間は実際に1万kmあるので、北緯60度の区間は、実際の2倍に引きのばされてえがかれていることになる。'], a: '実際の距離は約5000km。地図上では赤道上の区間と同じ長さ(1倍)にえがかれる(=実際の2倍に引きのばされている)。', check: '赤道上の経度差90度は4万÷4=1万km。北緯60度では1/cos60°=2倍にのびるので、5000km×2=1万km分の長さになり、赤道上と同じ長さになることと一致します。' }] },
      { h: '実戦演習:日付変更線をまたぐ時差と、太陽の南中から経度を求める', t: '時差の問題は、手順を決めておけば日付変更線をまたいでも迷いません。\n①まず2地点の【経度差】を出します。東経どうし・西経どうしなら引き算、東経と西経なら【足し算】です(経度0度の側を通って数える)。\n②経度15度で1時間なので、経度差÷15で時差が出ます。【東にある地点ほど時刻が進んでいる】と考えます。\n③飛行機の問題は、出発地の時刻に所要時間を足して「到着した瞬間の出発地の時刻」を出し、最後に1回だけ到着地の時刻に直します。\nよくある落とし穴は、日付変更線の側から数えたり経度0度の側から数えたりを混ぜることです。東経と西経の足し算で求めれば、日付変更線のことを特に考えなくても正しい答えになります。\nまた、太陽は1時間に経度15度ずつ西へ動いて見え、その土地の真南に来た(南中した)ときが、その土地の太陽の時刻で正午です。この性質を使うと、南中の時刻から経度を逆算できます。', key: '経度差は「東経と西経なら足す」。時刻の換算は最後に1回だけ。南中の時刻のずれ×15度で経度が出る。', ex: [{ q: '東京(東経135度の標準時)を1月10日午後8時に出発した飛行機が、7時間かかってホノルル(西経150度の標準時)に着いた。到着したときのホノルルの日時を答えよう。(サマータイムは考えない)', hint: '東経と西経なので、経度差は足し算です。まず日本時間のまま到着時刻を出します。', steps: ['経度差は135+150=285度。時差は285÷15=19時間で、東にある東京のほうが19時間進んでいる。', '到着した瞬間の日本時間は、1月10日午後8時+7時間=1月11日午前3時。', 'ホノルルは東京より19時間遅れているので、1月11日午前3時から19時間もどす。', '1月11日午前3時の19時間前は、1月10日午前8時。'], a: '1月10日午前8時', check: '日付変更線の側から考えると、経度差は360−285=75度で5時間。日付変更線をこえて東へ行くと日付を1日もどすので、1月11日午前3時+5時間=1月11日午前8時、から1日もどして1月10日午前8時となり、一致します。出発より「前の日付・時刻」に着いたように見えるのが、日付変更線をこえる東向きの旅の特徴です。' }, { q: 'ある地点で太陽が南中したとき、日本標準時は午後2時だった。この地点の経度を答えよう。(太陽の南中時刻の季節によるずれは考えない)', hint: '東経135度の地点で太陽が南中するのは、日本時間の正午です。', steps: ['日本標準時の基準である東経135度では、日本時間の正午に太陽が南中する。', 'この地点では、それより2時間おそく南中している。太陽は東から西へ動いて見えるので、おそく南中する地点ほど西にある。', '太陽は1時間に15度動いて見えるので、2時間で15×2=30度。', 'この地点は東経135度より30度西にあるので、東経105度。'], a: '東経105度', check: '東経105度の地方時は日本時間より2時間おくれているので、その土地の正午(南中)は日本時間で午後2時になり、条件と一致します。東経105度付近はインドシナ半島のあたりです。' }] }
    ],
    drill: [
      { lv: 2, q: '北緯30度の緯線の長さは、およそ何kmか。地球一周(赤道の長さ)を4万km、cos30°≒0.87として答えよう。', a: '約3万5千km(4万×0.87=3万4800km)', exp: '緯線は、地球の中心から見て、緯度が高くなるほど小さな円になります。緯度φの緯線の半径は、赤道の半径の cosφ 倍なので、長さも cosφ 倍です。4万×0.87=3万4800kmで、およそ3万5千kmです。\nまちがえやすいのは、「緯度30度は90度の3分の1だから、長さも3分の1減る」と比例で考えてしまうことです。緯線の長さは緯度に比例して減るのではなく、赤道付近ではゆっくり、高緯度ほど急に短くなります。北緯60度で半分、北緯90度(北極)で0になります。経線のほうは、どこでも長さが同じ(北極から南極まで約2万km)であることとも区別しておきましょう。' },
      { lv: 3, q: 'メルカトル図法の地図で、北緯60度付近にある島Aと、赤道付近にある島Bが、ほぼ同じ面積にえがかれていた。実際の面積はどちらが大きく、およそ何倍か。', a: '島Bのほうが大きく、島Aのおよそ4倍。', exp: 'メルカトル図法では、緯度φの所は東西にも南北にも1/cosφ倍にのびるので、面積は1/cos²φ倍にえがかれます。北緯60度では1/0.5²=4倍です。赤道付近はほとんどのびません。\n地図の上で同じ面積に見えるなら、島Aは実際の4倍にふくらんでえがかれていることになります。したがって、実際には島Aは島Bの4分の1しかなく、島Bが島Aの約4倍の面積をもちます。\n「4倍に見える」と「実際は4分の1」の向きを逆にしないように注意しましょう。長さは2倍、面積は2²=4倍、と分けて考えると混乱しません。' },
      { lv: 3, q: 'ある地点で太陽が南中したとき、ロンドン(経度0度)の時刻は午前9時だった。この地点の経度を答え、その理由を説明しよう。(南中時刻の季節によるずれは考えない)', a: '東経45度。経度0度では正午に南中するのに、この地点では3時間早く南中しているので、15度×3=45度だけ東にあるから。', exp: '太陽は東から西へ動いて見えるので、東にある地点ほど早く南中します。経度0度で太陽が南中するのはロンドンの時刻で正午です。この地点ではロンドンの午前9時、つまり3時間早く南中したので、ロンドンより東にあります。\n太陽は1時間に15度動いて見えるので、3時間で45度です。よって東経45度です。\n「早く南中=西」と逆に考えると西経45度と答えてしまいます。日の出も南中も日の入りも、東の地点から先に起こる、と覚えておくと確かめられます。' }
    ],
    faq: [
      ['「大縮尺」と「小縮尺」は、どちらがくわしい地図なの?', '縮尺を分数で表したとき、値が大きいほうが【大縮尺】です。1/25000と1/50000では、1/25000のほうが大きいので大縮尺です。\n大縮尺の地図は、せまい範囲を大きく、くわしくえがきます。小縮尺の地図は、広い範囲を小さくえがくので、細かい情報は省かれます。「分母が大きい=小縮尺」なので、数字の大きさにつられて逆にしないようにしましょう。'],
      ['経線と経線の間は高緯度ほどせまくなるのに、なぜ時差はどこでも「経度15度で1時間」なの?', '時差は、地球が24時間で360度自転することから決まります。360÷24=15なので、地球は1時間に15度回ります。\n高緯度では経度15度ぶんの距離(km)は短くなりますが、地球が回る「角度」は緯度に関係なく同じです。だから、時差を決めるのは距離ではなく経度の差なのです。北極の近くでは、少し歩くだけで経度が大きく変わることもあります。']
    ]
  });

  add('gg_climate', {
    secs: [
      { h: 'さらに深く:空気は上がると冷える──断熱変化とフェーン現象', t: '「標高が100m上がると気温が約0.65℃下がる」というのは、その場所の気温を平均した値です。雲や雨のでき方を考えるには、【空気のかたまりが上昇するときの冷え方】を知る必要があります。\n上空ほど気圧が低いので、上昇した空気はまわりから押される力が弱まり、ふくらみます(【断熱膨張】)。ふくらむときに自分のエネルギーを使うので、温度が下がります。水蒸気がまだ水滴になっていない空気は、100mにつき約【1℃】下がります(乾燥断熱減率)。\n冷えて水蒸気が水滴になり始めると、雲ができます。水蒸気が水になるときには熱(【凝結熱】)が出るので、そのぶん冷え方がゆるやかになり、100mにつき約【0.5℃】になります(湿潤断熱減率)。\nこの差が生むのが【フェーン現象】です。湿った風が山にぶつかって上昇すると、風上側で雲ができて雨を降らせ、0.5℃ずつしか冷えずに山頂に達します。山をこえて下りるときは、水分を落とした乾いた空気として1℃ずつ温まるので、風下では、もとの気温より高温で乾燥した風になります。日本でも、低気圧や台風に向かう風が山脈をこえたとき、日本海側で季節はずれの高温になることがあります。\n山の風下が乾燥する例としては、南アメリカ南部のパタゴニアがあります。偏西風がアンデス山脈の西側に雨を降らせたあと、東側に乾いた風としてふき下りるため、草原や荒れ地が広がります。', key: '上昇する空気は冷えて雲と雨をつくる。山をこえて下りる空気は乾いた状態で温まるので、風下は高温・乾燥になる。', ex: [{ q: '標高0mで気温20℃の空気が、標高2000mの山脈をこえる。風上側では標高500mで雲ができ始め、山頂まで雲ができ続けた。風下側では雲はできず、標高0mまで下りた。風下側の標高0mでの気温は何℃か。(乾燥断熱減率を100mにつき1℃、湿潤断熱減率を100mにつき0.5℃とする)', hint: '雲ができる前・できている間・下りるとき、の3つの区間に分けて計算します。', steps: ['0m→500mは雲ができていないので、100mにつき1℃下がる。500mで1℃×5=5℃下がり、20−5=15℃。', '500m→2000mは雲ができているので、100mにつき0.5℃下がる。1500mで0.5℃×15=7.5℃下がり、15−7.5=7.5℃。', '2000m→0mの下りは雲ができない乾いた空気なので、100mにつき1℃上がる。2000mで20℃上がり、7.5+20=27.5℃。', '風上側の20℃と比べて7.5℃高い。これは、上りの途中で凝結熱が出て冷え方が小さかったためである。'], a: '27.5℃', check: '上りでは合計12.5℃下がり、下りでは20℃上がるので、差し引き7.5℃上がります。「雲ができていた区間の長さ1500m×(1−0.5)℃/100m=7.5℃」と計算しても同じになります。' }] },
      { h: '実戦演習:乾燥限界を計算して、BW・BS・湿潤な気候を見分ける', t: '乾燥帯かどうかは、年降水量だけでは決まりません。気温が高いほど蒸発する水が多いからです。そこでケッペンは、年平均気温t(℃)から【乾燥限界r(mm)】を計算しました。\n・1年中ほぼ平均して降る場合:r=20(t+7)\n・年降水量の約7割以上が夏の半年に降る場合:r=20(t+14)\n・年降水量の約7割以上が冬の半年に降る場合:r=20t\n年降水量Rがrより少なければ乾燥帯(B)で、さらにrの半分より少なければ【砂漠気候(BW)】、半分以上なら【ステップ気候(BS)】です。\n夏に雨が多いほど乾燥限界が高いのは、気温の高い時期に降った雨はすぐに蒸発してしまい、植物に使われにくいからです。逆に、冬に降る雨は土にしみこんで残りやすいのです。\n典型的な落とし穴は、「年降水量が400mmだから乾燥帯」と量だけで決めることです。必ず、気温と雨の季節を見て乾燥限界を出してから比べましょう。', key: '同じ降水量でも、気温が高く、雨が夏に集中するほど乾燥帯になりやすい。rとr/2の2本の線で判定する。', ex: [{ q: '年平均気温18℃、年降水量400mmで、雨の大部分が夏に降る地点がある。この地点の気候区分は、BW・BS・乾燥帯ではない、のどれか。', hint: '夏に雨が集中しているので、r=20(t+14)の式を使います。', steps: ['夏に雨が集中しているので、乾燥限界は r=20(18+14)=20×32=640mm。', '年降水量400mmは640mmより少ないので、乾燥帯(B)である。', '砂漠かステップかは r の半分と比べる。640÷2=320mm。', '400mmは320mm以上なので、砂漠気候ではなく、ステップ気候(BS)。'], a: 'ステップ気候(BS)', check: '400<640(乾燥帯)、400≧320(砂漠ではない)の2つの不等式を確かめれば、答えが確定します。' }, { q: '前の問題と同じく年平均気温18℃・年降水量400mmだが、雨の大部分が冬に降る地点がある。この地点は乾燥帯か。前の問題と比べて答えよう。', hint: '冬に雨が集中する場合の式は r=20t です。', steps: ['冬に雨が集中しているので、乾燥限界は r=20×18=360mm。', '年降水量400mmは360mmより多いので、乾燥帯ではない。', '前の問題では乾燥限界が640mmだったので乾燥帯だった。同じ気温・同じ降水量でも、雨の季節によって判定が変わる。', '冬に雨が降るこの地点は、樹木が育つ温帯などの気候(たとえば夏に乾燥する地中海性気候)の可能性がある。'], a: '乾燥帯ではない(乾燥限界360mmを上回るため)。', check: '冬の雨は蒸発しにくく土に残るので、少ない雨でも樹木が育ちます。地中海沿岸に年降水量のわりにオリーブなどの樹木が多い理由とも結びつきます。' }] }
    ],
    drill: [
      { lv: 2, q: '標高0mで気温25℃の湿った空気が、最初から雲をつくりながら標高2000mの山頂まで上昇し、風下側では雲をつくらずに標高0mまで下りた。風下側の標高0mでの気温は何℃か。(乾燥断熱減率は100mにつき1℃、湿潤断熱減率は100mにつき0.5℃とする)', a: '35℃', exp: '上りはずっと雲ができているので、100mにつき0.5℃ずつ下がります。2000mで0.5×20=10℃下がり、山頂では15℃です。\n下りは乾いた空気なので、100mにつき1℃ずつ上がります。2000mで20℃上がり、15+20=35℃です。\n上りと下りで温度の変わり方がちがうことが、フェーン現象のポイントです。上りも下りも同じ0.5℃や1℃で計算してしまうと、もとの25℃にもどってしまい、フェーン現象が説明できません。「雲ができているかどうか」で使う数字を切りかえましょう。' },
      { lv: 3, q: '年平均気温10℃、年降水量150mmで、雨が1年中ほぼ平均して降る地点がある。乾燥限界を計算して、気候区分(BW・BS・乾燥帯ではない)を判定しよう。', a: '乾燥限界は20×(10+7)=340mm。150mmは340mmの半分の170mmより少ないので、砂漠気候(BW)。', exp: '1年中平均して降る場合の式 r=20(t+7) を使うと、r=20×17=340mmです。年降水量150mmは340mmより少ないので乾燥帯です。さらに、340÷2=170mmと比べると150mmのほうが少ないので、砂漠気候(BW)と判定できます。\n年平均気温が10℃と低めなので、暑い砂漠ではなく、中緯度の内陸にあるような「寒い砂漠」のタイプです。\nまちがえやすいのは、r の半分と比べる手順を忘れて「乾燥帯=ステップ」としてしまうことです。乾燥帯と分かったら、必ず2本目の線(r/2)とも比べましょう。' },
      { lv: 3, q: '雲ができているときの空気の冷え方(湿潤断熱減率)が、雲ができていないとき(乾燥断熱減率)より小さいのはなぜか。また、空気が上昇して雨が降る場面を、地形以外に2つ挙げよう。', a: '水蒸気が凝結して水滴になるときに凝結熱を放出し、その熱が空気を温めるぶん、冷え方がゆるやかになるから。雨が降る場面の例:強い日射で地面が温められて起こる上昇気流(熱帯のスコールなど)、暖かい空気と冷たい空気がぶつかる前線、低気圧の中心に向かって集まった空気の上昇。', exp: '水が蒸発するときにはまわりから熱をうばい、逆に水蒸気が水にもどるときには、その熱を放出します。雲ができている空気では、上昇して冷えるたびに凝結が進み、熱が出るので、冷え方が小さくなるのです。\n空気が上昇する場面は、①地面が強く温められる(対流による雨)、②山の斜面をのぼる(地形による雨)、③前線で暖かい空気が冷たい空気の上にのり上げる(前線による雨)、④低気圧に風が集まって上昇する(低気圧による雨)、の4つに整理できます。赤道付近で毎日のように午後に激しい雨が降るのは①、梅雨は③の例です。' }
    ],
    faq: [
      ['赤道の真上では、太陽が真上に来るのは1年に何回あるの?', '2回です。太陽が真上に来る緯度は、夏至のころの北回帰線(北緯約23.4度)と冬至のころの南回帰線の間を1年かけて往復します。赤道の上を通るのは、春分のころと秋分のころの2回です。\nそのため赤道付近では、気温の年変化が小さく、季節は暑さ・寒さよりも雨の多い時期・少ない時期として感じられます。北回帰線の上では、真上に来るのは夏至のころの1回だけです。'],
      ['偏西風と季節風(モンスーン)は、どうちがうの?', '偏西風は、大気の大循環によって中緯度でほぼ1年中、西から東へふく【恒常風】です。季節によって位置は少し南北に動きますが、向きは変わりません。\n季節風は、海と陸の温まり方のちがいによって生じ、夏と冬で向きがほぼ【逆になる】風です。夏は温まりやすい大陸に向かって海からふき、冬は冷えた大陸から海へふき出します。東アジアや南アジアで特に発達し、雨季と乾季をつくります。']
    ]
  });

  add('gg_landform', {
    secs: [
      { h: 'さらに深く:大地形の「年齢」が、資源のありかを決める', t: '安定陸塊・古期造山帯・新期造山帯という区分は、山の高さを説明するだけではありません。それぞれの土地ができた【時代】がちがうので、そこにねむる【資源】にも特徴が出ます。\n【安定陸塊】は、先カンブリア時代の古い岩石でできています。この時代、海の中にとけていた鉄が、生物が生み出した酸素と結びついて海底に積もり、鉄分の多い地層がつくられました。そのため、【鉄鉱石】の大産地は安定陸塊に集中しています。オーストラリア北西部や、ブラジル高原が代表例です。\n【古期造山帯】は、古生代の後半に山脈ができた所です。古生代には大型のシダ植物などが大森林をつくり、それが地中に埋もれて長い時間をかけて【石炭】になりました。そのため、アメリカのアパラチア山脈の周辺や、オーストラリア東部のグレートディヴァイディング山脈の周辺など、古期造山帯の付近に大きな炭田が多く見られます。\n【石油】は、海の生物の死がいなどが、比較的新しい時代の地層の中で変化してできたものです。石油は水より軽いので地層の中を上へ移動し、地層が山のように盛り上がった【背斜構造】の、水や油を通しにくい岩の下にたまります。ペルシア湾岸のように、新期造山帯の周辺にある厚い地層の地域に大油田が多いのはこのためです。\nもちろん例外もありますが、「古い土地=鉄、少し新しい山=石炭、新しい地層=石油」という目安をもつと、資源の分布が地形とつながって見えてきます。', key: '鉄鉱石は安定陸塊、石炭は古期造山帯の周辺、石油は新しい地層の背斜構造に多い。資源の分布は、土地ができた時代と結びついている。', ex: [{ q: 'オーストラリアでは、鉄鉱石の大産地は北西部に、石炭の大産地は東部に多い。この分布のちがいを、大地形と結びつけて説明しよう。', hint: 'オーストラリアの西側と東側は、それぞれどの大地形にあたるでしょうか。', steps: ['オーストラリアの西部から中央部は、先カンブリア時代の古い岩石でできた安定陸塊である。', '鉄鉱石の多くは先カンブリア時代に海底に積もった鉄分の多い地層からとれるので、安定陸塊の北西部に大産地がある。', '東部には、古生代に山脈ができた古期造山帯のグレートディヴァイディング山脈がある。', '石炭は古生代などの植物が埋もれてできたものなので、古期造山帯の周辺の東部に炭田が多い。'], a: '西部は先カンブリア時代の地層が広がる安定陸塊で、その時代にできた鉄鉱石が多い。東部は古生代に形成された古期造山帯で、その周辺に古生代の植物からできた石炭が多い。', check: 'アメリカでも、五大湖の西側の安定陸塊に鉄鉱石(メサビ鉄山)、東部の古期造山帯のアパラチア山脈周辺に炭田があり、同じ組み合わせになっています。' }] },
      { h: '実戦演習:三角州の形を「川の土砂」と「海の力」の綱引きで推理する', t: '三角州は、川が運んできた土砂が河口に積もってできます。その形が円弧状・鳥趾状などにちがうのは、【川が運ぶ土砂の量】と、【波や潮の流れが土砂を運び去る力】の綱引きの結果です。\n・川の土砂が多く、波や潮の力が弱い:土砂が川の流れにそって沖へのび、鳥のあしのように枝分かれした【鳥趾状三角州】になります(ミシシッピ川)。\n・土砂の量と波の力がつりあう:河口の前面が波にならされて、なめらかな弧をえがく【円弧状三角州】になります(ナイル川)。\n・波の力が強い:河口だけがとがって突き出た【カスプ状三角州】になります(イタリアのテヴェレ川)。\n・潮の干満が大きく、土砂が流し去られる:三角州ができず、河口がラッパ状に広がるエスチュアリーになります。\n問題を解くときは、まず「土砂の量」と「海の力」のどちらが強いかを判断し、それから形を考えましょう。形の名前の丸暗記では、条件の変化を問う問題に対応できません。', key: '三角州の形は、川の土砂の供給と、波・潮が土砂を運び去る力のバランスで決まる。条件が変われば形も変わる。', ex: [{ q: '次のA・Bの河口のようすから、それぞれの三角州の形を推理しよう。A:流域が広く、大量の泥を運ぶ大河が、波のおだやかな湾に注いでいる。B:河口の前の海は波が強く、川が運ぶ土砂の量は多くない。', hint: '土砂の量と海の力の、どちらが勝っているかを考えます。', steps: ['Aは、川が運ぶ土砂がとても多く、波が弱いので、土砂は運び去られずに河口から沖へのびていく。', '川の流れがいくつかに分かれ、それぞれの流れにそって土砂が積もるので、枝分かれした形になる。よってAは鳥趾状三角州。', 'Bは、波が強く、土砂の量が少ないので、河口から出た土砂の多くは波で左右に運ばれてしまう。', '流れの出口の部分だけがわずかに突き出るので、Bはとがった形のカスプ状三角州になる。'], a: 'A:鳥趾状三角州 B:カスプ状三角州', check: 'Aはミシシッピ川、Bはテヴェレ川がそれぞれの典型です。中間のつりあった状態が円弧状(ナイル川)になることも、綱引きの考え方で説明できます。' }, { q: 'エジプトでは、1970年にナイル川の上流にアスワン・ハイダムが完成した。その後、ナイル川の河口付近では、海岸線が後退する(海岸がけずられる)所が出てきた。その理由を説明しよう。', hint: 'ダムができると、川が運ぶ何が減るでしょうか。', steps: ['三角州は、川が運んでくる土砂と、波が運び去る土砂のつりあいで形が保たれている。', 'ダムができると、上流から運ばれてきた土砂の多くがダム湖にたまり、河口まで届く土砂が大きく減る。', '一方で、波が海岸の土砂を運び去る力は変わらない。', '綱引きのバランスが「海の力」の側にかたむくため、積もる土砂より運び去られる土砂が多くなり、海岸がけずられて後退する。'], a: 'ダムが上流からの土砂をせき止めたため、河口に届く土砂が減り、波による侵食が土砂の堆積を上回るようになったから。', check: '日本でも、ダムや砂防えん堤の建設、川砂の採取によって、河口近くの砂浜がやせる例が各地で見られます。同じしくみで説明できるか確かめてみましょう。' }] }
    ],
    drill: [
      { lv: 2, q: 'パリ盆地や五大湖の周辺に見られる、かたい地層とやわらかい地層がゆるく傾いて重なった所で、やわらかい層が先にけずられてできた、片側が急ながけ、反対側がゆるやかな斜面になった丘を何という?', a: 'ケスタ', exp: 'かたい層とやわらかい層が交互に、ゆるく傾いて重なっていると、やわらかい層のほうが速く侵食されます。かたい層は、その傾きにそったゆるやかな斜面と、層の切り口にあたる急ながけをもつ丘として残ります。これがケスタです。\nパリ盆地では、パリを囲むように何列ものケスタが並んでいます。北アメリカのナイアガラの滝も、ケスタの急ながけにかかる滝です。\nケスタは「侵食の速さのちがい」がつくる地形で、プレートの力で直接もち上がった山とはでき方がちがいます。地形の区分では、外的営力(侵食)による地形にあたります。' },
      { lv: 3, q: '石油や天然ガスが、地層が上向きに盛り上がった背斜構造の部分にたまりやすいのはなぜか説明しよう。', a: '石油や天然ガスは水より軽いので、すき間の多い地層の中を上へ移動する。背斜構造の頂上部では、その上を水や油を通しにくい岩の層がふたのようにおおっているため、上へ逃げられずにそこに集まってたまるから。', exp: '石油は、海の生物の死がいなどが地中で熱や圧力を受けて変化したものです。できた石油は、砂岩などすき間の多い地層の中を、水との比重のちがいで上へ上へと移動していきます。\n地層が山のように盛り上がった背斜構造では、移動してきた石油や天然ガスが頂上部に集まります。その上に泥岩などの通しにくい岩(帽岩)があると、ふたをされたように閉じこめられ、油田やガス田になります。\n上には軽い順にガス・石油・水の順に層が分かれてたまることも多く、これも比重のちがいで説明できます。逆に、下向きにくぼんだ向斜構造には、石油は集まりにくいと考えられます。' },
      { lv: 3, q: 'イギリスのテムズ川の河口には三角州が発達せず、ラッパ状に広がったエスチュアリーになっている。三角州ができにくい理由と、エスチュアリーが港として利用されやすい理由を説明しよう。', a: '河口付近が沈水したうえ、潮の干満の差が大きく、潮の流れが川の運んだ土砂を沖へ運び去るので、土砂が積もりにくいから。また、河口が広く深い水面になり、潮の満ち引きを利用して大きな船が内陸まで入りやすいので、港として利用されやすい。', exp: '三角州ができるには、河口に土砂が積もり続けることが必要です。テムズ川の河口は、氷期の後に海面が上がって谷が沈水したうえ、潮の干満の差が大きく、毎日の強い潮の流れが土砂を運び去ります。さらに、ゆるやかな平野を流れる川なので、運ぶ土砂の量もそれほど多くありません。\nこうしてできたラッパ状の広い河口は、水深が確保されやすく、内陸まで船が入れるので、ロンドンのような港湾都市が発達しました。\n三角州の形の綱引きで言えば、「海の力」が強く勝っている極端な場合がエスチュアリーだと考えると、ほかの形と一つの流れで理解できます。' }
    ],
    faq: [
      ['日本で鉄鉱石や石炭があまりとれないのはなぜ?', '日本列島は新期造山帯にあり、土地をつくる地層の多くが比較的新しく、断層や火山活動で複雑に入り組んでいます。鉄鉱石の大産地となる先カンブリア時代の厚い地層は、ほとんどありません。\n石炭は、かつて北海道や九州でさかんに掘られましたが、地層が複雑で掘りにくく、規模も大きくないため、海外の大規模な露天掘りの石炭に価格で太刀打ちできなくなり、大きな炭鉱は閉山しました。'],
      ['プレートは、何の力で動いているの?', '地球の内部では、マントルが長い時間をかけてゆっくり対流しており、その動きがプレートを動かす力の一つと考えられています。\nさらに、海溝で沈みこむプレートは冷えて重いため、自分の重さで沈みながらプレート全体を引っぱる力も大きいと考えられています。動く速さは1年に数cm程度で、髪の毛やつめがのびる速さと同じくらいです。']
    ]
  });

  add('gg_agri', {
    secs: [
      { h: 'さらに深く:同心円はなぜできる?──「地代曲線」で考えるチューネンのモデル', t: 'チューネンの孤立国では、都市を中心に農業が同心円状に並びます。その理由を、もう一歩くわしく数字で考えてみましょう。\nある土地でその作物をつくったときに残るもうけを【位置地代】といいます。1haあたりで、\n位置地代=(作物の売り上げ)−(生産費)−(市場までの輸送費)\nと表せます。輸送費は市場からの距離に比例して増えるので、位置地代は距離が遠くなるほど、まっすぐに(直線で)減っていきます。\nこの直線の【かたむき】は、作物によってちがいます。野菜や牛乳は、重くかさばり、いたみやすいので、遠くまで運ぶ費用が大きく、直線のかたむきが急です。小麦などの穀物は、乾燥していて運びやすいので、かたむきがゆるやかです。牧畜で生産する肉や毛は、さらにゆるやかです。\n農家は、それぞれの場所で位置地代がいちばん大きくなる作物を選びます。すると、市場の近くでは「売り上げは大きいが輸送費のかかる」野菜や牛乳が勝ち、ある距離をこえると、かたむきのゆるやかな穀物の直線のほうが上になります。この入れかわる地点が、同心円の境界です。\nこう考えると、交通の発達でなぜ同心円が外へ広がるのかも説明できます。輸送費が下がると、それぞれの直線のかたむきがゆるやかになり、入れかわる地点がより遠くへ移るからです。', key: '位置地代=売り上げ−生産費−輸送費。輸送費のかかる作物ほど直線のかたむきが急で、地代がいちばん大きい作物が場所ごとに選ばれる。', ex: [{ q: '1haあたりの位置地代(万円)が、市場からの距離をd(km)として、野菜は 60−3d、小麦は 30−0.5d で表されるとする。市場から何kmまでが野菜、何kmまでが小麦の地帯になるか。', hint: 'どちらの作物の地代が大きいかが入れかわる地点と、小麦の地代が0になる地点を求めます。', steps: ['d=0のとき、野菜は60万円、小麦は30万円なので、市場の近くでは野菜のほうが有利。', '2つの地代が等しくなる距離を求める。60−3d=30−0.5d より、30=2.5d、d=12km。', 'dが12kmをこえると、かたむきのゆるやかな小麦のほうが地代が大きくなる。', '小麦の地代が0になるのは、30−0.5d=0 より d=60km。これより遠いと、小麦をつくっても赤字になる。'], a: '市場から12kmまでが野菜、12〜60kmが小麦の地帯。60kmより遠くでは小麦はつくられない(より粗放的な牧畜などになる)。', check: 'd=10kmでは野菜30万円・小麦25万円で野菜が有利、d=20kmでは野菜0万円・小麦20万円で小麦が有利です。境界の12kmをはさんで有利な作物が入れかわっており、計算は正しいことが確かめられます。' }] },
      { h: '実戦演習:統計の「組み合わせ」から農業の型と国を推理する', t: '農業の統計問題では、1つの数字だけでなく、いくつかの指標の【組み合わせ】から推理することが大切です。よく使われる指標は次の3つです。\n①【農業従事者1人あたりの農地面積】:広いほど、機械を使った大規模な農業で、労働生産性が高い傾向があります。\n②【1haあたりの穀物の収量】:多いほど、肥料や手間をかけた集約的な農業で、土地生産性が高い傾向があります。\n③【農産物の輸出額】:国内の消費を上回る生産があるか、付加価値の高い農産物をつくっているかを表します。\n典型的な落とし穴は、「輸出額が大きい国=農地が広い国」と決めつけることです。オランダのように、国土がせまくても、施設園芸や酪農で付加価値の高い農産物をつくる国は、輸出額が大きくなります。また、「農業従事者の割合が大きい国=農業が強い国」でもありません。途上国では、多くの人が小さな農地で自給的な農業をしているため、割合が大きくなります。', key: '「1人あたり農地」と「1haあたり収量」の組み合わせで農業の型がわかる。輸出額の大きさは、農地の広さだけでは決まらない。', ex: [{ q: '次のA〜Cは、オーストラリア・オランダ・インドのいずれかの農業の特徴である。それぞれどの国か。\nA 農業従事者1人あたりの農地面積がきわめて広いが、1haあたりの穀物収量は低い。\nB 農業従事者1人あたりの農地面積はせまいが、1haあたりの収量はきわめて高く、農産物の輸出額が大きい。\nC 農業従事者1人あたりの農地面積がせまく、1haあたりの収量も高くない。働く人のうち農業に従事する人の割合が大きい。', hint: '労働生産性(1人あたり)と土地生産性(1haあたり)の高い・低いの組み合わせで考えます。', steps: ['Aは、1人あたりの農地が広く労働生産性は高いが、土地生産性は低い。広い土地を少ない人数で使う粗放的な企業的農業の国で、オーストラリアと考えられる。', 'Bは、せまい土地に資本や技術を多く投入し、土地生産性がきわめて高い。輸出額も大きいので、施設園芸や酪農がさかんなオランダと考えられる。', 'Cは、どちらの生産性も高くないが、農業で働く人の割合が大きい。小規模な農家が多い途上国型の農業で、インドと考えられる。', '3つとも条件にあてはまり、組み合わせに矛盾がないことを確かめる。'], a: 'A オーストラリア B オランダ C インド', check: 'オーストラリアの小麦地帯や牧羊地帯は年降水量が少なく、1haあたりの収量は低めです。一方オランダは、温室や機械化で集約的に生産しています。気候・土地の条件と結びつけて説明できれば、判定に自信がもてます。' }, { q: '高知県や宮崎県は、東京や大阪などの大都市から遠いのに、冬から春にかけてピーマンやきゅうりなどの野菜をさかんに出荷している。チューネンの考え方(位置地代)を使って、この理由を説明しよう。', hint: '位置地代=売り上げ−生産費−輸送費。どの項目が大きく変わっているでしょうか。', steps: ['チューネンの考え方では、輸送費のかかる野菜は市場の近くでつくられるはずである。', 'しかし、高知や宮崎は冬でも温暖なので、ビニールハウスなどを使って、他の産地の出荷が少ない冬から春に出荷できる(促成栽培)。', '出荷の少ない時期の野菜は高い値段で売れるので、売り上げが大きくなる。', 'さらに、高速道路やフェリー、保冷トラックの発達で輸送費が下がった。', '売り上げが大きく、輸送費が小さくなったので、遠い産地でも位置地代が大きくなり、野菜づくりが成り立つ。'], a: '温暖な気候を生かした促成栽培で、ほかの産地からの出荷が少ない時期に高い値段で売ることができ、さらに交通の発達で輸送費が下がったため、市場から遠くても位置地代が大きくなるから。', check: '長野県などの高原で夏にレタスやキャベツをつくる抑制栽培も、「ほかの産地が出荷しにくい時期に高く売る」という同じ考え方で説明できます。' }] }
    ],
    drill: [
      { lv: 2, q: '大都市から遠く離れた地域で、気候の条件を生かし、トラックや船・航空機などを使って野菜や花を大都市へ出荷する園芸農業を何という?', a: '輸送園芸農業(トラックファーミング)', exp: '大都市の近くで新鮮な野菜や花をつくる【近郊農業】に対して、遠くの産地から輸送手段を使って出荷するのが【輸送園芸農業】です。アメリカでは、温暖なフロリダ州などから北部の大都市へトラックで野菜を運ぶ農業がその代表です。\n日本では、高知県・宮崎県の促成栽培や、長野県・群馬県の高原での抑制栽培が、輸送園芸農業の例です。\n「近郊農業」と「輸送園芸農業」は、どちらも園芸農業ですが、市場からの距離と、何を有利な条件にしているか(新鮮さか、気候と出荷時期か)がちがいます。' },
      { lv: 3, q: '1haあたりの位置地代(万円)が、市場からの距離をd(km)として、作物Xは 90−4d、作物Yは 45−1.5d で表されるとする。Xがつくられる範囲と、Yがつくられる範囲を答えよう。', a: 'X:市場から18kmまで Y:18kmから30kmまで', exp: 'まず2つの地代が等しくなる距離を求めます。90−4d=45−1.5d より、45=2.5d、d=18kmです。18kmより近いとXのほうが地代が大きく、遠いとYのほうが大きくなります。\n次に、Yの地代が0になる距離は 45−1.5d=0 より d=30kmです。30kmより遠くでは、Yをつくると赤字になるので、Yの地帯はここで終わります。\n確かめとして、d=10kmではX=50・Y=30でX、d=20kmではX=10・Y=15でYが有利です。Xの地代が0になる22.5kmより手前の18kmで、すでにYに逆転されていることもわかります。境界を求めるときは、「どちらが大きいか」と「0より大きいか」の両方を確かめましょう。' },
      { lv: 3, q: '2000年代以降、アメリカでトウモロコシを原料とするバイオエタノールの生産が増えた。このことが、世界の食料や畜産にどのような影響をあたえうるか説明しよう。', a: 'トウモロコシが燃料の原料として大量に使われると、食用・飼料用に回る量が減り、トウモロコシの価格が上がりやすくなる。トウモロコシは家畜の飼料に多く使われるので、飼料代が上がって肉や卵・乳製品の価格も上がりやすくなり、輸入にたよる国や貧しい人々の食料の確保が難しくなるおそれがある。', exp: 'バイオエタノールは、植物を発酵させてつくるアルコール燃料です。燃やしても、植物が育つときに吸収した二酸化炭素を大気にもどすだけだと考えられるため、地球温暖化対策として広まりました。\nしかし、アメリカではトウモロコシ、ブラジルではさとうきびが主な原料で、食料や飼料と原料をうばい合う関係になります。トウモロコシの需要が増えると価格が上がり、それを飼料にする畜産物の価格にも影響が広がります。\n「環境によい」ことと「食料の安定」が対立しうる例として、食料の問題と環境の問題を結びつけて説明できるようにしておきましょう。' }
    ],
    faq: [
      ['「緑の革命」と「遺伝子組換え作物」は同じもの?', 'ちがいます。【緑の革命】は、1960年代ごろから、交配をくり返してつくった収量の多い小麦や米の品種を、化学肥料や灌漑とセットで途上国に広めた取り組みです。\n【遺伝子組換え作物】は、ほかの生物の遺伝子を直接組みこんで、害虫に強い・除草剤に強いといった性質をもたせた作物です。どちらも収量の増加をめざしますが、品種を改良する方法がちがいます。'],
      ['チューネンのモデルは、現実の農業の分布をそのまま説明できるの?', 'そのままでは説明できません。チューネンは、土地の条件がどこも同じで、市場が1つだけ、輸送手段も1つという単純な「孤立国」を仮定しました。\n現実には、気候・地形・土壌のちがい、複数の市場、鉄道や高速道路、冷凍輸送などがあるので、分布は同心円になりません。それでも、「市場からの距離と輸送費が土地の使い方を決める」という考え方は、今でも農業や都市の土地利用を考える基本になっています。']
    ]
  });

  add('gg_industry', {
    secs: [
      { h: 'さらに深く:工場はなぜ集まるのか──集積の利益と「集まりすぎ」の不利益', t: 'ウェーバーの工業立地論では、輸送費と労働費のほかに、もう一つ工場の場所を左右する力が考えられています。それが【集積の利益】です。同じ業種や関連する工場が1か所に集まることで、1つひとつの工場が得をするしくみです。\n集積の利益には、次のようなものがあります。\n①部品や材料をつくる工場が近くにあるので、輸送の費用と時間を節約できる。\n②技術や情報が人の行き来を通じて伝わりやすく、新しい工夫が生まれやすい。\n③その仕事に慣れた労働者が地域に集まり、人を集めやすい。\n④道路・港・電力・用水などの設備を共同で使える。\n典型例が【自動車工業】です。自動車は数万点もの部品からできており、組み立て工場のまわりに多くの部品工場が集まります。愛知県の豊田市周辺のように、自動車会社を中心とした工業地域ができるのはこのためです。また、アメリカのシリコンヴァレーでは、大学や研究所、新しい会社に投資する資金、技術者が集まることで、情報通信産業の一大集積地になりました。\n一方で、集まりすぎると、地価や賃金が上がる、道路が渋滞する、公害や水不足が起こる、といった【集積の不利益】が生まれます。すると、工場は地価や賃金の安い地方や海外へ移ります(分散)。工業の立地は、この「集まる力」と「散らばる力」の綱引きの中で変化していくのです。', key: '工場は集まることで費用を下げ、技術を高め合う(集積の利益)。しかし集まりすぎると地価や渋滞などの不利益が生じ、分散が起こる。', ex: [{ q: '愛知県の豊田市とその周辺には、自動車の組み立て工場のまわりに多くの部品工場が集まっている。部品工場が組み立て工場の近くに立地する理由を、自動車会社の生産方式と結びつけて説明しよう。', hint: '組み立て工場が、部品をどのように受けとっているかを考えます。', steps: ['自動車は部品の数がとても多く、組み立て工場は毎日大量の部品を必要とする。', '日本の自動車会社の多くは、必要な部品を、必要なときに、必要な量だけ届けてもらい、在庫をできるだけ持たない生産方式(ジャストインタイム方式)をとってきた。', 'この方式では、部品を1日に何回も、決められた時刻に正確に届ける必要がある。', 'そのためには、部品工場が組み立て工場のすぐ近くにあるほうが、輸送の時間が短く確実で、輸送費も安い。'], a: '在庫を減らすため、必要な部品を必要なときに必要な量だけ届けるジャストインタイム方式をとっているので、部品を短い時間で確実に届けられるよう、部品工場が組み立て工場の近くに集まるから。', check: '倉庫に大量の部品を置かなくてよいので、組み立て工場は保管の費用やスペースを節約できます。部品工場の側も、決まった取引先の近くにいることで安定した注文を得られ、双方に利益があることが確かめられます。' }] },
      { h: '実戦演習:製品の「どの工程」をどこで行うか──国際分業とスマイルカーブ', t: '現代の工業では、1つの製品の工程が、いくつもの国に分かれて行われることがふつうです。この国際分業を考えるときに役立つのが【スマイルカーブ】という考え方です。\n製品ができるまでの工程を左から順に、「研究開発・設計」→「部品の生産」→「組み立て」→「販売・アフターサービス・ブランド」と並べ、それぞれの工程で生まれる付加価値(もうけ)の大きさをグラフにすると、両はしが高く、真ん中の組み立てが低い、笑った口のような形になります。\n研究開発やブランドはまねされにくく、組み立ては多くの国でできて競争がはげしいからです。\nそのため、先進国の企業は研究開発や設計・ブランドに力を入れ、組み立ては賃金の安い国の工場にまかせることが多くなります。解くときは、各工程に必要な条件(技術者か、安い労働力か)を考えましょう。落とし穴は、「工場がある国が、その製品で一番もうけている」と考えてしまうことです。', key: '付加価値は研究開発とブランドで大きく、組み立てで小さい。工程ごとに必要な条件がちがうので、工程が国をこえて分かれる。', ex: [{ q: 'ある先進国の企業Xは、スマートフォンを自社で設計し、自社のブランドで世界中に販売しているが、自社の工場は持たず、組み立てはアジアの別の国の企業Yの工場にまかせている。(1)XとYのうち、製品1台あたりのもうけが大きいと考えられるのはどちらか。(2)Yのある国が、今後さらに経済を発展させるために、どのような方向をめざすと考えられるか。', hint: 'スマイルカーブで、XとYがそれぞれどの位置の工程を担当しているかを考えます。', steps: ['Xは、カーブの左はしの研究開発・設計と、右はしの販売・ブランドを担当している。どちらも付加価値の大きい工程である。', 'Yは、カーブの底にあたる組み立てを担当している。組み立ては多くの国でできるため競争がはげしく、付加価値は小さい。', 'よって(1)は、Xのほうが1台あたりのもうけが大きいと考えられる。', '(2)Yの国が組み立てだけを続けると、賃金が上がったときに、より賃金の安い国に仕事をうばわれるおそれがある。', 'そこで、部品の開発や設計、自国のブランドづくりなど、カーブの両はしの工程へ進出することをめざすと考えられる。'], a: '(1)X(研究開発・設計とブランドを担当しているため) (2)組み立てだけでなく、部品の開発・設計や独自ブランドの製品づくりなど、付加価値の大きい工程に進出することをめざす。', check: '韓国や台湾の企業が、組み立ての受託から出発して、半導体の開発や自社ブランドの家電・スマートフォンへと進んできた歩みは、このカーブを左右に登っていく動きとして説明できます。' }] }
    ],
    drill: [
      { lv: 2, q: '必要な部品を、必要なときに、必要な量だけ届けてもらい、在庫をできるだけ持たないようにする生産方式を何という?', a: 'ジャストインタイム方式(かんばん方式)', exp: '日本の自動車会社が生み出した生産方式で、部品の在庫を最小限にして、保管の費用やむだをなくすことをめざします。部品の注文に「かんばん」とよばれる札を使ったことから、かんばん方式ともよばれます。\nこの方式は、部品工場が組み立て工場の近くに集まる理由(集積)の一つにもなっています。\nなお、「ジャスト・イン・タイム」は、日常のことばとしては「ちょうど間に合って」という意味でも使われます。生産方式の名前としては、「必要なときに必要な分だけ」という意味だと理解しておきましょう。' },
      { lv: 3, q: 'ジャストインタイム方式には、どのような弱点があるか。大きな自然災害が起きた場合を例にして説明しよう。', a: '部品の在庫をほとんど持たないので、災害で一つの部品工場や輸送路が止まると、部品が届かなくなり、遠く離れた地域の組み立て工場まで生産を止めなければならなくなる。2011年の東日本大震災では、被災地の部品工場が操業を停止したことで、全国の自動車工場の生産が止まった。', exp: '在庫を持たないことは、ふだんは効率のよさにつながりますが、部品の流れ(サプライチェーン)が一か所でも切れると、すぐに生産全体が止まってしまうという弱点になります。\n東日本大震災では、被災した地域にあった半導体などの部品工場が止まり、その部品を使う工場が国内外で生産を減らしました。その後、企業は部品の調達先を複数にする、一定の在庫を持つ、といった対策を進めています。\n「効率」と「災害への強さ」はしばしば対立します。答えるときは、利点と弱点の両方を示すと説得力が増します。' },
      { lv: 3, q: '2000年代後半から、アメリカでは「シェール革命」とよばれる変化が起こった。シェール革命とは何か、またそれがアメリカのエネルギーの輸出入にどのような変化をもたらしたかを説明しよう。', a: '地下深くの頁岩(シェール)層にふくまれる天然ガスや原油を、水圧で岩に割れ目をつくる技術などによって大量に採掘できるようになったこと。その結果、アメリカの天然ガス・原油の生産が大きく増え、エネルギーの輸入が減り、天然ガス(液化天然ガス)などを輸出する国へと変わった。', exp: 'シェール(頁岩)は、泥が固まってできた、うすくはがれやすい岩石です。その中にも天然ガスや原油がふくまれていましたが、すき間が小さいため、以前は取り出すのが難しく、採算がとれませんでした。\n地中で横向きに井戸を掘る技術や、高い水圧で岩に細かい割れ目をつくる技術が進んだことで、大量に採掘できるようになりました。これにより、アメリカは世界最大級の原油・天然ガスの生産国になり、エネルギーを輸入にたよる国から、輸出もする国へと変わりました。\n一方で、地下水の汚染や、大量の水の使用などの環境問題も指摘されています。' }
    ],
    faq: [
      ['「労働集約型」と「資本集約型」の工業は、どうちがうの?', '【労働集約型】は、生産にかかる費用のうち人件費の割合が大きい工業で、衣類の縫製や電気製品の組み立てなどが例です。人手が多く必要なので、賃金の安い国や地域に立地しやすくなります。\n【資本集約型】は、大きな機械や設備にお金がかかる工業で、鉄鋼・石油化学・半導体などが例です。人件費の差より、設備を動かす技術や電力・用水、港などの条件が重視されます。'],
      ['日本の自動車会社が、アメリカや中国など販売する国に工場をつくるのはなぜ?', '理由はいくつかあります。①日本から大量に輸出すると相手国の産業と対立し、貿易摩擦が起こりやすい。②販売する国でつくれば、輸送費や関税がかからない。③円高になっても、現地で生産・販売すれば影響を受けにくい。④その国の人々の好みや道路の事情に合わせた車をつくりやすい。\n1980年代の日米の貿易摩擦をきっかけに、日本の自動車会社のアメリカでの現地生産が本格的に進みました。']
    ]
  });

  add('gg_pop', {
    secs: [
      { h: 'さらに深く:出生率が下がっても、人口はすぐには減らない──人口の「慣性」', t: '合計特殊出生率が約2.1(人口置換水準)を下回ると、長い目で見れば人口は減っていきます。ところが、出生率が下がったその年から人口が減り始めるわけではありません。人口には、走っている自転車が急には止まれないような【慣性】(人口モメンタム)があるのです。\n生まれる子どもの数は、「1人の女性が産む子どもの数」だけでなく、「子どもを産む年代の女性が何人いるか」で決まります。若い世代が多い国では、1人あたりの子どもの数が減っても、親になる人の数が多いので、生まれる子どもの総数はしばらく多いままです。さらに、高齢者が少ないので死亡数も少なく、人口は増え続けます。\n日本では、合計特殊出生率が1970年代半ばに人口置換水準を下回りました。しかし、総人口が減り始めたのは、それから30年以上たった2000年代後半です。第2次ベビーブームの世代など、親になる世代が多かったことや、平均寿命がのびて死亡数が少なかったことが理由です。\nこの慣性は、逆向きにも働きます。少子化が長く続いて親になる世代そのものが少なくなると、たとえ出生率が回復しても、生まれる子どもの総数はすぐには増えません。少子化対策が「早く始めるほど効果が大きい」といわれるのは、このためです。', key: '生まれる子どもの数=1人あたりの出生数×親になる世代の人数。人口構成のために、出生率の変化が人口の増減にあらわれるまでには長い時間がかかる。', ex: [{ q: 'A国とB国は、どちらも合計特殊出生率が1.8である。A国は20〜30歳代の人口が多く高齢者が少ない。B国は20〜30歳代の人口が少なく高齢者が多い。今後10年間の総人口の動きについて、どのような予想ができるか。', hint: '出生数は「親になる世代の人数」に、死亡数は「高齢者の人数」に大きく左右されます。', steps: ['どちらの国も出生率は人口置換水準(約2.1)を下回っているので、長い目で見ればどちらも人口は減る方向にある。', 'A国は親になる世代が多いので、出生数は多い。また高齢者が少ないので死亡数は少ない。', 'そのためA国では、当面は出生数が死亡数を上回り、人口が増え続ける可能性がある。', 'B国は親になる世代が少なく出生数が少ないうえ、高齢者が多く死亡数が多いので、人口がすでに減っているか、すぐに減り始めると予想できる。'], a: 'A国は出生率が低くても当面は人口が増え続ける可能性があり、B国は人口の減少がすでに始まっているか、まもなく始まると考えられる。どちらも長期的には減少に向かう。', check: '出生率が同じでも、人口ピラミッドの形によって数年〜数十年の動きが大きくちがうことがわかります。人口の予想には、出生率と人口ピラミッドの両方が必要です。' }] },
      { h: '実戦演習:昼夜間人口比率から都市の性格を読む', t: '都市の性格を判定する問題では、【昼夜間人口比率】がよく使われます。\n・昼間人口=夜間人口(そこに住む人)+通勤・通学で入ってくる人−通勤・通学で出ていく人\n・昼夜間人口比率=昼間人口÷夜間人口×100\n比率が100より大きい都市は、働く場所や学校が多く、まわりから人が集まる都市です。逆に100より小さい都市は、住民の多くがほかの都市に通勤・通学する【住宅都市(衛星都市)】の性格をもちます。\n解くときは、まず入ってくる人と出ていく人を正しく足し引きし、比率が100の上か下かを確かめます。そのうえで、人口の増減(自然増減・社会増減)や、年齢構成など、ほかの指標と組み合わせて判断します。\nよくある落とし穴は、「人口が多い都市=昼夜間人口比率が高い都市」と考えることです。比率は人口の多さではなく、「人の流れの向き」を表す指標なのです。', key: '昼夜間人口比率は「人の流れの向き」を表す。100より大きければ人が集まる都市、小さければ住宅都市。', ex: [{ q: 'ある都市Pの夜間人口は50万人である。通勤・通学で、ほかの都市からPへ12万人が入り、Pからほかの都市へ3万人が出ていく。Pの昼間人口と昼夜間人口比率を求め、Pの性格を答えよう。', hint: '入ってくる人は足し、出ていく人は引きます。', steps: ['昼間人口=夜間人口+入ってくる人−出ていく人。', '50万+12万−3万=59万人。', '昼夜間人口比率=59万÷50万×100=118。', '比率が100より大きいので、まわりの地域から通勤・通学する人が集まる、仕事や学校の多い中心的な都市である。'], a: '昼間人口59万人、昼夜間人口比率118。まわりから人が集まる中心的な都市。', check: '入ってくる人と出ていく人の差(12万−3万=9万人)が、夜間人口50万人の18%にあたることから、比率が100+18=118になることでも確かめられます。' }, { q: '大都市Qの郊外にある都市Rは、昼夜間人口比率が80で、この10年ほど人口が増えている。人口の増加は主に転入によるもので、転入してくる人の多くは30〜40歳代の子育て世帯である。Rはどのような性格の都市と考えられるか。また、将来どのような課題が生じうるか。', hint: '比率が100を下回ることと、転入してくる人の年代に注目します。', steps: ['昼夜間人口比率が80と100を下回るので、住民の多くが昼間はほかの都市(主に大都市Q)へ通勤・通学している。', '転入による人口増加(社会増加)なので、大都市Qで働く人が、住宅を求めて移り住んできていると考えられる。', 'よってRは、大都市のベッドタウンにあたる住宅都市(衛星都市)である。', '同じ年代の世帯が一度に転入しているので、数十年後には住民がいっせいに高齢化し、学校の空き教室や、高齢者向けの医療・交通の不足などの課題が生じうる。'], a: '大都市Qに通勤する人々が住む住宅都市(衛星都市・ベッドタウン)。将来、同じ世代の住民がいっせいに高齢化し、子どもの減少や高齢者を支えるサービスの不足が課題になりうる。', check: '高度経済成長期に開発された大都市郊外のニュータウンでは、実際に住民の高齢化と建物の老朽化が同時に進む問題が起きています。人口ピラミッドの「ふくらみ」が時間とともに上へ移る、という考え方とも一致します。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある都市の夜間人口は20万人で、通勤・通学で2万人が入ってきて、6万人が出ていく。この都市の昼夜間人口比率を求め、都市の性格を答えよう。', a: '昼間人口は20万+2万−6万=16万人で、昼夜間人口比率は80。住民の多くがほかの都市へ通勤・通学する住宅都市(衛星都市)の性格をもつ。', exp: '昼間人口は、夜間人口に入ってくる人を足し、出ていく人を引いて求めます。20万+2万−6万=16万人です。比率は16万÷20万×100=80です。\n100を下回っているので、昼間はほかの都市へ出ていく人のほうが多い都市です。大都市の郊外にある住宅都市に多いパターンです。\n入ってくる人と出ていく人を逆に計算すると、20万−2万+6万=24万人(比率120)となり、正反対の結論になってしまいます。「入る=足す、出る=引く」を、式を書いて確かめる習慣をつけましょう。' },
      { lv: 3, q: '日本では、合計特殊出生率が1970年代半ばに人口置換水準を下回ったのに、総人口が減り始めたのは2000年代後半になってからだった。このように、人口の減少が大きくおくれて始まった理由を説明しよう。', a: '出生率が下がっても、第2次ベビーブームの世代など親になる年代の人口が多かったため、生まれる子どもの総数はしばらく多いままだった。また、平均寿命がのび、高齢者の数が比較的少なかったため死亡数も少なく、出生数が死亡数を上回る状態がしばらく続いたから。', exp: '出生数は「1人の女性が産む子どもの数」と「出産する年代の女性の数」のかけ算で決まります。出生率が下がっても、親になる世代の人数が多ければ、出生数はすぐには大きく減りません。\nまた、人口が減るかどうかは出生数と死亡数の差で決まります。医療の進歩で平均寿命がのびたことで、死亡数の増加もゆるやかでした。\nその後、親になる世代が少なくなり、高齢化で死亡数が増えると、出生数を死亡数が上回るようになり、人口が減り始めました。人口には「慣性」があることを、出生数と死亡数の両面から説明することがポイントです。' },
      { lv: 3, q: '人口全体にしめる生産年齢人口(15〜64歳)の割合が高まる時期は、経済の成長に有利だといわれる。その理由と、その時期が終わったあとに生じやすい問題を説明しよう。', a: '働く世代が多く、支えられる子どもや高齢者が相対的に少ないので、労働力が豊富で、所得のうち貯蓄や投資に回るお金が増え、経済が成長しやすい(人口ボーナス)。その後、この世代が高齢になると、働く世代の割合が下がって高齢者の割合が上がり、労働力不足や年金・医療などの社会保障の負担の増加が問題になる(人口オーナス)。', exp: '出生率が下がり始めた直後の国では、子どもが減る一方で、それ以前に生まれた多くの世代が働く年齢になります。働く人が多く、養う家族が比較的少ないこの時期を【人口ボーナス】とよび、日本の高度経済成長期や、その後の中国・東南アジアの急成長の背景の一つとされます。\nしかし、その世代が高齢になると、働く人1人あたりが支える高齢者の数が増えます。これを、負担を意味する英語から【人口オーナス】とよびます。\n「ボーナス」はずっと続くものではなく、少子化が進むほど、後に大きなオーナスがやってくるという関係を押さえておきましょう。' }
    ],
    faq: [
      ['過疎は、なぜ一度始まると止まりにくいの?', '若い人が仕事や進学で都市へ出ていくと、地域で生まれる子どもが減り、高齢化が進みます。人口が減ると、バスの路線や商店、病院、学校などが利用者不足で維持できなくなります。すると暮らしがさらに不便になり、残っていた人も出ていく、という【悪循環】が起こります。\nそのため、過疎の対策では、移住者の受け入れや仕事づくりに加えて、生活に必要なサービスを小さな拠点に集めるなど、悪循環のどこかを断ち切る工夫が求められています。'],
      ['人口密度が高い国は、貧しい国なの?', 'そうとは限りません。バングラデシュのように人口密度が高く、所得の低い国もありますが、オランダやシンガポール、韓国のように、人口密度が高くても豊かな国もあります。\n豊かさを左右するのは、人口密度そのものよりも、産業の発展、教育、技術、政治の安定などです。むしろ人が集まって住むと、交通や情報のやりとりが効率的になり、経済活動に有利になる面もあります。']
    ]
  });

  add('gg_region', {
    secs: [
      { h: 'さらに深く:輸入代替から輸出指向へ──アジアの工業化の道すじ', t: '第二次世界大戦後に独立した多くの国は、まず【輸入代替工業化】という道を選びました。それまで外国から輸入していた工業製品を、高い関税などで輸入をおさえながら、自分の国でつくろうとする方法です。\nしかし、この方法はやがて行きづまりやすくなります。国内の市場が小さいと大量生産ができず、製品が割高になります。さらに、関税で守られて外国との競争がないため、品質や効率を高める努力が進みにくいのです。\nそこで、1960年代ごろから韓国・台湾・香港・シンガポールは、【輸出指向工業化】に切りかえました。外国の企業や資金を受け入れ、【輸出加工区】などで安い労働力を生かして製品をつくり、世界の市場に輸出する方法です。世界という大きな市場を相手にするので大量生産ができ、競争の中で技術も高まりました。これらの国・地域は急速に工業化し、【NIEs】とよばれるようになりました。\n1985年のプラザ合意の後、円高が進むと、日本の企業はタイやマレーシアなどのASEANの国々に工場を移し、これらの国々も輸出指向の工業化を進めました。さらに、改革開放政策を進めた中国や、ドイモイ(刷新)政策を進めたベトナムがこれに続きました。\nこのように、工業化が先に進んだ国から、賃金の安い国へと、産業が順番に移っていく様子は、雁が列をつくって飛ぶ姿にたとえて【雁行形態】とよばれます。', key: '国内市場向けの輸入代替は行きづまりやすく、世界市場向けの輸出指向に切りかえた国が急成長した。産業は先に発展した国から後の国へ順に移っていく(雁行形態)。', ex: [{ q: '輸入代替工業化よりも、輸出指向工業化のほうが、小さな国の経済成長につながりやすかったのはなぜか。「市場」と「競争」の2語を使って説明しよう。', hint: 'どちらの方法で、だれに向けて製品を売っているかを比べます。', steps: ['輸入代替工業化は、自国の市場に向けて製品をつくる。国が小さいと市場も小さく、大量生産によって費用を下げることが難しい。', 'また、高い関税で外国製品から守られているので、競争がなく、品質や効率を高める必要がうすい。', '輸出指向工業化は、世界の市場に向けて製品をつくるので、国が小さくても大量生産ができる。', 'さらに、世界の企業と競争しなければ売れないので、技術や品質を高める努力が進む。'], a: '輸出指向工業化は、小さな国内市場ではなく世界という大きな市場を相手にするので大量生産で費用を下げられ、また外国企業との競争にさらされることで技術や品質が高まったから。', check: 'シンガポールや香港のように、人口が少ない国・地域ほど、国内市場だけでは工業化が難しく、輸出指向に早く切りかえた、という事実とも一致します。' }] },
      { h: '実戦演習:言語・民族・輸出品の組み合わせでラテンアメリカの国を判定する', t: 'ラテンアメリカの国の判定では、次の3つの手がかりを組み合わせます。\n①【言語】:ほとんどの国はスペイン語ですが、ブラジルはポルトガル語です。これだけでブラジルが特定できることがあります。\n②【民族構成】:アルゼンチンやウルグアイはヨーロッパ系の住民が多数をしめます。メキシコやコロンビアなどは先住民とヨーロッパ系の混血である【メスチーソ】が多く、ペルーやボリビアなどアンデス山脈の国々は先住民の割合が高めです。\n③【輸出品】:チリは銅、アルゼンチンはパンパでつくられる小麦・大豆・牛肉、ブラジルは大豆・鉄鉱石・原油などが代表的です。\n落とし穴は、1つの手がかりだけで決めてしまうことです。たとえば「大豆の輸出が多い」だけでは、ブラジルかアルゼンチンか決まりません。言語や民族構成など、もう1つの手がかりで確かめましょう。', key: '言語でブラジルを、民族構成でアルゼンチンやアンデスの国を、輸出品でチリなどを見分ける。必ず2つ以上の手がかりで確かめる。', ex: [{ q: '次のA〜Cは、アルゼンチン・チリ・ブラジルのいずれかの説明である。それぞれどの国か。\nA 公用語はポルトガル語で、大豆や鉄鉱石、原油などを輸出している。\nB 公用語はスペイン語で、細長い国土をもち、輸出額の多くを銅鉱や銅がしめる。\nC 公用語はスペイン語で、ヨーロッパ系の住民が多数をしめ、温帯の草原で小麦や大豆、牛肉を生産・輸出している。', hint: 'まず言語で1つ、次に輸出品と民族構成で残りを見分けます。', steps: ['Aは公用語がポルトガル語なので、ラテンアメリカで唯一のポルトガル語の大国、ブラジル。', 'Bは銅への依存が大きく、国土が南北に細長いので、アンデス山脈ぞいに銅山が多いチリ。', 'Cは温帯の草原(パンパ)での農牧業と、ヨーロッパ系の住民の多さから、アルゼンチン。', 'それぞれ別の国になり、矛盾がないことを確かめる。'], a: 'A ブラジル B チリ C アルゼンチン', check: 'Aの大豆はCにもあてはまりますが、言語のちがいでブラジルと決まります。1つの手がかりだけでは決まらないことを確かめておきましょう。' }, { q: 'アルゼンチンでは、ヨーロッパ系の住民が人口の多数をしめている。その理由を、自然環境と移民の歴史から説明しよう。', hint: 'アルゼンチンの主な地域の気候と、19世紀後半からの開発を思い出しましょう。', steps: ['アルゼンチンの中心部は、温帯の草原であるパンパが広がり、ヨーロッパと似た気候である。', 'この地域には、アンデス山脈の国々のように大きな先住民の国家がなく、先住民の人口はもともと多くなかった。', '19世紀後半から、パンパの開発が進み、小麦や牛肉をヨーロッパへ輸出するようになると、多くの労働者が必要になった。', 'そこで、イタリアやスペインなどから多くの移民が渡ってきて定住したため、ヨーロッパ系の住民が多数をしめるようになった。'], a: 'パンパはヨーロッパに似た温帯の気候で、もともと先住民の人口が多くなかった。19世紀後半から農牧業の開発が進むと、イタリアやスペインなどから多くの移民が入植したため、ヨーロッパ系の住民が多数となった。', check: '同じ温帯の新大陸であるアメリカ合衆国・カナダ・オーストラリアでも、ヨーロッパからの入植者が多数をしめています。「温帯の新大陸=ヨーロッパ系の入植が多い」という共通点で確かめられます。' }] }
    ],
    drill: [
      { lv: 2, q: 'ブラジルには、日本からの移民とその子孫(日系人)が多く住んでいる。日本からブラジルへの移民が始まった時期と、移民の多くがついた仕事を答えよう。', a: '1908年に最初の移民船(笠戸丸)が到着し、移民の多くはコーヒー農園の労働者として働いた。', exp: 'ブラジルでは、19世紀末に奴隷制が廃止されると、コーヒー農園で働く労働者が不足しました。一方、日本では農村の人口が多く、海外に仕事を求める人がいました。こうして1908年、最初の移民を乗せた笠戸丸がサントスの港に着きました。\nその後も多くの日本人が渡り、ブラジルは世界でも日系人が特に多い国となりました。サンパウロには日本人街もあります。\n1990年代以降は逆に、日系ブラジル人が日本に働きに来るようになり、群馬県や静岡県・愛知県などの工業都市に多く住んでいます。人の移動が双方向に起こってきたことも押さえておきましょう。' },
      { lv: 3, q: '工業化が先に進んだ国から、賃金の安い国へと、産業が順番に移っていく様子を何というか。また、その例を、繊維・電気機械などの産業の移り変わりをもとに説明しよう。', a: '雁行形態。例:繊維や雑貨などの労働集約的な産業は、日本からまずNIEs(韓国・台湾など)へ、さらにASEANの国々や中国へと移った。NIEsはその後、電気機械や半導体などの技術の高い産業へと移っていった。', exp: '雁行形態は、日本の経済学者が示した考え方で、雁が列をつくって飛ぶように、各国の産業が順番に高度化していくようすを表しています。\n賃金が上がった国では、人手の多くかかる産業が競争力を失い、より賃金の安い国へ移ります。移った先の国は、その産業で工業化を始め、技術を高めると、次の段階の産業へ進みます。\nただし、近年は中国のように、労働集約的な産業から最先端の技術産業までを同時に発展させる国もあり、いつも順番どおりに移るとは限りません。「おおまかな傾向」として理解しておきましょう。' },
      { lv: 3, q: 'シンガポールは、国土がせまく天然資源もほとんどないが、一人あたりの所得が世界でも高い水準にある。その理由を、位置と政策の面から説明しよう。', a: 'マラッカ海峡の出入り口という海上交通の要所にあり、中継貿易の港として発展した。さらに、外国企業を積極的に受け入れて輸出指向の工業化を進め、その後は金融・物流・情報通信などのサービス業や、高い技術の産業にも力を入れ、国際的な拠点となったから。', exp: 'シンガポールは、インド洋と南シナ海を結ぶマラッカ海峡の南の出入り口にあり、昔から東西を結ぶ船の中継地でした。この位置を生かして、周辺国の産品を集めて世界へ送る【中継貿易】で栄えました。\n1965年にマレーシアから分離・独立した後は、資源がない国が生き残る道として、外国企業の工場を呼びこむ輸出指向工業化を進めました。英語が広く使われることも、外国企業にとって魅力でした。\nさらに、国際金融や港湾・空港の物流拠点、多国籍企業の地域本部などのサービス業を育てました。資源がなくても、位置・人材・制度を生かせば豊かになれる例として理解しましょう。' }
    ],
    faq: [
      ['BRICSとは、どんな国のグループなの?', '経済成長が著しく、人口や国土の大きい新興国の頭文字をとったよび名です。はじめはブラジル(B)・ロシア(R)・インド(I)・中国(C)の4か国を指して2000年代に広まり、2010年代に南アフリカ共和国(S)が加わりました。\nその後、首脳会議をもつ枠組みとして、2020年代には参加国がさらに広がっています。先進国中心の国際秩序に対して、新興国が発言力を強めようとする動きの一つとして注目されています。'],
      ['モノカルチャー経済の国は、どうすればそこから抜け出せるの?', '輸出品の種類を増やす【多角化】が基本です。たとえばマレーシアは、かつて天然ゴムとすずの輸出にたよっていましたが、油やしの栽培を広げ、さらに外国企業を受け入れて電気機械などの工業化を進めることで、特定の産品への依存を減らしました。\nそのためには、教育による人材の育成、道路や港・電力の整備、政治の安定などが欠かせません。資源の収入を、こうした将来への投資に回せるかどうかが分かれ目になります。']
    ]
  });

  add('gg_disaster', {
    secs: [
      { h: 'さらに深く:台風の「右側」はなぜ危ないのか──風と高潮のしくみ', t: '台風は、北西太平洋などで発生する熱帯低気圧が発達したもので、中心に向かって風がふきこみます。北半球では、地球の自転の影響で、風は中心のまわりを【反時計回り】にうずをまくようにふきこみます。\n台風は、うずをまきながら全体として移動します。そのため、進む方向の【右側】では、うずの風の向きと台風が進む向きが同じになり、2つの速さが足し合わされて風が特に強くなります。左側では向きが逆になるので、右側よりは風が弱くなります。台風の右側を【危険半円】とよぶのはこのためです。\n台風は高潮も引き起こします。高潮には2つの原因があります。1つは【吸い上げ効果】です。気圧が1hPa下がると、海面はおよそ1cm持ち上がります。まわりが1010hPaのときに中心気圧が950hPaの台風が来れば、中心付近の海面は約60cm上がる計算です。もう1つは【吹き寄せ効果】で、海から陸に向かう強い風が海水を海岸に押しつけます。\n吹き寄せ効果は、湾の形と台風のコースで大きく変わります。南に向かって開いた湾では、台風が湾の【西側】を北上すると、湾は台風の右側に入り、強い南寄りの風が湾の奥へ海水を押しこみます。1959年の伊勢湾台風では、台風が伊勢湾の西側を北上したため、湾の奥の名古屋市周辺などで大きな高潮が発生し、死者・行方不明者は5000人をこえました。', key: '台風の進む方向の右側は、うずの風と移動の速さが重なって風が強い。高潮は吸い上げ(1hPaで約1cm)と吹き寄せで起こり、湾の西側を北上する台風が特に危険。', ex: [{ q: '中心気圧が960hPaの台風が近づいている。まわりの気圧は1010hPaである。吸い上げ効果だけで、中心付近の海面はおよそ何cm上がるか。また、実際の高潮がこれより大きくなるのはなぜか。', hint: '気圧が1hPa下がると、海面は約1cm上がります。', steps: ['まわりの気圧との差は 1010−960=50hPa。', '1hPaあたり約1cm上がるので、50hPaで約50cm上がる。', 'しかし実際の高潮では、強風が海水を海岸に押しつける吹き寄せ効果が加わる。', '吹き寄せ効果は、遠浅の海や、風の向きに開いた湾の奥で特に大きくなり、満潮の時刻と重なるとさらに潮位が高くなる。'], a: '約50cm。実際には、強い風による吹き寄せ効果が加わり、湾の形や満潮の時刻によってはさらに大きくなるから。', check: '吸い上げだけなら数十cmですが、過去の大きな高潮では潮位が数mに達しています。吹き寄せや満潮との重なりが大きく影響することが、数字の差からもわかります。' }] },
      { h: '実戦演習:台風のコースと火山灰の行方を、風の向きで推理する', t: '防災の問題では、「どこで・どんな被害が大きくなるか」を、風の向きから推理させる問題がよく出ます。\n台風の問題では、まず【台風の進む向き】を確かめ、その右側と左側を決めます。北上する台風なら、東側が右側(危険半円)です。次に、湾の開いている向きと、台風が来たときにふく風の向きを比べます。海から湾の奥に向かって風がふくと、高潮が大きくなります。北半球の反時計回りのうずでは、台風の中心の東側で南寄りの風、西側で北寄りの風がふくことを、図をかいて確かめましょう。\n火山の問題では、【上空の風】に注目します。日本の上空には1年中【偏西風】がふいているので、噴火で高く上がった火山灰は、主に火山の【東側】へ運ばれて降り積もります。\n落とし穴は、地上の風や、そのときの季節風だけで考えてしまうことです。また、南半球ではうずの向きが逆になることにも注意が必要です。', key: '北上する台風は東側(右側)が危険。湾の奥に向かって風がふくと高潮が大きくなる。火山灰は偏西風で東へ運ばれる。', ex: [{ q: '南に向かって開いた湾がある。台風が(ア)湾の西側を北上する場合と、(イ)湾の東側を北上する場合とで、湾の奥の高潮が大きくなりやすいのはどちらか。理由も答えよう。', hint: '反時計回りのうずで、中心の東側と西側でどんな向きの風がふくかを考えます。', steps: ['北半球の台風では、風は中心のまわりを反時計回りにふきこむ。そのため中心の東側では南寄りの風、西側では北寄りの風がふく。', '(ア)台風が湾の西側を通ると、湾は台風の中心の東側に入る。南寄りの強い風が、南に開いた湾の入り口から奥へ向かってふく。', 'さらに、北上する台風の東側は進む方向の右側(危険半円)なので、風がいっそう強い。', '(イ)台風が湾の東側を通ると、湾は中心の西側に入り、北寄りの風が湾の奥から外へ向かってふくので、海水は湾の外へ押し出されやすい。'], a: '(ア)。湾が台風の右側(危険半円)に入り、強い南寄りの風が湾の奥へ向かって海水を押しこむため、吹き寄せ効果が大きくなるから。', check: '1959年の伊勢湾台風は、伊勢湾の西側を北上し、湾の奥で大きな高潮を起こしました。実際の災害の経過とも一致します。' }, { q: '1707年の富士山の宝永噴火では、火山から約100km離れた江戸にも火山灰が降った。もし今、富士山が大規模に噴火した場合、火山灰はおもにどの方向に広がると考えられるか。また、都市でどのような被害が考えられるか。', hint: '火山灰が上がる上空にふいている風を考えます。', steps: ['噴火で上空高く上がった火山灰は、上空の風に流されて広がる。', '日本の上空には1年中、西から東へ偏西風がふいている。', 'そのため、富士山の火山灰は主に東側、つまり神奈川県や東京都などの首都圏の方向へ広がると考えられる。', '火山灰が積もると、鉄道や道路が使えなくなる、航空機が飛べなくなる、電線や変電設備に付着して停電が起こる、水道の浄水に支障が出る、雨にぬれると重くなり建物に負担がかかる、などの被害が考えられる。'], a: '偏西風によって主に東側の首都圏の方向へ広がる。交通のまひ(鉄道・道路・航空)、停電、断水、建物への負担、健康被害などが考えられる。', check: '宝永噴火で江戸に灰が降ったのも、富士山の東にあたるからです。ただし、噴火の時期によって風の強さや向きは少し変わるので、ハザードマップでは複数の場合が想定されています。' }] }
    ],
    drill: [
      { lv: 2, q: 'まわりの気圧が1010hPaのとき、中心気圧970hPaの台風が近づいた。吸い上げ効果だけを考えると、中心付近の海面はおよそ何cm上がるか。', a: '約40cm', exp: '吸い上げ効果は、気圧が下がって海面を押さえつける力が弱まり、海面が持ち上がる現象です。気圧が1hPa下がるごとに、海面はおよそ1cm上がります。\n気圧の差は1010−970=40hPaなので、約40cmです。\n吸い上げ効果は、中心気圧が低い強い台風ほど大きくなります。ただし、実際の高潮は、これに強風による吹き寄せ効果や満潮が重なるので、もっと高くなることがあります。「高潮の原因=吸い上げだけ」と答えると不十分なので、2つの効果をセットで覚えておきましょう。' },
      { lv: 3, q: '北半球の台風で、進む方向の右側の風が左側より強くなるのはなぜか説明しよう。', a: '台風の風は中心のまわりを反時計回りにうずをまいてふいている。右側では、このうずの風の向きと台風全体が進む向きが同じになるので、2つの速さが足し合わされて風が強くなる。左側では向きが逆になって打ち消し合うので、右側より弱くなるから。', exp: 'たとえば、北へ進む台風を考えます。反時計回りのうずでは、中心の東側(右側)で風は南から北へ、西側(左側)では北から南へふきます。台風全体も北へ動いているので、東側では「うずの風+移動の速さ」、西側では「うずの風−移動の速さ」になります。\n動く歩道の上を、歩道と同じ向きに歩くと速く進み、逆向きに歩くと遅くなるのと同じしくみです。\n南半球では、うずの向きが時計回りになるので、進む方向の左側のほうが風が強くなります。「右側が危険」は北半球の場合だと覚えておきましょう。' },
      { lv: 3, q: '火山灰が数cm積もっただけでも、都市の生活には大きな影響が出るといわれる。その理由を、交通とライフラインの面から説明しよう。', a: '火山灰は細かくて重く、すべりやすいので、道路では車がスリップし、視界も悪くなる。鉄道では線路の信号や電気設備が誤作動して運行できなくなり、航空機はエンジンに吸いこむと故障するので飛べなくなる。また、電線や変電設備に付着した灰が雨でぬれると電気を通してショートし、停電が起こる。浄水場に灰が入ると水道も使えなくなるおそれがある。', exp: '火山灰は、ふつうの灰とはちがい、岩石やガラスの細かい粒です。水を吸うと重くなり、乾くと舞い上がります。\n交通では、道路の白線が見えなくなる、車がすべる、鉄道の信号やポイントが誤作動する、航空機のエンジンが損傷する、などの影響があります。ライフラインでは、停電や断水、通信の障害が心配されます。\n都市は多くのしくみが電気と交通に支えられているので、少しの灰でも影響が連鎖して広がります。火山から遠い都市でも備えが必要とされるのは、このためです。' }
    ],
    faq: [
      ['台風・ハリケーン・サイクロンは、何がちがうの?', 'どれも熱帯の海の上で発生して発達した熱帯低気圧で、しくみは同じです。発生する場所によってよび名が変わります。\n北西太平洋や南シナ海で発生したものが【台風】、北大西洋やカリブ海、北東太平洋のものが【ハリケーン】、インド洋や南太平洋のものが【サイクロン】です。日本の基準では、熱帯低気圧のうち最大風速がおよそ17m/s以上になったものを台風とよびます。'],
      ['南半球の台風(サイクロン)も、反時計回りにうずをまくの?', 'いいえ、南半球では【時計回り】にうずをまきます。地球の自転による見かけの力(コリオリの力)のはたらく向きが、北半球と南半球で逆になるためです。\nそのため南半球では、進む方向の左側で、うずの風と移動の速さが重なって風が強くなります。オーストラリアなどの南半球の災害を考えるときは、北半球の常識をそのまま使わないように注意しましょう。']
    ]
  });

  add('ri_seinen', {
    secs: [
      { h: 'さらに深く:道徳的な判断はどう発達するのか──コールバーグとギリガン', t: '青年期は、自分の生き方だけでなく、「何が正しいか」を自分の頭で考えはじめる時期でもあります。アメリカの心理学者【コールバーグ】は、人の道徳的な判断が、決まった順序で発達していくと考え、それを【3つの水準・6つの段階】に整理しました。\n【前慣習的水準】:段階1は「罰をさけるために従う」、段階2は「自分の得になるかどうか(ギブ・アンド・テイク)」で判断します。\n【慣習的水準】:段階3は「まわりの人から、よい人だと思われたい」、段階4は「法律や社会の秩序を守ることが大切だ」と考えます。\n【脱慣習的水準】:段階5は「法やルールは、人々の権利を守るための約束(社会契約)であり、よりよいものに変えることもできる」、段階6は「人間の尊厳のような、だれにでもあてはまる普遍的な原理」にもとづいて判断します。\nここで大切なのは、段階を決めるのは「どんな結論を出したか」ではなく、【なぜそう判断したかという理由】だということです。同じ「うそをつかない」でも、「しかられるから」なら段階1、「みんなの信頼を失うから」なら段階3にあたります。\nこれに対して、コールバーグのもとで研究した【ギリガン】は、この理論が主に男性を対象にした研究にもとづき、権利や公正を重んじる【正義の倫理】だけを高く評価していると批判しました。そして、身近な人とのつながりを大切にし、相手のニーズにこたえて傷つけないようにする【ケアの倫理】も、もう一つの成熟した道徳の声だと主張しました。', key: 'コールバーグの段階は「結論」ではなく「理由」で決まる。ギリガンは、正義の倫理だけでなく、関係と思いやりを重んじるケアの倫理を示した。', ex: [{ q: '「赤信号の横断歩道を、車が来ていなくても渡らない」と答えた生徒に理由を聞くと、「交通ルールは、みんなが安全に暮らせるように社会で決めた決まりだから、全員が守らないと社会の秩序がくずれる」と答えた。この理由は、コールバーグのどの段階にあたるか。', hint: '理由が「罰」「得」「人の目」「社会の秩序」「普遍的な原理」のどれを根拠にしているかを見ます。', steps: ['結論(渡らない)ではなく、理由に注目する。', '理由は「罰を受けるから」でも「自分の得になるから」でもないので、前慣習的水準(段階1・2)ではない。', '「まわりからよく思われたい」でもなく、「社会の秩序を守るためにルールは全員が守るべきだ」という理由である。', 'これは、法や社会の秩序の維持を重んじる、慣習的水準の段階4にあたる。'], a: '慣習的水準の段階4(法と社会秩序の維持を重んじる段階)', check: 'もし「ルールは人々の安全を守るための約束なので、もっとよいルールがあれば話し合って変えるべきだ」という理由なら、ルールを変えうるものとしている点で段階5になります。理由のちがいで段階が変わることを確かめましょう。' }] },
      { h: '実戦演習:理由の言いかえから発達の段階と立場を見分ける', t: '道徳性の発達の問題では、架空の人物の発言を読み、どの段階やどの立場にあたるかを判断させる形がよく出ます。\n戦略の1つめは、【発言を「結論」と「理由」に分ける】ことです。結論にまどわされず、理由の部分だけで判定しましょう。\n2つめは、【段階4と段階5の区別】です。「決まりだから守るべきだ」と、ルールそのものを守ることを重視していれば段階4、「ルールは人々の権利や幸福のための約束で、合意によって変えられる」と、ルールの目的から考えていれば段階5です。\n3つめは、【ギリガンの立場の見分け方】です。「だれの権利が優先されるか」「公平かどうか」という言い方は正義の倫理、「この人との関係を壊さないためにはどうするか」「相手が傷つかないためには」という言い方はケアの倫理にあたります。ギリガンは、ケアの倫理を「段階の低い考え方」とみなすことを批判した、という点も押さえておきましょう。', key: '結論ではなく理由で判定する。ルールを守ること自体が目的なら段階4、ルールの目的から考えるなら段階5。', ex: [{ q: '「友だちに借りたお金を、約束の日に返すべきか」という問いに、A〜Cの3人が「返すべきだ」と答えた。理由はそれぞれ次のとおりである。コールバーグの段階を低い順に並べよう。\nA 返さないと、次にお金を借りられなくなって自分が困るから。\nB 約束を守らないと、友だちやクラスのみんなから信用されなくなるから。\nC 約束を守ることは、相手を一人の人間として尊重することであり、だれに対してもそうすべきだから。', hint: 'それぞれの理由が、自分の得・まわりの評価・普遍的な原理のどれにあたるかを考えます。', steps: ['Aは「自分が困るから」という自分の利益を理由にしている。これは前慣習的水準の段階2にあたる。', 'Bは「まわりから信用されなくなるから」と、人間関係の中でよく思われることを理由にしている。これは慣習的水準の段階3にあたる。', 'Cは「人間を尊重する」という、だれにでもあてはまる原理を理由にしている。これは脱慣習的水準の段階6にあたる。', 'よって、低い順にA→B→Cとなる。'], a: 'A(段階2)→B(段階3)→C(段階6)', check: '3人とも結論は同じ「返すべきだ」です。それでも理由によって段階が大きくちがうことが、コールバーグの理論のポイントです。Cの理由は、カントの「人格を目的として扱え」という考えにも通じます。' }, { q: '次の発言は、ギリガンのいう「正義の倫理」と「ケアの倫理」のどちらの考え方に近いか。理由も答えよう。\n「部活の大会メンバーをだれにするか決めるとき、規則どおり記録の順に決めるのが公平なのはわかる。でも、けがから復帰したばかりで落ちこんでいる先輩の気持ちや、チームの人間関係がどうなるかも考えて、みんなで話し合いたい。」', hint: '判断の根拠が「公平・規則」なのか、「関係・相手の気持ち」なのかに注目します。', steps: ['発言者は、記録の順という規則にもとづく公平さ(正義の倫理の考え方)を理解したうえで、それだけで決めることに疑問をもっている。', '重視しているのは、先輩の気持ちや、チームの人間関係がどうなるかという、具体的な人どうしのつながりである。', 'さらに、一方的に決めるのではなく、関係者で話し合って答えを探そうとしている。', 'これらは、関係を大切にし、相手のニーズにこたえようとするケアの倫理の特徴である。'], a: 'ケアの倫理に近い。規則による公平さだけでなく、具体的な相手の気持ちや人間関係を大切にして判断しようとしているから。', check: 'ギリガンは、どちらか一方が正しいと言ったのではなく、ケアの倫理も成熟した道徳の一つとして認めるべきだと主張しました。「ケアの倫理のほうが優れている」と書いた選択肢は、言いすぎになっている可能性があるので注意しましょう。' }] }
    ],
    drill: [
      { lv: 2, q: 'スイスの心理学者ピアジェによれば、11〜12歳ごろから、目の前に具体的なものがなくても、仮説を立てて論理的に考えられるようになる。この認知の発達段階を何というか。', a: '形式的操作期', exp: 'ピアジェは、子どもの考える力(認知)が段階的に発達すると考えました。具体的なものを使えば論理的に考えられる「具体的操作期」の次に、ことばや記号だけで抽象的・仮説的に考えられる【形式的操作期】が来るとしました。\n青年期になると、「もし〜だったら」と現実とちがう可能性を考えたり、社会のあり方を理想と比べて批判したりできるようになります。青年が理想を追い求め、大人や社会に対して批判的になる背景には、この考える力の発達があると考えられます。\nコールバーグも、道徳性の発達には、このような認知の発達が土台になると考えました。' },
      { lv: 3, q: 'コールバーグの理論で、慣習的水準の段階4と、脱慣習的水準の段階5は、法やルールに対する考え方がどのようにちがうか説明しなさい。', a: '段階4は、法やルールを社会の秩序を保つためのものとして、それを守ること自体を重んじる。段階5は、法やルールを人々の権利や幸福を守るために合意によってつくられた約束(社会契約)と考え、その目的に合わなければ、正しい手続きで変えることもできると考える。', exp: 'どちらの段階も法やルールを大切にしますが、その「位置づけ」がちがいます。\n段階4では、ルールは守るべきものとして与えられており、「決まりだから守る」「みんなが破ったら社会が成り立たない」という理由づけになります。\n段階5では、ルールより先に人々の権利や幸福があり、ルールはそれを実現するための道具だと考えます。だから、ルールが人々の権利を不当に制限するなら、話し合いや正当な手続きを通じて改めるべきだ、という発想が出てきます。\nこの区別は、倫理で学ぶ社会契約説(ルールは人々の合意でつくられる)とも結びつけて理解するとよいでしょう。' },
      { lv: 3, q: 'ギリガンは、コールバーグの道徳性の発達理論をどのように批判したか。「正義の倫理」「ケアの倫理」の2語を使って説明しなさい。', a: 'コールバーグの理論は主に男性を対象にした研究にもとづいており、権利や公正を重んじる正義の倫理だけを成熟した道徳としていると批判した。そして、具体的な人間関係を大切にし、他者のニーズにこたえて傷つけないようにするケアの倫理も、正義の倫理とは別の、もう一つの成熟した道徳のあり方だと主張した。', exp: 'コールバーグの段階で判定すると、人間関係を大切にする考え方は段階3(よい子志向)に入りやすく、「発達の途中」と評価されてしまいます。ギリガンは、それは正義の倫理だけを基準にしているからだと考えました。\nギリガンは、著書『もうひとつの声』で、人とのつながりの中で責任を考える【ケアの倫理】を示しました。ケアの倫理は、のちに医療・看護・福祉や教育の分野でも重視されるようになりました。\n答案では、「何を批判したか」と「代わりに何を示したか」の2点を必ずセットで書くことがポイントです。' }
    ],
    faq: [
      ['コールバーグの段階は、とばして進むことはできるの?', 'コールバーグは、段階は決まった順序で一つずつ進み、とばすことはないと考えました。ただし、だれもが最後の段階まで進むわけではなく、多くの大人は慣習的水準(段階3・4)にとどまるとされます。\nまた、段階6にあたる人は非常に少なく、コールバーグ自身ものちに、段階6を実際に確かめることは難しいと考えるようになりました。年齢が上がれば自動的に段階が上がるわけではない点にも注意しましょう。'],
      ['「正義の倫理」と「ケアの倫理」は、どちらが正しいの?', 'どちらかが正しくて、もう一方がまちがいというわけではありません。ギリガンが批判したのは、ケアの倫理が「未熟な考え方」とみなされてきたことです。\n実際の問題では、両方の視点が必要になることが多いです。たとえば医療では、患者の権利や公平な扱い(正義)と、目の前の患者の不安によりそうこと(ケア)の両方が求められます。2つの見方を使い分けたり組み合わせたりすることが大切です。']
    ]
  });

  add('ri_greek', {
    secs: [
      { h: 'さらに深く:「変わるもの」と「変わらないもの」──イデア論はどこから来たのか', t: 'プラトンのイデア論は、突然生まれた考えではありません。それ以前の哲学者たちが争った、「世界は変化しているのか、変わらないのか」という問題に対する答えでもありました。\n【ヘラクレイトス】は「万物は流転する」と述べ、「同じ川に二度入ることはできない」とたとえました。川の水はたえず流れ去り、世界のすべては変化し続けている、という考えです。\nこれに対して、南イタリアのエレア出身の【パルメニデス】は、「あるものはあり、あらぬものはあらぬ」と述べ、理性で筋道を立てて考えれば、存在するものは生まれも滅びもせず、変化しないはずだと主張しました。私たちが目で見る変化や多様さは、感覚がつくる思いこみ(ドクサ)にすぎないというのです。\n【プラトン】は、この二つの考えを組み合わせました。感覚でとらえる【現象界】は、ヘラクレイトスの言うようにたえず変化し、不完全です。しかし、理性でとらえる【イデア界】には、パルメニデスの言うような、永遠に変わらない真の存在がある、と考えたのです。\nたとえば、紙にかいた三角形はゆがんでいて、やがて消えてしまいます。それでも私たちは「三角形の内角の和は180度」と確実に知ることができます。それは、変わらない「三角形そのもの(三角形のイデア)」を理性でとらえているからだ、とプラトンは考えました。\nなお、【デモクリトス】は、変わらない【原子】が組み合わせを変えることで変化が生まれる、という別の方法でこの問題に答えました。', key: 'ヘラクレイトスは変化を、パルメニデスは不変を主張した。プラトンは、変化する現象界と不変のイデア界を分けることで、両者を統合した。', ex: [{ q: 'プラトンの考えでは、「三角形の内角の和は180度である」という知識は、紙にかかれた個々の三角形について確かめられたものではない。それでは、この知識は何についての知識だと考えられるか。また、それを何によってとらえると考えたか。', hint: '紙にかいた三角形が、どんな点で「不完全」かを考えます。', steps: ['紙にかいた三角形は、線に太さがあり、角も少しゆがんでいる。測っても、内角の和がぴったり180度になるとは限らない。', 'また、紙の三角形は、やぶれたり消えたりして、いつかはなくなる。つまり、感覚でとらえる現象界のものは不完全で、変化する。', 'それでも「内角の和は180度」という知識は、いつでもどこでも確実に成り立つ。', 'プラトンは、この知識は、変化しない完全な「三角形そのもの」、すなわち三角形のイデアについての知識であり、それは感覚ではなく理性によってとらえられると考えた。'], a: '変わることのない完全な「三角形そのもの」(三角形のイデア)についての知識であり、感覚ではなく理性によってとらえられる。', check: '数学の知識が「確実で、変わらない」ことは、プラトンがイデア論を支える例として重視した点です。プラトンの学園アカデメイアの入り口に「幾何学を知らない者は入るべからず」と掲げられていたという言い伝えも、この考えと結びついています。' }] },
      { h: '実戦演習:ことばの言いかえから、ギリシアの思想家を特定する', t: '共通テストの倫理では、思想家の有名なことばを、そのまま出すのではなく、【現代のことばに言いかえた資料】として出すことが多くあります。\n戦略は、資料の中から【その思想家に特有の考え方の型】を探すことです。\n・「すべては変化する」「対立するものの争いが世界を動かす」→ヘラクレイトス\n・「変化は見かけで、真の存在は不変」→パルメニデス\n・「本質は個々のものの中にある」「素材(質料)と形(形相)」→アリストテレス\n・「死をおそれる必要はない」「心の平静」→エピクロス\n・「自然(理性)にしたがって生きる」「情念に動かされない」→ストア派\nもう一つの落とし穴は、【師弟の考えの入れかえ】です。「イデアは個物に内在する」はプラトンではなくアリストテレスの考え方に近く、「知れば必ず行う」はアリストテレスではなくソクラテスの考え方です。選択肢を読むときは、主語と述語の組み合わせを一つずつ確かめましょう。', key: '資料のキーワードは言いかえられている。思想家に特有の「考え方の型」を見つけ、師弟の考えの入れかえに注意する。', ex: [{ q: '次の資料A・Bは、ある思想家の考えを現代のことばで言いかえたものである。それぞれだれの考えか答えよう。\nA「死は、私たちにとって何ものでもない。私たちが生きているあいだは死はまだ来ておらず、死が来たときには私たちはもう存在しないからだ。だから死をおそれて心を乱す必要はない。」\nB「世界はたえず変化している。昼と夜、夏と冬のように、対立するものが入れかわり、争い合うことによって、かえって世界の調和が保たれている。」', hint: 'Aは「心の平静」、Bは「変化」と「対立」がキーワードです。', steps: ['Aは、死への恐れをとりのぞいて、心が乱されない状態をめざしている。', '死は感覚がなくなることであり、感じることのできないものをおそれる必要はない、という論の進め方は、心の平静(アタラクシア)を理想としたエピクロスの考え方である。', 'Bは、世界がたえず変化していることを強調している。', 'さらに、対立するものの争いによって調和が生まれるという考え方は、「万物は流転する」と述べ、火を根源としたヘラクレイトスの考え方である。'], a: 'A エピクロス B ヘラクレイトス', check: 'Aを「死をおそれない」という点だけでソクラテスと考える人もいます。ソクラテスは、死が善いものである可能性を語りましたが、「心の平静」を目的にした論ではありません。考えの目的まで確かめると、迷いが減ります。' }, { q: '次の記述のうち、正しいものを一つ選ぼう。\nア プラトンは、ものの本質(イデア)は、個々のものの中に形相として内在すると考えた。\nイ パルメニデスは、感覚でとらえられる変化こそが真の存在だと考えた。\nウ アリストテレスは、人が善を知りながら悪を行うことがあるのは、欲望などによって意志が弱くなるからだと考え、よい行いをくり返して習慣をつくることを重視した。\nエ ヘラクレイトスは、真の存在は生まれも滅びもせず、変化しないと考えた。', hint: 'それぞれの主語と内容の組み合わせが正しいか、一つずつ確かめます。', steps: ['アは、本質が個々のものの中にあるとした点で、プラトンではなくアリストテレスの考え方である。誤り。', 'イは、パルメニデスが「変化は感覚の思いこみ」としたことと逆になっている。誤り。', 'ウは、知っていても行えないことがあると認め、習慣による徳(倫理的徳)を重視したアリストテレスの考え方として正しい。', 'エは、ヘラクレイトスではなく、パルメニデスの考え方である。誤り。'], a: 'ウ', check: 'イとエは、パルメニデスとヘラクレイトスの考えを入れかえたひっかけです。「変化=ヘラクレイトス」「不変=パルメニデス」という対応を確かめれば、2つとも誤りだとわかります。' }] }
    ],
    drill: [
      { lv: 2, q: '「あるものはあり、あらぬものはあらぬ」と述べ、理性によって考えれば、真に存在するものは生成も消滅もせず変化しないと主張した、エレア派の哲学者はだれですか。', a: 'パルメニデス', exp: 'パルメニデスは、南イタリアのエレアで活躍した哲学者です。「ないもの」から「あるもの」が生まれることはありえない、と理性で考えて、変化や運動は感覚のつくる見かけにすぎないと主張しました。\nこれは、「万物は流転する」と述べたヘラクレイトスと正反対の立場です。二人の対立は、のちにプラトンが、変化する現象界と変わらないイデア界を分けて考える土台になりました。\nまた、パルメニデスの弟子とされるゼノンは、「アキレスは亀に追いつけない」などのパラドックス(逆説)を示して、運動が理性的に考えると矛盾をふくむことを示そうとしました。' },
      { lv: 3, q: 'デモクリトスの原子論は、「世界は変化するのか、しないのか」という問題に、どのように答えたものといえるか。説明しなさい。', a: 'それ以上分けることのできない、生まれも滅びもしない原子(アトム)が無数にあり、それらが空虚(何もない空間)の中を動き、結びついたり離れたりすることで、さまざまなものの生成や変化が生じると考えた。不変なもの(原子)を認めながら、その組み合わせの変化によって世界の変化を説明したといえる。', exp: 'パルメニデスは「真の存在は不変」と考え、ヘラクレイトスは「すべては変化する」と考えました。デモクリトスは、この両方を生かす答えを出しました。\n原子そのものは不変で、パルメニデスの「あるもの」の性質を受けつぎます。一方で、原子が動き回り、組み合わせを変えることで、私たちが見るような変化が起こります。そのためには、原子が動くための「空虚」が必要だと考えました。\nこの考えは、物質を小さな粒の組み合わせで説明する点で、近代の科学の原子論と似ています。ただし、デモクリトスの原子論は実験ではなく、理性による推論から生まれたものだという点に注意しましょう。' },
      { lv: 3, q: 'エピクロスは「死は私たちにとって何ものでもない」と述べた。この考えの理由を説明し、それがエピクロスのめざす生き方とどのように結びつくか答えなさい。', a: '人は死によって感覚を失うので、生きているあいだは死は存在せず、死が来たときには自分はもう存在しない。感じることのできない死をおそれる理由はないと考えた。死への恐れを取りのぞくことで、心が乱されない平静な状態(アタラクシア)を得ることができ、それこそがエピクロスのめざす快楽(幸福)であった。', exp: 'エピクロスは、原子論を受けついで、人の魂も原子でできており、死ねば原子がばらばらになって感覚もなくなると考えました。感覚がなければ苦痛も感じないので、死そのものは悪いものではありません。\n人を不幸にするのは、死や神々の罰へのいたずらな恐れです。その恐れを理性によって取りのぞけば、心の平静が得られます。\nエピクロスのいう快楽は、ぜいたくや刺激ではなく、体に苦痛がなく、心が乱されていない状態のことです。「死をおそれるな」という主張は、この「心の平静」という目的のための議論だと理解しましょう。' }
    ],
    faq: [
      ['ソクラテスは、自分で本を書いたの?', '書いていません。ソクラテスは、人々と対話することを哲学の方法とし、自分の考えを本にまとめることはしませんでした。\n私たちがソクラテスについて知っていることの多くは、弟子のプラトンが書いた対話篇(『ソクラテスの弁明』『クリトン』など)や、同じく弟子のクセノフォンの記録によるものです。そのため、対話篇の中の「ソクラテスの考え」のどこまでがソクラテス本人のもので、どこからがプラトンの考えなのかは、研究者の間でも議論があります。'],
      ['「哲学」ということばは、もともとどういう意味なの?', 'ギリシア語の【フィロソフィア】に由来し、「知(ソフィア)を愛する(フィレイン)」という意味です。知恵をすでにもっている者ではなく、知恵を求め続ける者が哲学者だ、という考えがこめられています。ソクラテスの「無知の知」とも深く結びつくことばです。\n日本語の「哲学」は、明治時代の思想家・西周がつくった訳語です。']
    ]
  });

  add('ri_religion', {
    secs: [
      { h: 'さらに深く:宗教はなぜ分かれるのか──「だれが正しく教えを受けつぐか」', t: '同じ宗教の中にも、いくつもの宗派があります。その分かれ方を見ると、多くの場合、「だれが、何によって、教えを正しく受けついでいるのか」という【権威のありか】が争点になっています。\n【イスラーム】では、632年に預言者ムハンマドが亡くなったあと、だれが共同体(ウンマ)を導くかが問題になりました。多数派の【スンナ派】は、共同体の合意で選ばれた指導者(カリフ)を認め、ムハンマドの言行にもとづく慣行(スンナ)と共同体のまとまりを重んじます。これに対して【シーア派】は、ムハンマドのいとこで娘むこでもあった【アリー】とその子孫だけが、正統な指導者(イマーム)だと考えます。「シーア」は「党派」という意味で、「アリーの党派」に由来します。現在、イスラーム全体ではスンナ派が多数をしめ、シーア派はイランなどで多数派です。\n【キリスト教】では、ローマ教皇の権威などをめぐって東西の教会が対立し、1054年に【ローマ=カトリック教会】と【東方正教会】に分かれました。16世紀には、ルターらが「教会の権威ではなく、聖書だけが信仰のよりどころだ」と主張し、【プロテスタント】が生まれました。\n仏教でも、出家者の戒律を重んじる上座部と、すべての人の救いをめざす大乗に分かれました。\nこのように、分派の多くは「血筋」「共同体の合意」「教会の組織」「聖典」のどれを権威とするかのちがいとして整理できます。', key: '宗派の分かれ目は「権威のありか」。シーア派はアリーの血筋、スンナ派は共同体の合意と慣行、プロテスタントは聖書のみを重んじる。', ex: [{ q: 'イスラームのスンナ派とシーア派のちがいを、「ムハンマドの後継者」という観点から説明しよう。', hint: '後継者を何によって決めるか、を比べます。', steps: ['二つの派が分かれたきっかけは、ムハンマドの死後、だれが共同体を導くかという後継者の問題である。', 'スンナ派は、共同体の合意によって選ばれたカリフを指導者として認める。', 'シーア派は、ムハンマドの血縁にあたるアリーとその子孫だけが正統な指導者(イマーム)だと考える。', 'つまり、後継者の正しさのよりどころを、スンナ派は共同体の合意と慣行に、シーア派はムハンマドとの血のつながり(アリーの家系)に求めている。'], a: 'スンナ派は共同体の合意で選ばれたカリフを正統な後継者と認めるのに対し、シーア派はムハンマドのいとこで娘むこのアリーとその子孫だけを正統な指導者(イマーム)と考える。', check: '両派とも、唯一神アッラーを信じ、クルアーンを聖典とし、六信五行を守る点は共通しています。ちがいは主に「指導者の正統性」にあることを確かめておきましょう。' }] },
      { h: '実戦演習:礼拝・聖地・偶像のちがいから宗教を判定する', t: '宗教の判定問題では、【礼拝の日】【聖地】【偶像や聖画への態度】などの具体的な特徴が手がかりになります。\n【礼拝の日】:ユダヤ教は【安息日】(金曜日の日没から土曜日の日没まで)に労働を休み、神を礼拝します。キリスト教は、イエスが復活したとされる日曜日を「主の日」として礼拝します。イスラームは毎日5回の礼拝に加えて、金曜日の正午すぎにモスクで集団礼拝を行います。\n【聖地】:エルサレムは三つの宗教にとっての聖地です。イスラームでは、それに加えてメッカとメディナが重要で。\n【偶像】:ユダヤ教とイスラームは、神の姿を像や絵にすることを厳しく禁じます。キリスト教では、カトリックや東方正教会が聖像や聖画(イコン)を用いますが、プロテスタントは教会の装飾をひかえめにする傾向があります。\n落とし穴は、「三つの一神教は同じ神を信じる」という共通点にひきずられて、ちがいを見落とすことです。', key: '安息日(ユダヤ教・金曜日没〜土曜日没)、主の日(キリスト教・日曜)、集団礼拝(イスラーム・金曜)。偶像を厳しく禁じるのはユダヤ教とイスラーム。', ex: [{ q: '次の説明にあてはまる宗教を答えよう。「信者は1日5回、決まった方角に向かって祈る。金曜日には礼拝所に集まって集団で礼拝する。礼拝所の内部には人物の像や絵はなく、植物や幾何学の模様、文字による装飾がほどこされている。」', hint: '礼拝の回数、集団礼拝の曜日、偶像への態度の3つを手がかりにします。', steps: ['1日5回の礼拝は、イスラームの五行の一つである礼拝(サラート)にあたる。決まった方角とは、聖地メッカの方角である。', '金曜日の集団礼拝も、イスラームの特徴である。ユダヤ教の安息日は土曜日(金曜日の日没から)、キリスト教の主日は日曜日である。', '人物の像や絵を置かないのは、偶像崇拝を厳しく禁じているためである。', '3つの手がかりがすべてイスラームを指している。'], a: 'イスラーム', check: '「金曜日」という語だけを見てユダヤ教と迷うことがあります。ユダヤ教の安息日は金曜日の日没に始まりますが、中心は土曜日の安息です。「集団礼拝」「1日5回」という手がかりと組み合わせれば、イスラームと確定できます。' }, { q: '次の記述のうち、正しいものを一つ選ぼう。\nア シーア派は、共同体の合意で選ばれたカリフを正統な指導者と認める多数派である。\nイ 東方正教会は、1054年にローマ=カトリック教会と分かれ、聖画(イコン)を用いた礼拝を行う。\nウ プロテスタントは、聖書よりもローマ教皇の権威を信仰のよりどころとした。\nエ キリスト教では、神が天地創造の後に休んだ日として、土曜日を主の日とする。', hint: 'それぞれの宗派の「権威のよりどころ」と、礼拝の日の対応を確かめます。', steps: ['アは、カリフを認める多数派はスンナ派である。シーア派はアリーとその子孫を指導者とする。誤り。', 'イは、1054年の東西教会の分裂と、東方正教会がイコンを重んじることの両方が正しい。', 'ウは、プロテスタントは教皇の権威ではなく「聖書のみ」をよりどころとした。誤り。', 'エは、神が休んだ7日目の安息日を守るのはユダヤ教で、キリスト教はイエスの復活の日である日曜日を主の日とする。誤り。'], a: 'イ', check: 'アとウは、権威のよりどころを入れかえたひっかけ、エはユダヤ教とキリスト教の礼拝の日の理由を入れかえたひっかけです。「何を権威とするか」「なぜその日なのか」まで確かめると、迷わずに判定できます。' }] }
    ],
    drill: [
      { lv: 2, q: '1054年に、ローマ=カトリック教会と分かれ、主にギリシアや東ヨーロッパ・ロシアなどに広まったキリスト教の教会を何といいますか。', a: '東方正教会(ギリシア正教会)', exp: 'キリスト教は、ローマ帝国の東西の分裂のあと、西のローマを中心とする教会と、東のコンスタンティノープルを中心とする教会とで、しだいに考え方や儀礼のちがいが大きくなりました。ローマ教皇の権威などをめぐる対立から、1054年に両者は正式に分かれました。\n東方正教会は、ギリシア・ロシア・東ヨーロッパなどに広まり、国や民族ごとの教会(ロシア正教会など)をもちます。聖画(イコン)を大切にすることが特徴です。\n「正教」は「正しい教え」という意味で、英語ではオーソドックス(Orthodox)とよばれます。この語は日常では「正統的な・伝統的な」という意味でも使われます。' },
      { lv: 3, q: 'シーア派の「シーア」ということばの由来を説明し、シーア派が正統な指導者をどのように考えるか答えなさい。また、シーア派が多数をしめる国を一つ挙げなさい。', a: '「シーア」は「党派」という意味で、「アリーの党派(シーア・アリー)」に由来する。シーア派は、ムハンマドのいとこで娘むこのアリーとその子孫だけが、共同体を導く正統な指導者(イマーム)であると考える。シーア派が多数をしめる国:イラン(イラクなども可)。', exp: 'ムハンマドの死後、共同体は話し合いでアブー・バクルを最初のカリフに選びました。アリーは4代目のカリフになりましたが、のちに暗殺され、その後の指導者の地位をめぐって対立が深まりました。\nアリーを支持した人々は「アリーの党派」とよばれ、これが「シーア派」の名の由来です。シーア派は、ムハンマドの血を引くアリーの家系にこそ、共同体を導く特別な資格があると考えます。\n現在、イスラーム全体ではスンナ派が多数派で、シーア派は少数派ですが、イランでは国民の多数がシーア派です。地理や国際情勢を学ぶときにも重要な知識です。' },
      { lv: 3, q: 'ユダヤ教で安息日が守られる理由を、聖典の記述と結びつけて説明しなさい。また、キリスト教が日曜日に礼拝を行うようになった理由と比べなさい。', a: 'ユダヤ教の聖典(旧約聖書)には、神が6日間で天地を創造し、7日目に休んだと記されており、その7日目を聖なる日として労働を休み、神を礼拝するのが安息日である(金曜日の日没から土曜日の日没まで)。キリスト教は、イエスが週の初めの日(日曜日)に復活したと信じられたことから、日曜日を「主の日」として礼拝するようになった。', exp: '安息日は、十戒の一つ「安息日を心にとめ、これを聖とせよ」にも定められており、ユダヤ教徒にとって律法の中でも特に大切な決まりです。その日は労働をやめ、神との契約を思い起こします。\nキリスト教はユダヤ教の中から生まれましたが、イエスの復活を信仰の中心においたので、復活の日である日曜日を礼拝の日にしました。\n同じ「週に一度の聖なる日」でも、ユダヤ教は「天地創造」、キリスト教は「イエスの復活」にもとづいている、という理由のちがいを押さえると、両者の信仰の中心のちがいも見えてきます。' }
    ],
    faq: [
      ['「カリフ」と「イマーム」は、どうちがうの?', '【カリフ】は、「(神の使徒の)後継者・代理人」という意味で、ムハンマドの死後、イスラーム共同体の政治と宗教を指導した人の称号です。スンナ派で重視されます。\n【イマーム】は、もともと「先に立つ者」という意味で、広くは礼拝を導く人を指します。シーア派では特に、アリーの子孫で、共同体を導く特別な資格をもつ最高指導者を意味します。同じことばでも、使われる場面によって意味が変わることに注意しましょう。'],
      ['イスラームでは、なぜ偶像崇拝がそれほど厳しく禁じられているの?', 'イスラームの根本は、唯一の神アッラー以外のものを神として拝まないこと(タウヒード、神の唯一性)です。神は目に見えず、人間がつくった像や絵で表せるものではないと考えられています。\n像を拝むと、神ではないものを神のように扱うことになり、唯一神への信仰をそこなうと考えるのです。ムハンマドがメッカを征服したとき、カーバ神殿の偶像を取りのぞいたことも、この考えを象徴するできごとです。']
    ]
  });

  add('ri_china', {
    secs: [
      { h: 'さらに深く:刑罰で治めるか、礼で治めるか──「恥」と「正名」から見た孔子の政治論', t: '孔子は、法律や刑罰で人々を治めることに、はっきりと疑問を示しています。『論語』為政篇には、次のことばがあります。\n「之を道くに政を以てし、之を斉うるに刑を以てすれば、民免れて恥無し。之を道くに徳を以てし、之を斉うるに礼を以てすれば、恥有りて且つ格し。」\n法令で導き、刑罰で取りしまれば、人々は罰をうまくのがれようとするだけで、悪いことをしても【恥じる心】をもたない。しかし、徳で導き、礼でととのえれば、人々は恥を知り、自分から正しくなる、という意味です。\nここには、【外からの強制】と【内からの自律】の対比があります。刑罰は、見つからなければ悪いことをしてもよい、という計算を生みます。これに対して、礼が身につくと、人は見られていなくても「そんなことをするのは恥ずかしい」と感じるようになります。孔子は、規範が心の中に根づいた社会こそが安定すると考えたのです。\nもう一つの柱が【正名】です。斉の景公に政治について問われた孔子は、「君は君たり、臣は臣たり、父は父たり、子は子たり」と答えました(顔淵篇)。君主は君主らしく、臣下は臣下らしく、それぞれが自分の地位(名)にふさわしいふるまい(実)をすることで、社会の秩序が保たれるという考えです。\nのちに韓非子も「名」を重んじましたが、こちらは臣下の言ったこと(名)と実際の成果(形)を照らし合わせて、賞と罰をきびしく与えるためのものでした。同じ「名」でも、孔子は徳による自覚を、韓非子は賞罰による管理をめざした点がちがいます。', key: '孔子は、刑罰による外からの強制では恥の心が育たないとし、徳と礼による自律を重んじた。正名は、地位(名)にふさわしいふるまい(実)を求める考え。', ex: [{ q: '『論語』の「之を道くに政を以てし、之を斉うるに刑を以てすれば、民免れて恥無し」を、現代の学校生活の例を使って説明しよう。', hint: '「罰でしばる」と人がどうふるまうようになるかを考えます。', steps: ['このことばは、「法令で導き、刑罰で取りしまると、人々は罰をのがれようとするだけで、恥の心をもたなくなる」という意味である。', 'たとえば、校則を罰則だけで守らせようとすると、生徒は「先生に見つからなければよい」と考えるようになる。', 'すると、先生の見ていない所では校則を破り、破っても「見つからなかったから問題ない」と考えて、恥ずかしいとは感じない。', '孔子は、これでは本当の秩序は生まれないとし、徳と礼によって、人々が自分から恥を知り正しくふるまうようになることを求めた。'], a: '(例)校則を罰だけで守らせると、生徒は「見つからなければよい」と考え、見られていない所で決まりを破っても恥ずかしいと思わなくなる。孔子は、このように刑罰による政治では人々の内面に恥の心が育たないと考えた。', check: 'この考えは、法による統治を重んじた韓非子と対立します。韓非子なら、「見つからない所がないように監視と賞罰を徹底すればよい」と答えるでしょう。両者を比べると、孔子の考えの特徴がはっきりします。' }] },
      { h: '実戦演習:諸子百家の「批判の応酬」を読み解く', t: '諸子百家の問題では、思想家どうしが【だれを、どの点で批判したか】がよく問われます。\n【墨子→儒家】:墨子は、儒家の仁は、自分の親や身内を先に愛する【別愛】(差別のある愛)だと批判し、すべての人を区別なく愛する兼愛を説きました。また、儒家が重んじた手厚い葬儀や音楽を、費用がかかり民衆を苦しめるむだだとして、【節葬】【非楽】を主張しました。\n【孟子→墨子・楊朱】:孟子は、墨子の兼愛は自分の父と他人の父を区別しないので「父を無視するものだ」と批判しました。また、自分のためだけに生きることを説いた楊朱を「君主を無視するものだ」と批判しました。\n【老子→儒家】:「大道廃れて仁義あり」と、仁義が説かれること自体が本来の道が失われた証拠だと批判しました。\n戦略は、【批判する側の中心思想】から批判の理由を考えることです。批判の理由は、必ず批判する側の考えの裏返しになっています。', key: '批判の理由は、批判する側の中心思想の裏返し。墨子は別愛と浪費を、孟子は兼愛と為我を、老子は仁義そのものを批判した。', ex: [{ q: '墨子は、儒家の説く仁を「別愛」とよんで批判した。墨子が儒家の仁を批判した理由と、それに代わって示した考えを説明しよう。', hint: '儒家の仁が、愛する相手によって「差」をつけるものであることに注目します。', steps: ['儒家の仁は、親への孝や兄弟への悌など、家族への愛を出発点とし、それを他人へ広げていくものである。', 'そのため、身内を他人より先に、より深く愛するという「差」がある。墨子はこれを、区別をつける愛=別愛とよんだ。', '墨子は、人々が自分や身内だけを大切にし、他人を区別することが、争いや戦争の原因だと考えた。', 'そこで、自分と他人、自分の家族と他人の家族を区別せずに愛する兼愛と、互いに利益を与え合う交利を説いた。'], a: '儒家の仁は、身内を先に愛する差別のある愛(別愛)であり、人々が身内と他人を区別することが争いの原因になると考えたから。代わりに、すべての人を区別なく愛する兼愛(と互いに利益を与え合う交利)を説いた。', check: '墨子の兼愛は、侵略戦争を否定する非攻の考えにもつながります。「区別するから争う→区別せずに愛せば争いがなくなる」という一本の筋道で、兼愛と非攻を結びつけられるか確かめましょう。' }, { q: '孟子は、墨子の兼愛を「父を無みする(無視する)ものだ」と批判した。孟子がこのように批判した理由を、孟子自身の考えにもとづいて説明しよう。', hint: '孟子は儒家です。儒家の愛は、どこから始まるのでしょうか。', steps: ['孟子は孔子の教えを受けつぐ儒家であり、愛は家族、とくに親への孝から始まり、しだいに他人へ広がっていくのが自然だと考えた。', '墨子の兼愛は、自分の親と他人の親を区別せずに同じように愛することを求める。', '孟子から見ると、これは自分を生み育ててくれた親への特別な愛と恩を認めないことになる。', 'そのため、兼愛は人間の自然な心に反し、親を親として扱わない(父を無視する)考えだと批判した。'], a: '孟子は、愛は親への孝から始まり他人へと広げていくのが人間の自然な心のあり方だと考えた。そのため、自分の親と他人の親を区別しない兼愛は、親への特別な愛と恩を否定し、父を父として扱わない考えになると批判した。', check: '墨子が儒家を「区別があるからだめだ」と批判し、孟子は墨子を「区別がないからだめだ」と批判しています。批判が正反対の向きになっていることを確かめると、両者の中心思想のちがいがよくわかります。' }] }
    ],
    drill: [
      { lv: 2, q: '孔子が説いた、君主は君主らしく、臣下は臣下らしく、父は父らしく、子は子らしく、それぞれの地位や名にふさわしいふるまいをすることで社会の秩序を保とうとする考えを何といいますか。', a: '正名(名を正す)', exp: '孔子は、弟子に「政治を任されたら何から始めるか」と問われ、「必ずや名を正さんか」と答えたと伝えられます。名(地位や役割を表すことば)と実(実際のふるまい)が一致していないと、ことばが通じなくなり、礼も刑罰も正しく行われず、民はどうしてよいかわからなくなる、と考えたのです。\n「君は君たり、臣は臣たり、父は父たり、子は子たり」ということばがよく知られています。\nなお、「名」は日常語では名前を指しますが、ここでは「地位・役割とそれにふさわしいあり方」を表す、より広い意味で使われています。' },
      { lv: 3, q: '韓非子は、君主が臣下を思いどおりに動かすための二つの手段を「二柄(二つの柄)」とよんだ。二柄とは何か。また、それを用いる考えは、孔子の徳治主義とどのような点で対立するか説明しなさい。', a: '二柄とは、刑(罰)と徳(賞)の二つである。韓非子は、人は利益を求め罰をおそれる存在だと考え、君主が賞と罰の権限をしっかりにぎり、法にもとづいて必ず与えることで臣下や民を動かそうとした。これは、人々の内面の徳や礼によって自ら正しくなることを期待する孔子の徳治主義とは、外からの強制で秩序をつくろうとする点で対立する。', exp: '韓非子は、荀子の性悪説を受けつぎつつ、さらに徹底して、人は利益を好み害をきらうものだと考えました。だから、仁や礼で心を変えようとするより、賞と罰という「柄(取っ手)」をにぎって、人を動かすほうが確実だと主張したのです。\nここでの「徳」は、儒家の「人格の徳」ではなく、「恩賞を与えること」という意味で使われている点に注意しましょう。\n孔子が「刑罰で治めれば民は恥を知らない」と述べたのと、韓非子の考えは正反対です。どちらが人間をどう見ているか(人間観)から、政治論の対立を説明できるようにしておきましょう。' },
      { lv: 3, q: '墨子が、儒家の重んじた手厚い葬儀や音楽を批判して、節葬・非楽を説いたのはなぜか。墨子の根本的な考え方と結びつけて説明しなさい。', a: '墨子は、天下の人々の利益を増やし、害を取りのぞくことを何より重んじ、すべての人を区別なく愛する兼愛を説いた。儒家の手厚い葬儀や音楽は、多くの財産と労力を使い、民衆の生活を苦しめるだけで、天下の利益にならないと考えたので、葬儀を簡素にする節葬と、音楽をつつしむ非楽を主張した。', exp: '墨子は、身分の低い職人の出身ともいわれ、民衆の生活の苦しさをよく知っていたと考えられています。そのため、思想の判断の基準は、つねに「天下の人々の利益になるか」でした。\n儒家にとって、親の葬儀を手厚く行い長く喪に服することは、孝を表す大切な礼でした。しかし墨子は、それで財産を使い果たし、働く時間も失えば、かえって人々を貧しくすると批判しました。音楽も同じく、支配者のぜいたくだと考えました。\n「礼を重んじる儒家」と「実際の利益を重んじる墨家」の対立として、兼愛・非攻と合わせて理解しておきましょう。' }
    ],
    faq: [
      ['儒教の「礼」は、ただのマナーや作法のこと?', '作法や儀式もふくみますが、それだけではありません。孔子の礼は、【仁】という人を思いやる心が、ふさわしい形となって外にあらわれたものです。心のこもらない形だけの礼を、孔子はきびしく批判しました。\nまた礼は、家族や君臣の関係を正しく保つ社会の規範でもあります。人が礼を身につけると、強制されなくても自ら正しくふるまうようになるので、礼は内面の徳と社会の秩序をつなぐ役割をもっているのです。'],
      ['儒教は宗教なの?それとも道徳や政治の思想なの?', '両方の面があります。孔子は「怪力乱神を語らず」と述べ、超自然的なことを積極的に語りませんでした。また、死について問われ「未だ生を知らず、焉んぞ死を知らん」と答え、まず現実の人間の生き方を重んじました。この点では道徳・政治の思想です。\n一方で、儒教は天をうやまい、祖先をまつる祭祀を大切にし、のちには孔子をまつる廟もつくられました。このように、宗教的な面もあわせもっています。']
    ]
  });

  add('ri_west', {
    secs: [
      { h: 'さらに深く:人間に自由意志はあるのか──エラスムスとルターの論争', t: 'ルネサンスと宗教改革は、どちらも中世のカトリック教会のあり方に疑問を投げかけた運動です。しかし、【人間をどう見るか】という点では、正反対ともいえる考えをもっていました。それがはっきり表れたのが、【自由意志】をめぐる論争です。\nルネサンスの人文主義者ピコ・デラ・ミランドラは、人間は自由意志によって、獣のようにも天使のようにもなれる存在だとし、そこに人間の尊厳を見いだしました。同じ人文主義者の【エラスムス】は、1524年に『自由意志論』を書き、人間が救われるには神の恵みが必要だが、人間の自由意志もそれに協力し、善を選ぶことができると主張しました。\nこれに対して【ルター】は、翌1525年に『奴隷意志論』で反論しました。ルターによれば、人間の意志は、原罪によって罪にしばられており、自分の力で善を選んで救いに近づくことはできません。人間の意志は、罪か神か、どちらかに乗られて進む「乗りもの」のようなものだというのです。だからこそ、人が救われるのは、行いや努力によるのではなく、ただ神の恵みと信仰によるのだ(信仰義認)と考えました。\nこの論争は、「人間は自分の力で善くなれるのか」という問いをめぐる対立です。のちにカントは、人間の自由を、欲望に流されず、理性が自ら立てた道徳法則にしたがうこと(【自律】)としてとらえ直しました。自由意志の問題は、近代の哲学に受けつがれていったのです。', key: 'エラスムスは人間の自由意志が救いに協力できるとし、ルターは原罪にしばられた意志は無力で、救いは神の恵みと信仰のみによるとした。', ex: [{ q: 'ルターが人間の自由意志の力を否定したことは、ルターの信仰義認の考え方とどのように結びついているか説明しよう。', hint: 'もし人間が自由意志で善を選べるなら、救いは何によって得られることになるでしょうか。', steps: ['もし人間が自分の自由意志で善を選び、よい行いを積み重ねて救いに近づけるなら、救いは人間の行いや努力によって得られることになる。', 'ルターは、人間の意志は原罪によって罪にしばられており、自分の力では本当の善を行えないと考えた。', 'そうであれば、人間は自分の行いによって神の前に正しい者(義)とされることはできない。', 'だから、人が救われるのは、人間の側の功績によるのではなく、ただ神の恵みを信じる信仰によってのみである、という信仰義認の主張になる。'], a: '人間の意志は原罪にしばられ、自分の力で善を行って救いに近づくことはできないと考えたので、救いは人間の行いや功績によるのではなく、神の恵みを信じる信仰によってのみ与えられる(信仰義認)という主張に結びついた。', check: 'ルターが、お金を払えば罪の罰が軽くなるとする贖宥状の販売を批判したことも、「人間の行いで救いを買うことはできない」という同じ考えで説明できます。' }] },
      { h: '実戦演習:カントの原典を読んで、道徳哲学と結びつける', t: '共通テストの倫理では、思想家の原典を読んで、その主張を、その思想家の中心的な考えと結びつけさせる問題がよく出ます。\n戦略は、資料を読んだら、まず【カントの中心となる3つの考え】のどれと関係しているかを考えることです。\n①【自律】:人間は、欲望や他人の命令にしたがうのではなく、自分の理性が立てた道徳法則にしたがうときに自由である。\n②【人格の尊厳】:人間を、単なる手段としてではなく、つねに同時に目的として扱わなければならない。\n③【普遍性】:自分の行為の方針が、すべての人にあてはまる法則となりうるように行為せよ。\nカントの『啓蒙とは何か』(1784年)や『永遠平和のために』(1795年)は、道徳とは別の話題に見えますが、実はこの3つの考えが土台になっています。\n落とし穴は、資料の表面のことば(「戦争」「国家」など)だけに反応して、ほかの思想家(ホッブズなど)の考えと混同することです。', key: 'カントの原典は、自律・人格の尊厳・普遍性の3つの柱のどれにつながるかを考えて読む。', ex: [{ q: 'カントは『啓蒙とは何か』で、次のように述べている(要約)。「啓蒙とは、人間が、自分の責任で陥っている未成年の状態から抜け出ることである。未成年とは、他人の指導がなければ自分の知性を使うことができない状態である。自分の知性を使う勇気をもて。」この主張は、カントの道徳哲学のどの考えと結びつくか。', hint: '「他人の指導がなければ」考えられない状態は、自律と他律のどちらにあたるでしょうか。', steps: ['「未成年の状態」とは、年齢のことではなく、自分で考えることをせず、他人の判断にたよっている状態を指している。', 'これは、自分の外にあるもの(他人や権威)にしたがう状態であり、カントのいう他律にあたる。', '「自分の知性を使う勇気をもて」とは、他人にたよらず、自分の理性で判断せよということである。', 'これは、自分の理性が立てた法則に自らしたがう自律の考え方と結びつく。'], a: '自律の考え方と結びつく。他人の判断にたよる「未成年の状態」は他律の状態であり、自分の理性を使って自ら判断することを求める啓蒙は、理性が自ら立てた法則にしたがう自律の考えと共通している。', check: '「自分の責任で陥っている」とあるのは、能力がないからではなく、決心と勇気が足りないために他人にたよっている、という意味です。理性はすべての人がもっている、というカントの前提とも一致します。' }, { q: 'カントは『永遠平和のために』で、「常備軍は、時とともに全廃されるべきである」と主張した。その理由の一つとして、カントは、人を殺したり殺されたりするために雇われることは、人間を国家の単なる道具として使うことだと述べている。この理由は、カントの道徳哲学のどの考えにもとづいているか説明しよう。', hint: '定言命法の一つ「人格を、単に手段としてのみ扱ってはならない」を思い出しましょう。', steps: ['常備軍の兵士は、国家の命令によって、人を殺したり、自分が殺されたりするために、いつでも使えるように雇われている。', 'これは、兵士という人間を、国家の目的を果たすための機械や道具として扱っていることになる。', 'カントは、人間はかけがえのない価値(尊厳)をもつ人格であり、つねに同時に目的として扱われなければならず、単なる手段としてのみ扱ってはならないと考えた。', 'したがって、人間を殺し合いの道具として扱う常備軍は、人格の尊厳に反すると考えたのである。'], a: '人格を単に手段としてのみ扱ってはならず、つねに同時に目的として扱わなければならないという、人格の尊厳の考え(定言命法)にもとづいている。常備軍は、兵士を国家の殺し合いのための道具として扱うので、この考えに反するから。', check: 'カントは、常備軍がほかの国をたえず戦争の脅威にさらし、軍備の拡大競争を引き起こすことも理由に挙げています。道徳的な理由と、国際関係の現実的な理由の両方があることも押さえておきましょう。' }] }
    ],
    drill: [
      { lv: 2, q: 'エラスムスの『自由意志論』に反論し、1525年に『奴隷意志論』を書いて、原罪にしばられた人間の意志は自分の力で善を選べないと主張した宗教改革者はだれですか。', a: 'ルター', exp: 'ルターは、1517年に『95か条の論題』を発表して贖宥状の販売を批判し、宗教改革のきっかけをつくった人物です。人文主義者エラスムスは、はじめは教会の腐敗を批判する点でルターに近い立場でしたが、人間の自由意志をめぐって対立しました。\nエラスムスは、自由意志が神の恵みに協力しうると考えたのに対し、ルターは、救いは神の恵みと信仰のみによると考えました。\n「奴隷意志」とは、意志が罪の奴隷になっていて自由ではない、という意味です。同じ時代の改革者カルヴァンが説いた予定説も、救いは人間の意志ではなく神が決めているという点で、ルターと同じ方向の考えです。' },
      { lv: 3, q: 'カントの考える「自由」は、「何でも好きなことを選べる」という意味の自由とどのようにちがうか。「自律」「他律」の2語を使って説明しなさい。', a: 'カントにとって、欲望や好み、外からの命令にしたがって行動することは、自分以外のものに決められている他律の状態であり、本当の自由ではない。本当の自由とは、自分の理性が自ら立てた道徳法則に、自らしたがう自律のことである。好きなことを選ぶ自由は、欲望にしたがっている点で、むしろ他律にあたる。', exp: 'ふつう「自由」というと、したいことができることを思いうかべます。しかしカントは、たとえば「おなかがすいたから食べる」「ほめられたいから親切にする」という行動は、欲望や他人の評価に動かされているので、自分で決めているとはいえないと考えました。\n人間が本当に自由なのは、「すべての人にあてはまる法則として認められるか」を自分の理性で考え、その法則に自分からしたがうときです。\nピコの「人間は自由意志で自分のあり方を選べる」という自由が「選択の自由」だとすると、カントの自由は「理性による自己立法」としての自由だと区別できます。' },
      { lv: 3, q: 'カントは『永遠平和のために』で、平和のためには、各国の政治体制が共和的であるべきだと主張した。共和的な体制が戦争をおさえると考えられた理由を説明しなさい。', a: '共和的な体制では、戦争をするかどうかを決めるのに国民の同意が必要になる。戦争になれば、戦う、費用を負担する、荒廃した国土を立て直すなどの苦しみを国民自身が負うので、国民は戦争を始めることに慎重になる。そのため、君主が自分の意志だけで戦争を始められる体制よりも、戦争が起こりにくいと考えた。', exp: 'カントのいう共和的な体制とは、国民が法の下で自由・平等であり、法をつくる権力と法を実行する権力が分けられている体制です。\n君主が国を私物のように支配する体制では、君主は戦争をしても自分の生活はほとんど変わらないので、ささいな理由で戦争を始めてしまいます。これに対して、戦争の負担を負う国民が決定にかかわれば、戦争には慎重になるはずだ、とカントは考えました。\nカントはさらに、諸国家が自由な国家の連合をつくることも提案しました。この構想は、のちの国際連盟や国際連合の思想的な源流の一つとされています。' }
    ],
    faq: [
      ['「啓蒙思想」は、カントだけの考えなの?', 'いいえ。啓蒙思想は、17〜18世紀のヨーロッパで広まった、理性によって迷信や古い権威を批判し、人間の進歩をめざす思想の大きな流れです。フランスでは、ヴォルテール、モンテスキュー、ルソー、ディドロ(『百科全書』)らが活躍しました。\nカントの『啓蒙とは何か』は、この流れを振り返り、啓蒙の本質を「自分の理性を使う勇気」として示したものとして有名です。'],
      ['エラスムスとルターは、最初から対立していたの?', 'はじめは、教会の腐敗を批判する点で近い立場でした。エラスムスは『愚神礼讃』で聖職者の堕落を風刺し、聖書の原典にもどることを重んじました。そのため当時、「エラスムスが卵を産み、ルターがそれをかえした」と言われたほどです。\nしかし、エラスムスは教会を内側から改めることを望み、教会の分裂には反対しました。そして、人間の自由意志をめぐる考え方のちがいから、二人ははっきりと対立するようになりました。']
    ]
  });

  add('ri_modern', {
    secs: [
      { h: 'さらに深く:「他者」はわたしの理解をこえている──レヴィナスの倫理', t: '近代の哲学は、デカルトの「われ思う」のように、【自分(自我)】を出発点にして世界を理解しようとしてきました。フランスの哲学者【レヴィナス】は、この考え方そのものに、深い危うさがあると考えました。\nレヴィナスはユダヤ系で、第二次世界大戦中、家族の多くをナチスによるホロコーストで失いました。彼は、他者を自分の理解の枠組みの中に取りこみ、「こういう人間だ」と決めつけてしまう考え方を【全体性】とよび、それがやがて他者を排除し、抹殺することにさえつながると考えました。\nこれに対してレヴィナスは、他者は、どれほど理解しようとしても、わたしの理解に完全にはおさまらない、【無限】の存在だと考えました。主著『全体性と無限』の題名は、この対比を表しています。\n他者は、まず【顔】としてわたしの前に現れます。ここでいう顔とは、目や鼻の形のことではありません。弱く、むき出しで、傷つきやすい他者の存在そのものが、わたしに「殺すなかれ」と訴えかけ、こたえるように呼びかけてくる、という意味です。\nこの呼びかけにこたえることが、【責任】の始まりです。レヴィナスにとって倫理とは、まず自分があって、その後に他人とのルールを決めることではなく、他者の顔に出会い、その呼びかけにこたえることから始まるものなのです。', key: 'レヴィナスは、他者を自分の理解に取りこむ「全体性」を批判し、理解をこえた他者の「顔」の呼びかけにこたえることに倫理の始まりを見た。', ex: [{ q: 'レヴィナスのいう「顔」とは、どのようなものか。また、レヴィナスが、他者を自分の理解の枠組みに取りこむこと(全体性)を危険だと考えた理由を説明しよう。', hint: '「顔」は見た目のことではありません。レヴィナスの体験も手がかりになります。', steps: ['レヴィナスのいう顔とは、目鼻立ちのような外見ではなく、弱く傷つきやすい他者の存在そのものが、わたしに直接に現れることである。', 'その顔は、わたしに「殺すなかれ」と訴え、こたえることを求める。そこから他者への責任が生まれる。', '一方、他者を「〜人だから」「〜な人間だ」と自分の枠組みで決めつけると、その人のかけがえのなさは見えなくなる。', 'レヴィナスは、ホロコーストのように、人々をある集団の一員としてしか見ず、排除し抹殺することは、このような全体性の考え方の行きついた姿だと考え、危険視した。'], a: '顔とは、外見ではなく、弱く傷つきやすい他者の存在そのものが現れ、「殺すなかれ」とわたしに呼びかけるもののこと。他者を自分の理解の枠組みに取りこむと、その人のかけがえのなさが消され、ついには他者の排除や抹殺につながるおそれがあるから。', check: '「他者を理解することは悪い」という意味ではない点に注意しましょう。理解しつくしたと思いこみ、他者の他者性(自分とのちがい)を消してしまうことを、レヴィナスは批判したのです。' }] },
      { h: '実戦演習:現代思想の資料を「何を批判し、何を求めたか」で読む', t: '現代の思想の問題は、短い資料文を読み、だれの考えかを特定させたり、その考えを具体的な事例にあてはめさせたりする形がよく出ます。\n戦略は、資料の中に【批判の対象】と【代わりに示したもの】の2つを探すことです。\n・近代の理性が人を支配する道具になった→フランクフルト学派(ホルクハイマー・アドルノ)\n・対話による合意の可能性→ハーバーマス\n・見えない形で人を規律し、自分から規則にしたがう人間をつくる権力→フーコー\n・自分の理解に他者を取りこむ全体性→レヴィナス\n・所得や財の量だけで豊かさをはかること→セン(何ができるかという潜在能力)\n落とし穴は、資料の中の具体例(監獄・病院・学校など)にひきずられることです。たとえば「監獄」が出てきても、それが刑罰の話なのか、権力のしくみの話なのかを読み分ける必要があります。資料の結論が何を問題にしているかをつかみましょう。', key: '資料から「批判の対象」と「代わりに示したもの」を見つける。具体例ではなく、資料の結論が何を問題にしているかで判断する。', ex: [{ q: '次の資料は、ある思想家の考えを要約したものである。だれの考えか答え、資料の主張を説明しよう。\n資料「中央に監視塔があり、そのまわりを囚人の部屋が円形に囲む監獄が考案された。囚人からは監視塔の中が見えないので、実際に見張られていなくても、囚人は常に見られているかもしれないと意識し、自分から規則にしたがうようになる。近代の学校や工場、病院も、これと同じしくみで人々を規律している。」', hint: '資料が問題にしているのは、監獄そのものでしょうか、それとも人を動かす権力のしくみでしょうか。', steps: ['資料は監獄を例にしているが、結論では学校・工場・病院にも同じしくみがあると述べており、刑罰そのものではなく、近代社会の権力のしくみを問題にしている。', 'その権力は、暴力で命令するのではなく、「見られているかもしれない」という意識を植えつけて、人々が自分から規則にしたがうようにするものである。', 'このように、目に見えない形で人々を規律し、従順な人間をつくり出す権力を分析したのはフーコーである。', 'なお、この円形の監獄(パノプティコン)を考案したのは、功利主義者のベンサムである。フーコーは、それを近代の権力を象徴するものとして取り上げた。'], a: 'フーコー。近代社会では、権力が暴力で命令するのではなく、常に見られているかもしれないという意識を通じて、人々が自分から規則にしたがうように内側から規律している、という主張。', check: '資料に「監獄」があるからといって、刑罰の改善を説いたベンサムの考えと答えると誤りになります。考案者はベンサムでも、資料の主張(権力が人を規律するしくみの批判)はフーコーのものです。' }, { q: 'AさんとBさんは、同じ金額の所得を得ている。ただし、Bさんは車いすを使っており、Bさんの住む町には段差の多い道や、エレベーターのない駅が多い。センの「潜在能力(ケイパビリティ)」の考え方にもとづくと、2人の豊かさは同じだといえるか。理由も答えよう。', hint: 'センは、所得の量よりも、その人が実際に「何ができるか」を重視しました。', steps: ['所得の量だけで比べると、AさんとBさんは同じ豊かさだということになる。', 'しかし、センの潜在能力の考え方では、所得などの財を使って、その人が実際にどのような生き方を選び、実現できるか(移動する・働く・人と会うなど)を重視する。', 'Bさんは、段差やエレベーターのない駅のために、同じ所得があっても、自由に移動したり通勤したりすることが、Aさんより難しい。', 'したがって、Bさんが実際に選べる生き方の幅(潜在能力)はAさんより小さく、2人の豊かさは同じとはいえない。'], a: '同じとはいえない。所得が同じでも、Bさんは町の段差などのために移動や仕事などの選択肢がせまく、実際に実現できる生き方の幅(潜在能力)がAさんより小さいから。', check: 'この考え方からは、Bさんにお金を多く配るだけでなく、段差をなくしエレベーターを設置する(バリアフリー化)ことで、潜在能力を広げることが大切だ、という政策の方向も導けます。' }] }
    ],
    drill: [
      { lv: 2, q: '『全体性と無限』を著し、他者を自分の理解に取りこむことを批判して、他者の「顔」の呼びかけにこたえる責任に倫理の出発点を見いだしたフランスの哲学者はだれですか。', a: 'レヴィナス', exp: 'レヴィナスは、リトアニア出身のユダヤ系の哲学者で、フランスで活躍しました。第二次世界大戦中にナチスによって家族の多くを失った体験が、その思想の背景にあります。\n彼は、自分を中心にして世界や他者を理解しようとする西洋哲学の伝統を「全体性」として批判し、自分の理解をこえた他者を「無限」として示しました。\nなお、「顔」は日常のことばでは目や鼻のある部分を指しますが、レヴィナスの用語としては、他者がその弱さと傷つきやすさのままにわたしの前に現れることを意味します。ふつうの意味と区別して覚えましょう。' },
      { lv: 3, q: 'フーコーは、近代の権力は、王が罰を見せつけて人々をおそれさせる権力とはちがうと考えた。フーコーのいう近代の権力の特徴を、学校を例にして説明しなさい。', a: '近代の権力は、暴力や見せしめで外から強制するのではなく、人々を常に観察し、時間割や試験・成績などで管理し、「正常」な基準に合わせるように訓練することで、人々が自分から規則にしたがうように内側からつくりかえる(規律権力)。たとえば学校では、決まった時間に決まった席にすわり、試験で評価され、比べられることで、生徒は先生に命令されなくても、自分から時間や規則を守るようになる。', exp: 'フーコーは、中世や近世の権力が、公開処刑のように身体に罰を加えて人々をおそれさせたのに対し、近代の権力は、監視・記録・試験などを通じて人を細かく管理し、「規律正しい人間」をつくり出すものだと考えました。\nこの権力は、上から押しつけられるだけでなく、社会のすみずみに網の目のように広がり、人々は知らないうちにそれを自分のものとして受け入れます。\n学校の例を使うときは、「命令されなくても自分から守るようになる」という点を必ず書くことが大切です。それが、外からの強制とはちがう近代の権力の特徴だからです。' },
      { lv: 3, q: 'ベルクソンは『道徳と宗教の二源泉』で、「閉じた社会」と「開いた社会」を区別した。それぞれの社会の特徴を説明しなさい。', a: '閉じた社会とは、家族・民族・国家など、限られた集団を守るために、習慣や義務によって成員をしばり、外の集団に対しては排他的になる社会である。開いた社会とは、特定の集団の枠をこえて、人類全体を愛によって結びつける社会であり、すぐれた宗教者などが示す愛の飛躍(エラン・ダムール)によって開かれる。', exp: 'フランスの哲学者ベルクソンは、生命を、たえず新しいものを生み出していく創造的な流れ(生命の飛躍、エラン・ヴィタール)としてとらえました。\n閉じた社会の道徳は、集団を守るための「圧力」としてはたらき、仲間には親切でも、よそ者には冷たくなりがちです。これに対して、開いた社会の道徳は、集団の外の人々にまで広がる愛の「あこがれ」によって人を動かします。\n閉じた社会を少しずつ広げれば開いた社会になる、のではなく、質の異なる飛躍が必要だとした点が、ベルクソンの考えの特徴です。' }
    ],
    faq: [
      ['レヴィナスとサルトルでは、「他者」のとらえ方はどうちがうの?', 'サルトルは、他者のまなざしは、わたしを見られる「もの」にしてしまい、わたしの自由をおびやかすものだと考えました。戯曲『出口なし』の「地獄とは他人のことだ」というせりふが有名です。\nこれに対してレヴィナスは、他者は、わたしをおびやかす存在というより、わたしに呼びかけ、責任を目覚めさせる存在だと考えました。他者との出会いを、自由の制限ではなく倫理の始まりとしてとらえた点が大きなちがいです。'],
      ['フーコーは、権力をすべて悪いものと考えたの?', '単純に「悪いもの」とは考えていません。フーコーは、権力を、王や政府が上から押しつけるものだけでなく、学校・病院・家庭など社会のあらゆる関係の中に広がり、人々の考え方やふるまいをつくり出す「生産的」なはたらきをもつものとしてとらえ直しました。\nだからこそ、わたしたちが「あたりまえ」「正常」と思っていることが、どのような権力のしくみの中でつくられたのかを問い直すことが大切だ、と考えたのです。']
    ]
  });

  add('ri_japan', {
    secs: [
      { h: 'さらに深く:「民主主義」ではなく「民本主義」──吉野作造が言葉を選んだ理由', t: '大正時代には、政治に民衆の意見を反映させようとする動き(大正デモクラシー)が広がりました。その理論的な中心となったのが、政治学者の【吉野作造】です。\n吉野は、デモクラシーを【民本主義】と訳しました。なぜ「民主主義」と言わなかったのでしょうか。\n当時の大日本帝国憲法では、主権は天皇にあるとされていました。「民主主義」は「主権が国民にある」という意味をふくむので、そのまま主張すると、憲法の天皇主権と正面からぶつかってしまいます。\nそこで吉野は、デモクラシーの中から、【主権がだれにあるか】という問題を切りはなしました。そして、主権のありかは問わずに、①政治の目的は一般民衆の幸福(利福)にあること、②政策の決定は民衆の意向にもとづくべきこと、の2点を民本主義の中身としました。こうすれば、天皇主権の憲法の下でも、民衆のための政治を実現できると考えたのです。\n吉野は、その実現の方法として、【普通選挙】の実施と、選挙で多数をしめた政党が内閣をつくる【政党内閣】を主張しました。1925年には男子の普通選挙が実現し、政党内閣も一時期続きました。\nかつて明治時代に中江兆民は、上から与えられた「恩賜的民権」を、民衆が勝ちとる「恢復的民権」へと育てるべきだと説きました。吉野の民本主義も、与えられた憲法の枠の中で、民衆の政治参加を少しずつ広げようとする、現実的な工夫だったといえます。', key: '吉野作造は、主権のありかを問わずに、政治の目的を民衆の幸福に、政策の決定を民衆の意向に置く民本主義を説き、天皇主権の憲法の下で普通選挙と政党内閣を求めた。', ex: [{ q: '吉野作造が、デモクラシーを「民主主義」ではなく「民本主義」と訳した理由を、大日本帝国憲法と関連づけて説明しよう。', hint: '「民主主義」ということばが「何がだれにある」ことを意味するかを考えます。', steps: ['「民主主義」は、国の主権(政治のあり方を最終的に決める力)が国民にあることを意味する。', '大日本帝国憲法では、主権は天皇にあるとされていたので、「民主主義」を主張することは、憲法の根本と対立することになる。', '吉野は、デモクラシーのうち主権のありかの問題を切りはなし、政治の目的と、政策の決め方の問題に焦点をしぼった。', 'そのうえで、政治の目的は民衆の幸福、政策の決定は民衆の意向にもとづく、という民本主義を説き、天皇主権の憲法の下でも実現できる考え方として示した。'], a: '「民主主義」は主権が国民にあることを意味し、天皇主権を定めた大日本帝国憲法と対立してしまうため。吉野は主権のありかを問わず、政治の目的を民衆の幸福に、政策の決定を民衆の意向に置く「民本主義」として示すことで、憲法の枠内で民衆のための政治をめざした。', check: '戦後の日本国憲法は、国民主権を明記しました。吉野が「問わない」とした主権のありかの問題に、はっきりと答えを出したのが日本国憲法だと考えると、時代の流れがつながります。' }] },
      { h: '実戦演習:江戸の町人の合理的な思想を、資料から見分ける', t: '18世紀には、大坂の商人たちがつくった学問所【懐徳堂】などを中心に、【合理的・批判的】な考え方をする町人の学者も現れました。\n【富永仲基】は、『出定後語』などで【加上説】を説きました。後から現れた思想は、それ以前の思想に、より古く、より高い権威を主張する説を「加え上げる」ことでつくられた、という考えです。この方法で、仏教・儒教・神道のどれもが絶対的な真理ではないと批判しました。\n【山片蟠桃】は、『夢の代』で、霊魂や鬼神は存在しないとする【無鬼論】を説きました。\n解くときの戦略は、【何を根拠に批判しているか】に注目することです。国学者が日本の古典を根拠に儒教や仏教を批判した(漢意の否定)のに対して、富永仲基や山片蟠桃は、歴史的な成り立ちの分析や、自然の観察・合理的な推論を根拠にしました。批判の対象が同じでも、根拠がちがえば別の立場になる点が、ひっかけになりやすいところです。', key: '国学は日本の古典を根拠に、富永仲基は思想の歴史的な成り立ち(加上説)を、山片蟠桃は合理的な推論と科学を根拠に、既成の教えを批判した。', ex: [{ q: '次の資料は、ある江戸時代の思想家の考えを要約したものである。だれの考えか答え、その考えの名前を答えよう。\n資料「どの教えも、それ以前にあった教えに対抗するために、自分たちはもっと古く、もっと優れた教えを受けついでいると主張し、新しい説をつけ加えてきた。だから、教えの内容を時代の順に並べると、後のものほど話が大きくなっている。仏教も儒教も神道も、こうして成り立ったものであり、どれか一つを絶対の真理とすることはできない。」', hint: '「新しい説をつけ加えて」いくという、思想の成り立ちの見方に注目します。', steps: ['資料は、思想の内容の正しさではなく、思想がどのように成り立ってきたかという歴史的な成り立ちを分析している。', '後から現れた教えは、前の教えに対抗するため、より古い・より高い権威を主張する説を加え上げていく、という考え方である。', 'これは、富永仲基が説いた加上説である。', '仏教・儒教・神道のいずれも絶対視しない、という結論も、富永仲基の立場と一致する。'], a: '富永仲基、加上説', check: '「仏教も儒教も批判している」という点だけを見ると、国学者の本居宣長と迷うかもしれません。しかし宣長は、日本の古典に表れた「真心」を根拠にし、神道を批判したわけではありません。資料が神道まで相対化している点が決め手になります。' }, { q: '富永仲基は、加上説を仏教の経典にあてはめて、大乗仏教の経典について大胆な主張をした。どのような主張だったと考えられるか、加上説の考え方から推論しよう。', hint: '大乗仏教の経典は、上座部の経典と比べて、いつごろ成立したものでしょうか。', steps: ['加上説によれば、後から現れた教えは、前の教えより古く・高い権威を主張する説を加えてつくられている。', '大乗仏教は、釈迦の死後しばらくたってから、それまでの仏教(上座部などの部派仏教)を批判して現れた。', 'しかし大乗の経典は、自分たちの教えこそが釈迦の本当の教えだと主張している。', 'これを加上説で見ると、大乗の経典は、釈迦が直接説いたものではなく、後の人々が釈迦の権威を借りてつけ加えたものだ、という主張になる。'], a: '大乗仏教の経典は、釈迦が直接説いたものではなく、後の時代の人々が、それ以前の教えに説を加え上げてつくったものだという主張(大乗非仏説)。', check: '富永仲基のこの主張は、当時の仏教界に大きな衝撃を与えました。近代の仏教学でも、大乗経典が釈迦の死後に成立したことが研究によって確かめられており、仲基の分析の鋭さが評価されています。' }] }
    ],
    drill: [
      { lv: 2, q: '大正時代、主権のありかを問わずに、政治の目的は一般民衆の幸福にあり、政策の決定は民衆の意向にもとづくべきだと説いた吉野作造の考えを何といいますか。', a: '民本主義', exp: '民本主義は、デモクラシーを吉野作造が訳したことばです。主権が天皇にある大日本帝国憲法の下で、民衆のための政治を実現するために、主権の問題をあえて切りはなした点が特徴です。\n吉野は、その実現のために普通選挙と政党内閣を求め、大正デモクラシーの理論的な支えとなりました。\n「民本」の「本」は「もと・根本」という意味で、「民を政治の根本とする」という考えを表します。中国の孟子の「民を貴しと為す」という民本思想(民を政治の根本とする考え)と、ことばが似ていることにも注目できますが、吉野の民本主義は近代のデモクラシーの訳語である点で区別しましょう。' },
      { lv: 3, q: '吉野作造の民本主義は、のちに、主権のありかをあいまいにしていると批判されることもあった。それでも吉野がこの考えをとった意義を、当時の憲法と政治の状況にふれて説明しなさい。', a: '天皇主権の大日本帝国憲法の下では、国民主権を正面から主張すると、憲法に反する危険な思想として弾圧されかねなかった。吉野は、主権の問題を切りはなすことで、憲法の枠内で合法的に、普通選挙や政党内閣など、民衆の意見を政治に反映させるしくみを求めることができた。実際に、男子普通選挙の実現や政党内閣の成立を後押しし、政治への民衆の参加を広げた点に意義がある。', exp: '民本主義に対しては、社会主義の立場などから、「主権の問題を避けているので、本当のデモクラシーではない」という批判もありました。\nしかし、当時は天皇主権を否定する主張は許されにくく、強く主張すればかえって運動そのものがつぶされるおそれがありました。吉野は、理想をすべて一度に実現しようとするのではなく、現行の憲法の解釈の中で、実現可能な改革を一歩ずつ進めようとしたのです。\n答案では、「批判される点(主権の問題を避けた)」と「それでも意義がある点(憲法の枠内で現実の改革を進めた)」の両方を示すと、深い説明になります。' },
      { lv: 3, q: '山片蟠桃が『夢の代』で説いた無鬼論とはどのような考えか。また、それが当時の思想の中でどのような特徴をもっていたかを説明しなさい。', a: '無鬼論とは、死後の霊魂や鬼神(神霊・たたり)は存在しないとする考えである。山片蟠桃は、人の精神は肉体とともにはたらくものであり、死ねばなくなると考え、迷信を退けた。西洋の天文学を学んで地動説を支持するなど、自然の観察と合理的な推論を重んじた点で、古典や宗教の権威にたよる当時の多くの思想とは異なる、合理主義的な特徴をもっていた。', exp: '山片蟠桃は、大坂の商家の番頭として働きながら、懐徳堂で学んだ町人の学者です。『夢の代』では、天文・地理・歴史・経済など幅広い分野について論じました。\n無鬼論の「鬼」は、日本語でいう「おに」ではなく、中国の用法で「死者の霊・神霊」を意味します。ことばの意味の取りちがえに注意しましょう。\n当時の思想の多くは、儒教の経典や日本の古典、仏教の教えを根拠にしていました。蟠桃は、観察や実証にもとづく考え方を重んじた点で、近代の科学的な考え方に近い立場をとった人物として評価されています。' }
    ],
    faq: [
      ['吉野作造の民本主義と、美濃部達吉の天皇機関説は、どう関係しているの?', 'どちらも大正デモクラシーを支えた理論です。美濃部達吉の【天皇機関説】は、統治権は法人としての国家にあり、天皇は国家の最高の機関として、憲法にしたがって統治権を行使する、という憲法の解釈です。\n天皇の権力も憲法にしばられるとすることで、議会や内閣の役割を重くみる政党政治を憲法の面から支えました。吉野の民本主義が政治の目的と方法を、美濃部の説が憲法の解釈を担った、と整理できます。しかし1935年には天皇機関説が攻撃され、美濃部の著書は発禁となりました。'],
      ['懐徳堂とは、どんな学校だったの?', '18世紀前半に、大坂の有力な商人たちがお金を出し合ってつくった学問所です。のちに幕府にも認められました。\n商人の子弟や町人が、仕事のかたわら儒学などを学び、身分にかかわらず学べることが特徴でした。ここから、富永仲基や山片蟠桃のような、自由で合理的な考え方をする学者が育ちました。商業の中心地であった大坂の町人の経済力と知的な関心の高さを示す存在です。']
    ]
  });

  add('ri_bio', {
    secs: [
      { h: 'さらに深く:「よりよい命」を選ぶことの危うさ──優生思想の歴史から考える', t: '出生前診断やゲノム編集の議論で、「命の選別につながる」という心配がくり返し語られるのはなぜでしょうか。その背景には、【優生思想】が実際に大きな人権侵害を生んだ歴史があります。\n優生思想とは、人間の遺伝的な性質に優劣をつけ、「優れた」性質を残し、「劣った」とされた性質を社会から減らそうとする考えです。19世紀後半にイギリスで「優生学」が提唱され、20世紀前半には多くの国で政策として取り入れられました。ナチス・ドイツは、障害のある人々などに強制的に不妊手術を行い、さらには多くの命をうばいました。\n日本でも、1948年に制定された【旧優生保護法】が、「不良な子孫の出生を防止する」ことを目的の一つにかかげ、障害のある人などに対して、本人の同意がなくても不妊手術を行うことを認めていました。この規定は1996年に法律が改正(母体保護法)されるまで続き、多くの人が手術を強いられました。2024年には最高裁判所が、この規定は個人の尊重や法の下の平等を定めた憲法に違反すると判断しました。\nこの歴史から学べるのは、【「社会のため」という名目で、ある人の命の価値を他人が判断する】ことの危うさです。現代の生殖医療は、国家の強制ではなく、個人の選択として行われます。それでも、多くの人が同じ選択をすれば、障害のある人が「生まれてこないほうがよかった」と見なされる社会につながらないか、という問いが残ります。自己決定権の尊重と、命の平等をどう両立させるかが、生命倫理の大きな課題なのです。', key: '優生思想は、命に優劣をつけ、国家が「不良」とした人の出生を防いだ歴史をもつ。個人の選択としての生殖医療にも、命の選別につながらないかという問いが向けられている。', ex: [{ q: '旧優生保護法の下で行われた、本人の同意のない不妊手術は、生命倫理の考え方から見てどのような点で問題があったか。「自己決定権」「人間の尊厳」の2語を使って説明しよう。', hint: '子どもを産むかどうかを決めるのは、本来だれでしょうか。', steps: ['子どもをもつかどうか、産むかどうかは、その人の人生にかかわる、きわめて個人的で重要な決定である。', 'その決定は、本人が自分で行うべきものであり、これは自己決定権の中心的な内容の一つである。', '本人の同意なしに不妊手術を行うことは、この自己決定権を国家が一方的にうばうことになる。', 'さらに、「不良な子孫」という考え方は、障害などを理由に人の命の価値に優劣をつけるものであり、すべての人がかけがえのない価値をもつという人間の尊厳を否定するものである。'], a: '子どもを産むかどうかという、本人が決めるべき重要なことがらについて、本人の同意なしに手術を行ったことは、自己決定権を国家がうばうものであった。また、障害などを理由に「不良な子孫」とみなす考え方は、命に優劣をつけ、すべての人がもつ人間の尊厳を否定するものだった。', check: 'カントの考えで言えば、人を「社会をよくする」という目的のための単なる手段として扱ったことになります。生命倫理の議論と、これまでに学んだ倫理学を結びつけられるか確かめましょう。' }] },
      { h: '実戦演習:生命倫理の四原則で、医療の難しい判断を整理する', t: '医療の倫理的な判断を整理するために、アメリカの研究者ビーチャムとチルドレスが示した【生命医学倫理の四原則】がよく使われます。\n①【自律尊重原則】:判断能力のある患者が自分で決めたことを尊重する。\n②【無危害原則】:患者に害を与えない。\n③【善行原則】:患者の利益になることを行う。\n④【正義原則】:医療の利益と負担を、公平に分配する。\n実際の問題では、これらの原則が【ぶつかり合う】ことがあります。たとえば、患者が治療を拒否したとき、自律尊重原則は本人の決定を尊重せよと言い、善行原則は治療したほうが本人の利益になると言います。\n問題を解くときは、まず事例の中で「だれの、どの原則が問題になっているか」を特定し、次に「どの原則とどの原則が対立しているか」を整理しましょう。\n典型的な落とし穴は、「患者のためになるから」という善行原則だけで判断を正当化し、パターナリズムにおちいることです。', key: '自律尊重・無危害・善行・正義の四原則で事例を整理する。原則どうしの対立を見つけることが、判断の出発点になる。', ex: [{ q: '大地震で多くのけが人が一つの病院に運ばれてきた。医師と医薬品の数は限られている。病院は、けが人の重症度と、治療によって助かる見込みにもとづいて、治療の優先順位を決めることにした(トリアージ)。その結果、すぐに治療すれば助かる人が優先され、ほぼ助かる見込みのない重篤な人や、治療を待っても命に別状のない軽症の人は、後回しになった。この判断を、生命倫理の四原則と、功利主義の考え方から説明しよう。', hint: '限られた医療資源を、どう分配するかという問題です。', steps: ['この場面では、医療資源が限られているため、すべての人を同時に治療することはできない。そのため、医療の利益をどう分配するかという正義原則が中心的な問題になる。', 'トリアージは、助かる見込みの高い人から治療することで、できるだけ多くの命を救おうとする。これは、全体の幸福(救われる命)を最大にしようとする功利主義の考え方と一致する。', '一方で、後回しにされた重篤な人にとっては、善行原則(その人の利益になることを行う)が十分に満たされないという対立がある。', 'そのため、トリアージは、事前に定めた医学的な基準にもとづき、だれに対しても同じように適用することで、身分や財産などによる差別をしない公平さ(正義原則)を確保しようとしている。'], a: '限られた医療資源を、できるだけ多くの命を救うように配分する判断であり、功利主義(救われる命の最大化)の考え方に合う。また、医学的な基準をすべての人に同じように適用することで、正義原則(公平な分配)を満たそうとしている。ただし、後回しにされる人に対する善行原則とは対立する面がある。', check: 'ふだんの医療では、目の前の一人の患者に最善を尽くすこと(善行原則)が基本です。災害時に判断が変わるのは、資源の不足によって正義原則の重みが大きくなるためだ、と整理できます。' }] }
    ],
    drill: [
      { lv: 2, q: '生命医学倫理の四原則のうち、医療の利益と負担を、人々の間で公平に分配することを求める原則を何といいますか。', a: '正義原則', exp: '四原則は、自律尊重原則・無危害原則・善行原則・正義原則の4つです。正義原則は、限られた医療資源(医師、薬、臓器、病床など)を、差別なく公平に分配することを求めます。\nたとえば、臓器移植を受ける人を選ぶとき、お金持ちや有名人が優先されるのは正義原則に反します。医学的な緊急度や適合の程度など、だれにでも同じように適用できる基準が求められます。\n「正義」は、日常のことばでは「正しいこと」全般を指しますが、この原則では「公平な分配」という特定の意味で使われている点に注意しましょう。倫理学では、アリストテレスの配分的正義の考え方にも通じます。' },
      { lv: 3, q: '判断能力のある成人の患者が、医師から「手術をすれば治る見込みが高い」と説明を受けたうえで、手術を拒否した。この場面で対立している生命倫理の原則を2つ挙げ、医師がとるべき対応を説明しなさい。', a: '対立しているのは、患者の決定を尊重する自律尊重原則と、患者の利益になる治療を行おうとする善行原則である。医師は、患者がなぜ拒否するのかをよく聞き、誤解や不安があれば十分に説明し直すべきだが、そのうえで判断能力のある患者が拒否を続けるなら、その決定を尊重し、強制的に手術を行うべきではない。', exp: '医師から見れば、手術をすれば治るのですから、手術をすることが患者の利益(善行原則)になります。しかし、自分の体にどのような治療を受けるかを決めるのは、判断能力のある患者本人です(自律尊重原則)。\n患者の利益のためだからといって、本人の意思に反して治療を行うことは、パターナリズムにあたります。インフォームド・コンセントの考え方では、医師の役割は、十分な説明を行い、患者が理解して決定できるよう支えることです。\nただし、「拒否されたらすぐにあきらめる」のでもありません。拒否の理由(費用・痛みへの不安・誤解など)を確かめ、別の治療法も示すなど、対話を重ねることが大切です。' },
      { lv: 3, q: '「障害のある胎児を産むかどうかは、親が決める自由がある」という主張と、「出生前診断の結果による中絶が広がることは、命の選別につながる」という主張がある。両者の対立を、優生思想の歴史をふまえて説明しなさい。', a: '前者は、子どもを産むかどうかは、育てる責任を負う親(とくに妊娠している女性)の自己決定権にもとづくという主張である。後者は、かつて国家が障害のある人などの出生を防いだ優生思想の歴史をふまえ、国家の強制でなくても、多くの人が同じ選択をすれば、障害のある人の命の価値を低く見る社会になるおそれがあるという主張である。自己決定権の尊重と、すべての命の平等という価値が対立している。', exp: '旧優生保護法やナチス・ドイツの政策は、国家が「不良」とみなした人々の出生を強制的に防ぐものでした。現代の出生前診断は、国家の強制ではなく、個人の選択として行われる点で大きくちがいます。\nそれでも、「障害があるから産まない」という選択が社会の中で当然とされるようになると、障害のある人が生きにくい社会になるのではないか、という批判があります。一方、女性の身体と人生にかかわる決定を、他人が制限することにも大きな問題があります。\nどちらか一方を正解とするのではなく、何と何の価値がぶつかっているのかを正確に説明できることが大切です。障害のある子どもを育てやすい社会づくりという視点も加えると、答案に深みが出ます。' }
    ],
    faq: [
      ['優生思想は、もう過去の問題なの?', '国家が強制的に不妊手術を行うような政策は、現在の日本では行われていません。しかし、旧優生保護法による被害の救済は、2010年代から2020年代にかけて大きな社会問題になりました。\nまた、出生前診断やゲノム編集など、技術の進歩によって、親が子どもの遺伝的な性質を知ったり選んだりできる範囲は広がっています。「強制」がなくても、社会の雰囲気が人々の選択を一つの方向に導くことはありうるため、優生思想は今も考え続けるべき問題だといえます。'],
      ['生命倫理の四原則は、どれがいちばん大切なの?', '四原則の間に、あらかじめ決まった優先順位はありません。どの原則も大切で、具体的な事例の中で、どの原則をどの程度重く見るかを考える必要があります。\nただし、現代の医療では、パターナリズムへの反省から、自律尊重原則が特に重視される傾向があります。一方で、判断能力が十分でない人(幼い子どもや意識のない患者など)の場合には、善行原則や無危害原則がより重い意味をもつことになります。']
    ]
  });

  add('pk_kenpo', {
    secs: [
      { h: 'さらに深く:生存権は「裁判で使える権利」か──プログラム規定説と朝日訴訟・堀木訴訟', t: '憲法第25条1項は、「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」と定めています。では、生活が苦しい人は、この条文だけを根拠に、裁判で国にお金を請求できるのでしょうか。\nこの問題について、かつて有力だったのが【プログラム規定説】です。第25条は、国が政治を行ううえでの目標(プログラム)を示したもので、個々の国民に、裁判で主張できる具体的な権利を与えたものではない、という考え方です。これに対して、第25条は法的な権利を定めているが、その中身は法律によって具体化される、とする考え方(法的権利説)も主張されてきました。\nこの問題が争われたのが【朝日訴訟】です。結核で療養していた朝日茂さんは、生活保護で支給される日用品費(月600円)では、健康で文化的な生活はできないと訴えました。最高裁判所は1967年、朝日さんの死亡により訴訟は終了したとしつつ、意見として、第25条は国民に直接具体的な権利を与えたものではなく、何が「健康で文化的な最低限度の生活」かの判断は、厚生大臣の裁量にゆだねられる、と述べました。\n1982年の【堀木訴訟】でも、最高裁は、障害福祉年金と児童扶養手当の併給を禁止した法律について、社会保障の制度の内容は【立法府の広い裁量】にゆだねられるとして、合憲と判断しました。\n裁判所が国の判断を尊重するのは、社会保障には予算が必要で、限られた財源をどう配分するかは、国民に選ばれた国会や内閣が専門的・政策的に判断すべきだと考えるからです。ただし朝日訴訟は「人間裁判」とよばれて社会の関心を集め、生活保護の基準の見直しにつながりました。', key: '最高裁は、生存権の中身の判断を国会や行政の広い裁量にゆだねる立場をとる。社会権は予算をともなうため、裁判所の審査はゆるやかになりやすい。', ex: [{ q: '裁判所が、生存権にかかわる法律や行政の判断について、精神の自由にかかわる場合よりも、国会や行政の判断を尊重する(ゆるやかに審査する)傾向があるのはなぜか。「予算」「民主政治」の2語を使って説明しよう。', hint: '生存権を実現するには、何が必要でしょうか。また、それを決めるのはだれがふさわしいでしょうか。', steps: ['生存権の実現には、生活保護や年金などの給付が必要であり、それには国の予算(財源)が必要である。', '限られた予算を、福祉・教育・防衛などのどこにどれだけ配分するかは、国全体の事情を考えた政策的な判断である。', 'こうした判断は、選挙で選ばれ国民に責任を負う国会や内閣が、民主政治の過程を通じて行うのがふさわしいと考えられる。', 'そのため裁判所は、明らかに不合理な場合を除いて、国会や行政の判断(裁量)を尊重する。一方、精神の自由が侵されると民主政治そのものが傷つくので、裁判所がきびしく審査する必要がある。'], a: '生存権の実現には予算が必要で、その配分は国の財政全体を考えた政策的な判断になる。こうした判断は、民主政治の過程を通じて国民に選ばれた国会や内閣が行うのがふさわしいので、裁判所は明らかに不合理でないかぎり、その裁量を尊重するから。', check: 'これは「二重の基準」の考え方とも一致します。経済的な自由や社会権の制度は民主政治の過程で修正できるが、精神の自由が侵されると、その過程そのものが働かなくなる、という理由を確かめておきましょう。' }] },
      { h: '実戦演習:平等権の判例を「区別の目的」と「手段」で読み解く', t: '憲法第14条の「法の下の平等」は、すべての人をまったく同じに扱うこと(絶対的平等)を求めているのではありません。年齢や所得のちがいなどに応じて扱いを変えることは、【合理的な理由があれば許される】(相対的平等)と考えられています。判例を読むときは、次の2段階で考えると整理しやすくなります。\n①【区別の目的】は正当か。\n②【区別の手段】が、その目的と合理的に結びついているか。\n入試では、判決の結論だけでなく、「なぜ違憲とされたのか」が問われるようになっています。特に、【本人が自分の意思や努力では変えられないこと】(生まれ方など)を理由にした不利益や、【社会の変化】によって区別の理由が失われたことが、違憲の判断につながった例が多い点に注目しましょう。\n落とし穴は、「区別がある=違憲」と単純に考えることです。区別そのものではなく、その理由と程度が問われていることを忘れないようにしましょう。', key: '平等の判例は「目的が正当か」「手段が目的と合理的に結びつくか」の2段階で読む。本人が変えられない事情による不利益は、きびしく見られる。', ex: [{ q: '2008年、最高裁判所は国籍法の規定を違憲とした。当時の国籍法では、日本人の父と外国人の母の間に生まれ、生まれた後に父から認知された子は、父母が結婚した場合にかぎって、届け出によって日本の国籍を取得できるとされていた。最高裁がこの「父母の結婚」という要件を違憲とした理由を、「区別の目的」と「手段」に分けて説明しよう。', hint: '国籍を与える条件として、何が求められているのかを考えます。結婚するかどうかは、子どもが決められることでしょうか。', steps: ['この規定の目的は、日本と密接な結びつきのある子に国籍を与えることにあり、目的そのものは正当だと考えられた。', '手段として、父母の結婚を、日本との結びつきを示す条件にしていた。', 'しかし、家族のあり方が多様になった現代では、父母が結婚していなくても、日本で生活し、日本と密接な結びつきをもつ子は多い。つまり、手段が目的と合理的に結びつかなくなっていた。', 'さらに、父母が結婚するかどうかは、子ども自身には変えられないことであり、それを理由に国籍の取得という重要な利益に差をつけることは、合理的な理由のない差別にあたると判断された。'], a: '日本との密接な結びつきのある子に国籍を与えるという目的は正当だが、家族のあり方が多様化した現在では、父母の結婚を条件とすることはその目的と合理的に結びつかず、しかも子ども自身が変えられない事情で国籍の取得に差をつけるものであるため、法の下の平等に反するとされた。', check: '2013年の婚外子の相続分の違憲決定も、「子にとって自ら選べない事柄を理由に不利益を与えることは許されない」という同じ考え方を示しています。2つの判例を同じ物差しで説明できるか確かめましょう。' }, { q: '次のア〜ウの区別のうち、合理的な区別として一般に認められているものをすべて選び、その理由を答えよう。\nア 所得の多い人ほど、所得税の税率を高くする。\nイ 選挙権を、満18歳以上の国民に与える。\nウ 同じ仕事をしている労働者の賃金を、性別だけを理由に変える。', hint: '区別の目的と、その手段が結びついているかを考えます。', steps: ['アの目的は、税を負担する能力に応じた公平な課税と、所得の再分配である。所得が多いほど負担能力が高いので、手段として合理的である。', 'イの目的は、政治について判断できる能力をもつ人に選挙権を与えることである。一定の年齢で線を引くことは、その目的と結びついた合理的な手段とされる。', 'ウは、同じ仕事をしているのに、性別という仕事の内容と関係のない理由で差をつけている。目的と手段の合理的な結びつきがなく、労働基準法も、女性であることを理由とする賃金の差別を禁止している。', 'よって、合理的な区別はアとイである。'], a: 'アとイ。アは税の負担能力に応じた公平な課税という目的に、イは政治的な判断能力をもつ人に選挙権を与えるという目的に、それぞれ合理的に結びついた区別だから。ウは、仕事の内容と関係のない性別を理由にした差別であり、合理的とはいえない。', check: 'イのように年齢で線を引くと、17歳でも十分な判断力をもつ人は不利益を受けます。それでも、一人ひとりの能力を調べることは不可能なので、一律の線引きが合理的とされるのです。「合理的=完全に公平」ではないことに注意しましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '憲法第25条は、国が政治を行ううえでの目標や方針を示したもので、個々の国民に裁判で主張できる具体的な権利を与えたものではないとする考え方を何という?', a: 'プログラム規定説', exp: 'プログラム規定説では、第25条は国の「努力目標」を示したものとされ、国民は、この条文だけを根拠に国に具体的な給付を請求することはできません。\nこれに対して、第25条は法的な権利を定めているとする考え方には、生活保護法などの法律によって具体化されてはじめて裁判で主張できるとする説(抽象的権利説)などがあります。\n最高裁判所は、朝日訴訟(1967年)や堀木訴訟(1982年)で、生存権の中身の判断は、国会や行政の広い裁量にゆだねられるという立場を示しました。「プログラム」は、ここではコンピュータの命令ではなく、「計画・方針」という意味で使われていることにも注意しましょう。' },
      { lv: 3, q: '朝日訴訟で争われた内容と、最高裁判所の判断を説明しなさい。また、この訴訟が社会にどのような影響を与えたか述べなさい。', a: '結核で療養していた朝日茂さんが、生活保護の日用品費(月600円)が低すぎて、憲法第25条の健康で文化的な最低限度の生活を保障していないと訴えた。最高裁は1967年、朝日さんの死亡で訴訟は終了したとしたうえで、何が健康で文化的な最低限度の生活かの判断は厚生大臣の裁量にゆだねられると述べた。この訴訟は「人間裁判」とよばれて社会の関心を集め、生活保護の基準の引き上げなど、社会保障の見直しにつながった。', exp: '朝日訴訟は、生存権が裁判で本格的に争われた最初の大きな事件です。第一審では朝日さんの主張が認められましたが、第二審で逆転し、最高裁への上告中に朝日さんが亡くなりました。\n最高裁は、生活保護を受ける権利は本人だけのもので、相続できないとして訴訟を終わらせました。そのうえで、「念のため」として、生存権についての考え方を示しました。\n裁判の結果は朝日さんの敗訴に近いものでしたが、裁判を通じて生活保護の水準の低さが広く知られ、制度の改善を後押ししました。裁判の「結論」と「社会への影響」を分けて説明できるようにしておきましょう。' },
      { lv: 3, q: '2013年に最高裁判所が、婚外子(結婚していない男女の間に生まれた子)の相続分を、結婚した夫婦の子の2分の1とする民法の規定を違憲とした理由を、「社会の変化」と「子ども自身」という2つの観点から説明しなさい。', a: '社会の変化:家族のあり方や結婚に対する国民の意識が多様化し、諸外国でも婚外子の相続分の差別をなくす動きが進んだため、この区別を支える合理的な理由が失われた。子ども自身:父母が結婚しているかどうかは、子ども自身が選んだり変えたりできない事柄であり、それを理由に子どもに不利益を与えることは許されない。', exp: 'この規定は、かつては「法律上の結婚を尊重する」という目的のための合理的な区別だとして、1995年に最高裁で合憲とされていました。\nしかし2013年の決定は、その後の家族の多様化や、国際的な人権の考え方の広がり、国内の法制度の変化などをふまえ、区別の合理性はすでに失われたと判断しました。同じ規定でも、社会の変化によって合憲から違憲へと判断が変わったことが大きな特徴です。\nこの決定を受けて、同じ年に民法が改正され、相続分は平等になりました。「憲法の条文は同じでも、その解釈は社会の変化によって変わりうる」という点も押さえておきましょう。' }
    ],
    faq: [
      ['憲法第25条2項の「国の努力義務」は、1項とどう関係しているの?', '1項は、国民が「健康で文化的な最低限度の生活を営む権利」をもつことを定めています。2項は、国が「社会福祉、社会保障及び公衆衛生の向上及び増進」に努めなければならないと定めています。\n1項が国民の側から見た権利、2項がそれを実現するための国の責務を表していると考えると、わかりやすいでしょう。生活保護法・国民年金法・健康保険法などは、この2つを具体化するための法律です。'],
      ['「合理的な区別」かどうかは、だれが、どうやって決めるの?', '最初に区別を定めるのは、法律をつくる国会です。その区別が憲法に反するかどうかは、具体的な事件の裁判の中で、最終的に裁判所(最高裁判所)が判断します。\n裁判所は、区別の目的が正当か、手段がその目的と合理的に結びついているかを検討します。その際、性別や生まれのように、本人が変えられない事情による区別や、選挙権のような重要な権利にかかわる区別は、よりきびしく審査されるべきだと考えられています。']
    ]
  });

  add('pk_seiji', {
    secs: [
      { h: 'さらに深く:選挙制度は政党の数を変える──デュヴェルジェの法則と並立制・併用制', t: '小選挙区制は二大政党制、比例代表制は多党制になりやすい、という傾向は、フランスの政治学者の名をとって【デュヴェルジェの法則】とよばれます。なぜこうなるのでしょうか。理由は2つあります。\n1つめは【機械的な効果】です。小選挙区制では、各選挙区で1位にならなければ議席を得られません。全国で20%の票を得た第3党でも、どの選挙区でも2位や3位なら、議席はほとんど得られません。\n2つめは【心理的な効果】です。有権者は、自分の票が死票になるのをさけるため、本当は第3党を支持していても、当選の見こみのある大きな2党のどちらかに投票しがちです。政治家も、当選するために大きな政党に集まろうとします。\nこの2つの効果で、小選挙区制では大きな2つの政党が残りやすくなるのです。比例代表制では、得票率に応じて議席が配分されるので、小さな政党も議席を得られ、多党制になりやすくなります。\n日本の衆議院の【小選挙区比例代表並立制】は、小選挙区と比例代表の議席を、それぞれ別々に決めて足し合わせる方式です。そのため、議席の多くをしめる小選挙区の効果が強く出て、第一党が得票率以上の議席を得やすくなります。\nこれに対して、ドイツなどで用いられてきた【小選挙区比例代表併用制】では、各党の議席の総数は基本的に比例代表の得票で決まり、その枠の中で小選挙区の当選者が優先して議席を得ます。そのため、全体の議席配分は得票率に近くなります。同じ「小選挙区+比例代表」でも、組み合わせ方で結果は大きく変わるのです。', key: '小選挙区制は、機械的効果(1位しか当選しない)と心理的効果(死票をさける投票)で二大政党制をうながす。並立制は小選挙区の効果が強く、併用制は全体が比例的になる。', ex: [{ q: '定数100の議会で、全国の得票率がA党46%、B党34%、C党20%だった。小選挙区(50議席)では、A党が35議席、B党が15議席を得て、C党は0議席だった。比例代表の部分(50議席)は得票率どおりに配分されるものとする。(1)並立制の場合と、(2)全体を得票率どおりにする併用制の場合で、各党の議席数を求めよう。', hint: '並立制は「小選挙区+比例代表」を足すだけ、併用制は「全体の議席を得票率で決める」方式です。', steps: ['比例代表50議席を得票率どおりに配分すると、A党50×0.46=23、B党50×0.34=17、C党50×0.2=10議席。', '(1)並立制では、小選挙区と比例代表をそのまま足す。A党35+23=58、B党15+17=32、C党0+10=10議席。', '(2)併用制では、全体100議席を得票率で配分する。A党46、B党34、C党20議席。', '併用制では、各党の小選挙区の当選者(A党35、B党15)は、この総数の枠の中に入る。たとえばA党は、46議席のうち35議席を小選挙区の当選者が、残り11議席を比例名簿の候補者が得る。'], a: '(1)並立制:A党58、B党32、C党10議席 (2)併用制:A党46、B党34、C党20議席', check: '並立制ではA党が得票率46%で議席の58%を得て過半数をこえていますが、併用制では得票率どおりで、どの党も単独では過半数をとれません。小選挙区の結果を「足す」か「枠の中に入れる」かで、政権のでき方まで変わることがわかります。' }] },
      { h: '実戦演習:惜敗率の計算と「ねじれ国会」を読み解く', t: '衆議院の選挙では、小選挙区と比例代表の両方に立候補する【重複立候補】が認められています。政党は、比例代表の名簿で重複立候補者を【同じ順位】に並べることができ、その場合、小選挙区で落選した候補者の中から、【惜敗率】の高い順に比例代表で当選が決まります。\n惜敗率=(自分の得票数÷その小選挙区の当選者の得票数)×100(%)\nただし、小選挙区での得票が有効投票総数の10分の1に満たなかった候補者は、比例代表で復活当選することはできません。計算問題では、自分の得票を【自分の選挙区の当選者】の得票で割ることに注意しましょう。\nもう一つの頻出テーマが【ねじれ国会】です。衆議院と参議院で多数をしめる勢力が異なる状態をいいます。予算・条約の承認・内閣総理大臣の指名は衆議院の優越で決まりますが、法律案は、参議院で否決されると、衆議院で出席議員の3分の2以上の多数で再可決しなければ成立しません。', key: '惜敗率は「自分の得票÷自分の選挙区の当選者の得票」。ねじれ国会では、予算や首相指名は衆議院で決まるが、法律案は衆議院の3分の2の再可決が必要になる。', ex: [{ q: 'X党は、比例代表の名簿の1位に、重複立候補したP・Q・Rの3人を同じ順位で並べた。3人とも小選挙区で落選し、X党は比例代表で2議席を獲得した(名簿1位の3人以外に上位の候補はいない)。小選挙区の結果は次のとおりである。比例代表で当選するのはだれとだれか。\nP:得票6万票(その選挙区の当選者は8万票、有効投票総数は16万票)\nQ:得票5万票(その選挙区の当選者は5万5千票、有効投票総数は12万票)\nR:得票4万8千票(その選挙区の当選者は6万票、有効投票総数は15万票)', hint: '得票数の多さではなく、惜敗率の高さで決まります。10分の1の条件も確かめます。', steps: ['まず、3人とも有効投票総数の10分の1(P:1万6千票、Q:1万2千票、R:1万5千票)以上の票を得ているので、全員が復活当選の対象になる。', 'Pの惜敗率は 6万÷8万×100=75%。', 'Qの惜敗率は 5万÷5万5千×100≒90.9%。', 'Rの惜敗率は 4万8千÷6万×100=80%。', '惜敗率の高い順に、Q(約90.9%)→R(80%)→P(75%)となる。当選は2議席なので、QとRが当選する。'], a: 'QとR(得票数が最も多いPは、惜敗率が最も低いため当選しない)', check: '得票数だけを見るとP(6万票)が最多ですが、惜敗率ではPが最も低くなります。なお、惜敗率が同じ候補者が並んだ場合は、くじで順番を決めます。「当選者にどれだけ迫ったか」を比べる制度なので、選挙区の大きさや接戦かどうかで順位が変わることを確かめましょう。' }, { q: '与党は衆議院で過半数をもつが3分の2未満、参議院では野党が過半数をもつ「ねじれ国会」の状態にある。次の(1)〜(3)は、与党の賛成だけで成立(決定)させることができるか。\n(1)予算 (2)法律案 (3)内閣総理大臣の指名', hint: '衆議院の優越が認められている事項と、再可決が必要な事項を区別します。', steps: ['(1)予算は、参議院が衆議院と異なる議決をし、両院協議会でも意見が一致しないとき(または参議院が30日以内に議決しないとき)、衆議院の議決が国会の議決になる。よって与党の衆議院の過半数で成立できる。', '(2)法律案は、参議院で否決されると、衆議院で出席議員の3分の2以上で再可決しなければ成立しない。与党は3分の2未満なので、与党だけでは成立させられない。', '(3)内閣総理大臣の指名は、両院の指名が異なり、両院協議会でも一致しないとき(または参議院が10日以内に指名しないとき)、衆議院の指名が国会の指名になる。よって与党だけで決定できる。', 'したがって、与党だけで決められるのは(1)と(3)である。'], a: '(1)できる (2)できない(衆議院で3分の2以上の再可決が必要) (3)できる', check: 'ねじれ国会では、首相は選べて予算も通るのに、予算を実行するための関連法案が成立しない、という事態が起こりえます。実際に2000年代後半から2010年代前半には、ねじれ国会で法案の審議が停滞したことがありました。' }] }
    ],
    drill: [
      { lv: 2, q: '衆議院の比例代表で重複立候補者を同じ順位に並べた場合、当選の順番を決めるために使われる、「小選挙区での自分の得票数÷その選挙区の当選者の得票数×100」で求める値を何という?', a: '惜敗率', exp: '惜敗率は、小選挙区で落選した候補者が、当選者にどれだけ迫ったかを表す割合です。値が100%に近いほど接戦だったことになり、比例代表での当選の順番が上になります。\nこの制度によって、小選挙区で落選しても比例代表で当選する「復活当選」が起こります。復活当選には、民意を幅広く反映できるという評価と、小選挙区で落選した人が当選するのはわかりにくいという批判の両方があります。\nなお、小選挙区での得票が有効投票総数の10分の1未満の候補者は、復活当選できません。「惜しくも敗れた率」という字の意味から覚えると、計算の分母(当選者の得票)をまちがえにくくなります。' },
      { lv: 3, q: '小選挙区制が二大政党制をうながしやすい理由を、「機械的な効果」と「心理的な効果」に分けて説明しなさい。', a: '機械的な効果:各選挙区で1位の候補者しか当選しないため、全国で一定の票を得ても、どの選挙区でも1位になれない小さな政党は議席をほとんど得られない。心理的な効果:有権者は自分の票が死票になるのをさけるため、当選の見こみのある大きな2つの政党のどちらかに投票しやすくなり、政治家も大きな政党に集まりやすくなる。', exp: 'この傾向は、フランスの政治学者デュヴェルジェが指摘したことから、デュヴェルジェの法則とよばれます。\n機械的な効果は、選挙制度のしくみそのものが、得票を議席に変えるときに小さな政党を不利にすることです。心理的な効果は、そのしくみを知っている有権者や政治家の行動が、さらに大きな政党への集中を強めることです。\nただし、地域によって強い政党がちがう国(地域政党が強い国)では、小選挙区制でも多くの政党が議席を得ることがあります。「法則」といっても、必ずそうなるわけではなく、「傾向」であることに注意しましょう。' },
      { lv: 3, q: '日本の衆議院の小選挙区比例代表並立制と、ドイツなどの小選挙区比例代表併用制のちがいを、各党の議席の総数の決まり方に注目して説明しなさい。', a: '並立制では、小選挙区の議席と比例代表の議席をそれぞれ別々に決め、それを足し合わせて各党の議席数とする。そのため、小選挙区の結果が強く反映され、大きな政党が得票率以上の議席を得やすい。併用制では、各党の議席の総数は基本的に比例代表の得票率で決まり、その枠の中で小選挙区の当選者が優先して議席を得る。そのため、全体の議席配分は得票率に近くなる。', exp: '名前はよく似ていますが、「並立」は2つの制度を横に並べて足すだけ、「併用」は比例代表を土台にして小選挙区を組みこむ、というちがいがあります。\n並立制は、二大政党制や安定した政権をつくりやすい一方で、少数意見が議席に反映されにくいという面があります。併用制は、得票率に近い議席配分になり、少数意見も反映されやすい一方で、単独で過半数をとる政党が出にくく、連立政権になりやすい面があります。\n計算問題では、「足す」のか「総数の枠の中に入れる」のかで答えが大きく変わります。名前と方式の対応をしっかり確かめましょう。' }
    ],
    faq: [
      ['小選挙区制と比例代表制は、結局どちらがよい制度なの?', 'どちらにも長所と短所があり、何を重視するかによって評価が変わります。小選挙区制は、政権を担う政党がはっきりして政治が安定しやすく、政権交代も起こりやすい一方で、死票が多く、少数意見が反映されにくくなります。\n比例代表制は、民意を議席に正確に反映しやすい一方で、小さな政党が多く生まれて連立政権になりやすく、政治が不安定になることもあります。多くの国が、両方を組み合わせた制度を工夫しているのはこのためです。'],
      ['ねじれ国会は、悪いことなの?', '一概に悪いとはいえません。法律案が成立しにくくなり、政治の決定がおくれるという問題がある一方で、参議院が衆議院の行きすぎをおさえる「良識の府」としての役割を果たしやすくなる面もあります。\n与党と野党が話し合い、修正を重ねて合意をつくる機会が増えるという評価もあります。二院制の意義と、決定の速さのどちらを重視するかによって、評価が分かれるテーマです。']
    ]
  });

  add('pk_keizai', {
    secs: [
      { h: 'さらに深く:市場はなぜ「効率的」なのか──消費者余剰と生産者余剰', t: '需要と供給が一致する均衡価格で取引されると、社会全体にとって最も望ましい状態になる、といわれます。なぜそう言えるのでしょうか。カギになるのが【余剰】という考え方です。\nある人が、ある商品に「最大で100円までなら払ってもよい」と思っているとします。その商品が60円で買えたなら、この人は40円ぶん得をしたと考えられます。この得を【消費者余剰】といいます。需要曲線は、人々が「払ってもよい」と思う最大の金額を並べたものなので、グラフでは、需要曲線と価格の線ではさまれた部分の面積が、消費者余剰の合計になります。\n同じように、生産者が「最低でも50円で売れれば生産してよい」と考えている商品を60円で売れたなら、10円ぶん得をします。これが【生産者余剰】で、価格の線と供給曲線ではさまれた部分の面積で表されます。\n消費者余剰と生産者余剰の合計を【総余剰】といい、取引によって社会全体が得た利益を表します。均衡価格で取引されると、「払ってもよい金額」が「生産にかかる費用」を上回る取引がすべて行われ、そうでない取引は行われないので、総余剰が最大になります。これが、市場が「効率的」だといわれる理由です。\n逆に、政府が価格の上限を決めたり、税をかけたりすると、本来なら行われたはずの取引が行われなくなり、総余剰が減ります。この失われた余剰を【死荷重(厚生の損失)】といいます。', key: '総余剰=消費者余剰+生産者余剰。均衡で取引すると総余剰が最大になり、価格の規制や課税は死荷重を生む。', ex: [{ q: 'ある商品の需要曲線が P=100−Q、供給曲線が P=Q で表される(Pは価格〔円〕、Qは数量〔個〕)。(1)均衡価格と均衡数量を求め、消費者余剰と生産者余剰を求めよう。(2)政府が価格の上限を30円と決めた場合、取引量はいくつになり、総余剰はどれだけ減るか。', hint: '余剰は三角形や台形の面積で求められます。価格の上限があると、売り手は供給曲線の分しか売りません。', steps: ['(1)100−Q=Q より Q=50、P=50。消費者余剰は、価格50と需要曲線の間の三角形で、底辺50×高さ(100−50)÷2=1250。生産者余剰は、価格50と供給曲線の間の三角形で、50×50÷2=1250。総余剰は2500。', '(2)価格が30円に決められると、売り手は供給曲線 P=Q より30個しか売らない。買い手は100−Q=30 より70個買いたいので、40個の品不足になる。取引量は少ないほうの30個。', '取引される30個について、総余剰は、需要曲線と供給曲線ではさまれた台形の面積になる。Q=0では需要100・供給0で差は100、Q=30では需要70・供給30で差は40。台形の面積は(100+40)×30÷2=2100。', '総余剰は2500から2100へ、400減る。これが死荷重で、取引されなくなった30〜50個の部分の三角形(底辺20×高さ40÷2=400)にあたる。'], a: '(1)均衡価格50円、均衡数量50個。消費者余剰1250、生産者余剰1250。 (2)取引量は30個。総余剰は400減る(2500→2100)。', check: '死荷重の三角形は、数量30〜50の間で、需要曲線(Q=30で70)と供給曲線(Q=30で30)の間の高さ40、底辺20なので、20×40÷2=400となり、差し引きの計算と一致します。' }] },
      { h: '実戦演習:税をかけると、だれが負担するのか', t: '商品1個あたりに一定額の税(従量税)を売り手に課すと、売り手は税の分だけ高い価格でなければ売らなくなるので、【供給曲線が税額の分だけ上へ】移動します。\n【税を納めるのが売り手でも、負担をするのは売り手だけではない】ということです。新しい均衡では、買い手の払う価格が上がり、売り手が税を引いた後に受けとる金額が下がります。\nどちらが多く負担するかは、曲線の【傾き(価格弾力性)】で決まります。価格が上がっても買う量があまり減らない(需要が非弾力的な)商品では、買い手は高い価格を受け入れるしかないので、買い手の負担が大きくなります。\n問題を解く手順は、①供給曲線の式に税額を足す、②新しい均衡を求める、③買い手の払う価格と、売り手の受けとる価格(買い手の価格−税額)を、もとの均衡価格と比べる、の3段階です。落とし穴は、「税を納めるのは売り手だから、売り手が全部負担する」と考えることです。', key: '従量税は供給曲線を税額分だけ上へ移す。税の負担は買い手と売り手で分け合い、需要が非弾力的なほど買い手の負担が大きくなる。', ex: [{ q: 'ある商品の需要曲線が P=90−2Q、供給曲線が P=Q で表される。政府が売り手に、1個あたり15円の税をかけた。(1)課税前と課税後の均衡数量を求めよう。(2)課税後に買い手が払う価格と、売り手が税を納めた後に受けとる金額を求め、税15円のうち買い手と売り手がそれぞれいくら負担しているか答えよう。', hint: '課税後の供給曲線は P=Q+15 です。', steps: ['課税前:90−2Q=Q より 3Q=90、Q=30。均衡価格は P=30円。', '課税後:供給曲線は税の分だけ上がって P=Q+15。90−2Q=Q+15 より 3Q=75、Q=25。', '買い手が払う価格は、需要曲線より P=90−2×25=40円。売り手が受けとる金額は、40−15=25円(供給曲線 P=Q で Q=25 のときの25円とも一致)。', 'もとの価格30円と比べると、買い手は40−30=10円多く払い、売り手は30−25=5円少なく受けとる。15円の税のうち、買い手が10円、売り手が5円を負担している。'], a: '(1)課税前30個、課税後25個 (2)買い手が払う価格40円、売り手が受けとる金額25円。負担は買い手10円、売り手5円。', check: '負担の合計は10+5=15円で、税額と一致します。この需要曲線は傾きが2で、供給曲線(傾き1)より急(需要が比較的非弾力的)なので、買い手の負担が大きくなっており、本文の説明とも合っています。税収は15×25=375円です。' }] }
    ],
    drill: [
      { lv: 2, q: '消費者が「この価格までなら払ってもよい」と考える最大の金額と、実際に支払った価格との差の合計を何という?', a: '消費者余剰', exp: '消費者余剰は、消費者が取引によって得た「得」を金額で表したものです。たとえば、最大300円まで払ってもよいと思っていた商品を200円で買えたら、100円の消費者余剰が生まれます。\nグラフでは、需要曲線と価格の線ではさまれた部分の面積になります。価格が下がると、すでに買っていた人の得が増えるうえ、新しく買う人も現れるので、消費者余剰は大きくなります。\nなお、日常のことばの「余剰」は「余り・余分なもの」という意味で、「余剰人員」「余剰農産物」のように使われます。経済学の「余剰」は「取引による得」という特別な意味なので、区別して覚えましょう。' },
      { lv: 3, q: 'ある商品の需要曲線が P=120−Q、供給曲線が P=Q で表される。政府がこの商品の価格の上限を40円と定めた。(1)品不足(超過需要)の量を求めよう。(2)この規制によって生じる死荷重(総余剰の減少分)を求めよう。', a: '(1)40個 (2)400', exp: '均衡は 120−Q=Q より Q=60、P=60円です。価格の上限が40円だと、売り手は P=Q より40個しか売りません。買い手は 120−Q=40 より80個買いたいので、80−40=40個の品不足になります。\n取引量は40個に減ります。本来は60個取引されるはずだったので、40〜60個の20個分の取引が失われます。Q=40 のとき、需要曲線の高さは80、供給曲線の高さは40なので、差は40です。死荷重は、この三角形の面積で 20×40÷2=400 です。\n価格の上限は、買い手を助けるために行われることが多いですが、実際には品不足が起こり、手に入らない人が出てしまいます。「価格を下げる規制=全員が得をする」とは限らないことが、余剰の考え方からわかります。' },
      { lv: 3, q: 'たばこのように、価格が上がっても需要量があまり減らない商品に税をかけた場合、税の負担と税収にはどのような特徴があるか。需要の価格弾力性と結びつけて説明しなさい。', a: '需要が非弾力的なので、課税で価格が上がっても買う量があまり減らない。そのため、税の負担は、売り手よりも高い価格を受け入れる買い手(消費者)に多くかかる。また、課税しても取引量があまり減らないので、税収が安定して得られやすく、課税による死荷重も比較的小さい。', exp: '需要曲線の傾きが急(非弾力的)な商品では、売り手が税の分だけ価格を上げても、買い手は買う量をあまり減らしません。その結果、価格は大きく上がり、その多くを買い手が負担します。\n税をかけて取引量が大きく減ると、税収は少なくなり、失われる取引(死荷重)も大きくなります。逆に、非弾力的な商品では、取引量があまり減らないので、税収が安定し、死荷重も小さくなります。たばこや酒、ガソリンに大きな税がかけられてきた理由の一つです。\nただし、生活必需品のような非弾力的な商品に重い税をかけると、所得の低い人ほど負担が重くなるという、公平さの問題が生じます。効率と公平の両面から考えることが大切です。' }
    ],
    faq: [
      ['総余剰が最大になれば、それは「公平」な状態なの?', 'そうとは限りません。総余剰が最大であることは、社会全体として取引の利益がむだなく生まれているという意味で【効率的】ですが、その利益がだれにどう分けられているかは問いません。\nたとえば、所得の多い人だけが大きな余剰を得ていても、総余剰は最大になりえます。そのため、市場の効率性を生かしながら、税や社会保障によって所得を再分配し、【公平】を実現することが、政府の重要な役割とされています。'],
      ['死荷重が生まれるのに、なぜ政府は価格を規制したり、税をかけたりするの?', '効率だけでなく、ほかの目的があるからです。税は、公共サービスの財源を集めるために必要です。また、たばこ税のように健康への害をおさえる目的や、環境税のように外部不経済をへらす目的もあります。\n外部不経済がある場合には、税をかけることで、かえって社会全体の余剰が増えることもあります。死荷重という「費用」と、規制や課税によって得られる「利益」を比べて判断することが大切です。']
    ]
  });

  add('pk_zaisei', {
    secs: [
      { h: 'さらに深く:公共事業は「使った額以上」に効く?──乗数効果のしくみ', t: '政府が景気対策として公共事業を10兆円増やすと、国全体の所得(GDP)は10兆円だけ増えるのでしょうか。実は、それ以上に増えると考えられています。これを【乗数効果】といいます。\nしくみを順に追ってみましょう。政府が道路工事に10兆円を使うと、建設会社や働く人の所得が10兆円増えます。所得が増えた人は、その一部を消費に回します。増えた所得のうち消費に回す割合を【限界消費性向】といい、これを0.8とすると、8兆円が新たに消費されます。その8兆円は、お店や会社の人々の所得になり、さらにその0.8倍の6.4兆円が消費されます……。\nこのように、所得の増加は、消費を通じて次々に波のように広がっていきます。その合計は、\n10兆+8兆+6.4兆+……=10兆×1/(1−0.8)=50兆円\nとなります。この「1/(1−限界消費性向)」を【乗数】といい、この例では5です。限界消費性向が大きいほど、乗数も大きくなります。\nでは、同じ10兆円の【減税】ではどうでしょう。減税では、最初の10兆円は人々の手もとに残るだけで、そのうち消費されるのは0.8倍の8兆円からです。そのため効果は 8兆×5=40兆円となり、公共事業より小さくなります。\nただし、現実の乗数はこれほど大きくありません。増えた所得の一部は、貯蓄だけでなく、税として納められたり、輸入品の購入に回って外国の所得になったりするからです。また、国債を大量に発行して金利が上がると、民間の投資が減る(クラウディング・アウト)ことも、効果を弱めます。', key: '乗数=1/(1−限界消費性向)。政府支出は最初の支出がまるごと所得になるので、同じ額の減税より効果が大きい。現実には貯蓄・税・輸入への漏れで乗数は小さくなる。', ex: [{ q: '限界消費性向が0.75の国で、政府が公共事業を20兆円増やした。(1)乗数はいくつか。(2)国民所得は最終的に何兆円増えるか。(3)同じ20兆円を公共事業ではなく減税に使った場合、国民所得は何兆円増えるか。', hint: '乗数は1/(1−限界消費性向)。減税は、最初の1回目の消費から波が始まります。', steps: ['(1)乗数=1/(1−0.75)=1/0.25=4。', '(2)公共事業の20兆円は、まるごとだれかの所得になるので、20兆×4=80兆円増える。', '(3)減税では、20兆円は人々の手もとに残るだけで、そのうち消費に回るのは 20兆×0.75=15兆円。', '波はこの15兆円から始まるので、15兆×4=60兆円増える(減税の乗数は 0.75/(1−0.75)=3 と考えてもよい)。'], a: '(1)4 (2)80兆円 (3)60兆円', check: '公共事業と減税の差は 80−60=20兆円で、ちょうど最初の20兆円の分です。公共事業では「最初の支出」そのものが所得になるのに、減税ではそれがない、というちがいがそのまま差になっていることが確かめられます。' }] },
      { h: '実戦演習:名目金利と実質金利──物価の上がり方で金利の重みが変わる', t: '銀行の預金や借金の金利としてふだん目にするのは【名目金利】です。しかし、お金を借りる人・貸す人にとって本当に大切なのは、物価の変化を差し引いた【実質金利】です。おおまかには、\n実質金利≒名目金利−物価上昇率(予想される物価上昇率)\nで表されます。\nたとえば、名目金利が2%で、物価が1年で3%上がるとすると、実質金利は約−1%です。返すお金の価値が物価の上昇で目減りするので、借りた人は実質的に得をし、貸した人は損をしているのです。\n逆に、デフレで物価が下がっていると、名目金利がほぼ0%でも、実質金利はプラスになります。\n問題を解くときの戦略は、引き算で出した実質金利の符号(プラスかマイナスか)から、借り手と貸し手のどちらが有利かを判断することです。落とし穴は、「金利がゼロ=お金を借りる負担がない」と考えてしまうことです。デフレのもとでは、名目金利がゼロでも実質的な負担は重くなります。', key: '実質金利≒名目金利−物価上昇率。物価が上がると借り手が有利、デフレでは名目金利がゼロでも実質金利はプラスになる。', ex: [{ q: 'Aさんは、銀行から年利1%で100万円を借りた。次の(1)(2)の場合について、実質金利を求め、Aさんにとって有利か不利かを答えよう。(1)1年間で物価が3%上がった。(2)1年間で物価が2%下がった。', hint: '実質金利≒名目金利−物価上昇率。物価が下がるときは、物価上昇率がマイナスです。', steps: ['名目金利は1%で、1年後に101万円を返すことになる。', '(1)物価上昇率は+3%なので、実質金利≒1−3=−2%。返すお金の価値が物価の上昇で目減りしており、Aさんは実質的に有利である。', '(2)物価上昇率は−2%なので、実質金利≒1−(−2)=+3%。物価が下がり、返すお金の価値が上がっているので、名目の1%より重い負担になり、Aさんは不利である。', '同じ1%の名目金利でも、物価の動きによって実質的な負担が大きく変わる。'], a: '(1)実質金利は約−2%で、Aさん(借り手)に有利。 (2)実質金利は約+3%で、Aさんに不利。', check: '(1)では、101万円を物価上昇の分で割ると、101万÷1.03≒98万円分の価値しかなく、借りた100万円より少なくなります。式の近似と実際の計算が同じ方向を示していることが確かめられます。' }, { q: '日本銀行は、短期の金利をほぼ0%まで下げた後、2013年に「物価上昇率2%」の目標をかかげて大量の資金を供給した。名目金利をこれ以上下げにくいときに、人々の予想する物価上昇率を高めようとすることには、どのようなねらいがあるか。実質金利ということばを使って説明しよう。', hint: '名目金利がゼロのままで、予想物価上昇率が上がると、実質金利はどうなるでしょうか。', steps: ['名目金利はほぼ0%で、それ以上大きく下げることは難しい。', '実質金利≒名目金利−予想物価上昇率なので、名目金利が0%のままでも、予想物価上昇率が上がれば、実質金利は下がる(マイナスになる)。', '実質金利が下がると、企業はお金を借りて設備投資をしやすくなり、人々も、物価が上がる前に買おうとして消費を増やしやすくなる。', 'このように、名目金利を下げられないかわりに、予想物価上昇率を高めて実質金利を下げ、投資や消費をうながして景気を回復させることがねらいである。'], a: '名目金利がほぼゼロでそれ以上下げられなくても、人々の予想物価上昇率を高めれば実質金利を下げることができる。実質金利が下がれば、企業の設備投資や家計の消費が増えやすくなり、景気の回復とデフレからの脱却につながると考えたから。', check: 'この政策は、人々が「本当に物価が上がる」と信じるかどうかに効果が左右されます。予想がなかなか変わらなければ、実質金利は下がりにくく、期待した効果が出にくいという課題があります。' }] }
    ],
    drill: [
      { lv: 2, q: '所得が増えたとき、その増えた分のうち消費に回される割合を何という?', a: '限界消費性向', exp: '限界消費性向は、「増えた所得1円のうち、何円を消費に使うか」を表します。たとえば、所得が10万円増えて8万円を消費に使えば、限界消費性向は0.8です。残りの割合(この例では0.2)は、貯蓄に回る割合で、限界貯蓄性向といいます。両者を足すと1になります。\n限界消費性向が大きいほど、政府支出の乗数効果(1/(1−限界消費性向))は大きくなります。\nなお、「限界」は日常のことばでは「これ以上はできないぎりぎりのところ」という意味ですが、経済学では「追加の1単位あたりの」という意味で使われます。限界費用・限界効用なども同じ使い方です。' },
      { lv: 3, q: '限界消費性向が0.6の国で、政府が公共事業を30兆円増やした場合と、30兆円の減税を行った場合とで、国民所得はそれぞれ最終的に何兆円増えるか。', a: '公共事業:75兆円 減税:45兆円', exp: '乗数は 1/(1−0.6)=1/0.4=2.5 です。\n公共事業の30兆円は、まるごとだれかの所得になるので、30兆×2.5=75兆円増えます。\n減税の30兆円は、まず人々の手もとに残り、そのうち消費に回るのは 30兆×0.6=18兆円です。波はこの18兆円から始まるので、18兆×2.5=45兆円増えます。減税の乗数は 0.6/0.4=1.5 と考えて、30兆×1.5=45兆円としても同じです。\n差の30兆円は、最初の支出の分にあたります。減税も公共事業と同じ乗数をかけて75兆円としてしまうのが、典型的なまちがいです。' },
      { lv: 3, q: 'デフレが続くと、名目金利がほぼ0%でも、企業が借り入れをして設備投資をしにくくなる。その理由を、実質金利と借金の重さの面から説明しなさい。', a: '物価が下がると、実質金利≒名目金利−物価上昇率で、物価上昇率がマイナスになるため、名目金利が0%でも実質金利はプラスになる。また、物価が下がると、企業の製品の価格や売り上げも下がりやすいのに、借金の金額は変わらないので、返済の負担が実質的に重くなる。そのため、企業は借り入れをして投資することに慎重になる。', exp: 'たとえば、名目金利0%・物価上昇率−2%なら、実質金利は約+2%です。金利がゼロに見えても、実際には2%の金利を払っているのと同じ重さになります。\nさらに、物価が下がると、企業が売る商品の値段も下がり、売り上げが減りやすくなります。一方、借りたお金の額は減らないので、借金の返済は売り上げに比べてますます重くなります。\nその結果、企業は投資をひかえ、借金の返済を急ぎます。すると経済全体の需要が減り、さらに物価が下がる、というデフレスパイラルにつながるおそれがあります。金融政策が「ゼロ金利」だけでは効きにくい理由として理解しておきましょう。' }
    ],
    faq: [
      ['乗数効果があるなら、政府はどんどんお金を使えばよいのでは?', 'そう単純ではありません。まず、現実には所得の増加分の一部が税や輸入、貯蓄に回るので、乗数は理論ほど大きくなりません。また、政府支出の財源を国債でまかなうと、国の借金が増え、将来の世代の負担になります。\nさらに、国債の大量発行で金利が上がれば、民間の投資が減るクラウディング・アウトが起こることもあります。景気が十分によいときに支出を増やすと、物価が上がりすぎるおそれもあります。乗数効果は、景気が悪く、使われていない労働力や設備があるときに最も働きやすいと考えられています。'],
      ['物価上昇率と金利の関係を、なぜ「予想される」物価上昇率で考えるの?', 'お金を借りたり貸したりする時点では、これから先の物価がどれだけ上がるかはわからないからです。人々は、将来の物価の動きを予想して、借りるか貸すか、投資するかどうかを決めます。\nそのため、実際の行動に影響するのは、あとからわかる実際の物価上昇率ではなく、決めるときに人々が予想している物価上昇率です。中央銀行が「物価目標」を示して人々の予想にはたらきかけようとするのは、このためです。']
    ]
  });

  add('pk_rodo', {
    secs: [
      { h: 'さらに深く:社会保険はなぜ「強制加入」なのか──保険のしくみと逆選択', t: '日本では、1961年に【国民皆保険・皆年金】が実現し、原則としてすべての人が公的な医療保険と年金に加入することになりました。自分で入るかどうかを選べる民間の保険とちがって、なぜ強制なのでしょうか。\n保険のしくみは、多くの人が少しずつ保険料を出し合い、病気や事故にあった少数の人がまとまった給付を受ける、というものです。加入者が多いほど、一人あたりの保険料は安定します。\nところが、加入を自由にすると問題が起こります。自分が病気になりやすいかどうかは、保険を運営する側より、本人のほうがよく知っています(【情報の非対称性】)。そのため、病気になりやすい人ほど保険に入りたがり、健康な人は「自分には必要ない」と入らなくなります。\nすると、加入者の中で病気になる人の割合が高くなり、給付が増えるので、保険料を上げなければなりません。保険料が上がると、さらに健康な人が抜けていき、保険料はますます上がります。こうして、保険が本当に必要な人ほど高い保険料を払うことになり、最後には保険そのものが成り立たなくなるおそれがあります。この現象を【逆選択】といいます。\nすべての人を強制的に加入させれば、健康な人も病気になりやすい人もいっしょに支え合うので、逆選択は起こりません。さらに、公的な保険では、保険料を所得に応じて決めることで、所得の多い人から少ない人へと所得を再分配するはたらきももっています。強制加入は、「だれもが安心して医療を受けられる」ための、しくみ上の工夫なのです。', key: '加入が自由だと、リスクの高い人ばかりが残って保険料が上がり続ける(逆選択)。強制加入はこれを防ぎ、所得の再分配も可能にする。', ex: [{ q: 'ある地域に100人が住んでおり、病気になりやすい人が20人(1人あたりの医療費は年50万円)、健康な人が80人(1人あたりの医療費は年5万円)いる。医療費の総額を保険料でまかなう保険をつくるとする。(1)100人全員が加入すると、1人あたりの保険料はいくらか。(2)加入が自由だと、どのようなことが起こるか。', hint: '健康な人にとって、(1)の保険料は自分の医療費と比べて高いでしょうか、安いでしょうか。', steps: ['(1)医療費の総額は、20人×50万円+80人×5万円=1000万円+400万円=1400万円。100人で割ると、1人あたりの保険料は14万円。', '(2)健康な人から見ると、自分の医療費は年5万円なのに、保険料は14万円で、9万円も多く払うことになる。', 'そのため、加入が自由なら、健康な人は保険に入らなくなる。', '病気になりやすい20人だけが残ると、医療費の総額1000万円を20人で割り、保険料は1人50万円に上がる。これでは保険で支え合う意味がなくなる。'], a: '(1)14万円 (2)健康な人は保険料が自分の医療費より高いので加入しなくなり、病気になりやすい人だけが残って、保険料が1人50万円まで上がってしまう(逆選択)。', check: '全員加入なら、病気になりやすい人の負担は50万円から14万円に下がり、健康な人は9万円多く払う代わりに、将来もし病気になったときの安心を得ます。強制加入によって、この支え合いが保たれることが数字で確かめられます。' }] },
      { h: '実戦演習:労働市場を需要と供給で考える──最低賃金と人手不足', t: '労働も、商品と同じように需要と供給のグラフで考えることができます。労働市場では、働き手を求める【企業が需要側】、働きたい【人々が供給側】で、価格にあたるのが【賃金】です。\n需要曲線は右下がり、供給曲線は右上がりです。\n【最低賃金】を均衡の賃金より高く定めると、企業が雇いたい人数より、働きたい人数のほうが多くなります。この差が、この単純なモデルでの【失業】(労働の超過供給)です。ただし現実の影響については、研究の結果が分かれています。\nまた、【少子高齢化】で働く世代の人口が減ると、労働の供給曲線は左へ移り、賃金が上がって人手不足が起こりやすくなります。\n問題を解くときは、「何が需要側で、何が供給側か」を最初に確かめましょう。商品市場とは、企業と家計の立場が逆になっていることが、最大の落とし穴です。', key: '労働市場では企業が需要側、働く人が供給側。均衡より高い最低賃金は、単純なモデルでは労働の超過供給(失業)を生む。少子高齢化は供給を減らす。', ex: [{ q: 'ある地域の労働市場で、時給をW円、労働者の人数をL人とすると、労働の需要は L=200−0.1W、労働の供給は L=0.1W で表される。(1)均衡の時給と雇用量を求めよう。(2)最低賃金を時給1200円と定めた場合、雇用される人数と、働きたいのに雇われない人数を求めよう。', hint: '最低賃金のもとでは、雇用される人数は、需要と供給のうち少ないほうになります。', steps: ['(1)需要と供給が等しくなるのは 200−0.1W=0.1W のとき。0.2W=200 より W=1000円。雇用量は L=0.1×1000=100人。', '(2)時給1200円のとき、企業が雇いたい人数(需要)は 200−0.1×1200=80人。', '働きたい人数(供給)は 0.1×1200=120人。', '企業は80人しか雇わないので、雇用されるのは80人。働きたいのに雇われない人は 120−80=40人(労働の超過供給)。'], a: '(1)時給1000円、雇用量100人 (2)雇用されるのは80人、働きたいのに雇われない人は40人', check: '最低賃金の導入で、雇われた80人は時給が1000円から1200円に上がって得をしますが、雇用は100人から80人に減っています。このモデルでは「賃金が上がる人」と「仕事を失う人」の両方が生まれることを確かめましょう。ただし、現実の影響は市場の条件によってちがいます。' }, { q: '少子高齢化によって、働く世代の人口が減っている。この変化を労働市場のグラフで表すと、どの曲線がどちらに動き、賃金と雇用量はどうなるか。また、それに対する政策を一つ挙げ、グラフ上の動きで説明しよう。', hint: '働く世代の人口が減ると、需要と供給のどちらに影響するでしょうか。', steps: ['働く世代の人口が減ると、どの賃金でも働きたい人の数が減るので、労働の供給曲線が左へ動く。', '需要曲線が変わらなければ、新しい交点では、賃金は上がり、雇用量は減る。これが人手不足の状態である。', '政策の例として、高齢者が長く働ける環境を整える(定年の延長など)、育児と仕事を両立しやすくして女性の就労を広げる、外国人労働者を受け入れる、などが考えられる。', 'これらの政策は、どの賃金でも働きたい人の数を増やすので、労働の供給曲線を右へ動かし、人手不足をやわらげるはたらきをもつ。'], a: '労働の供給曲線が左へ動き、賃金は上がり、雇用量は減る(人手不足)。政策の例:高齢者や女性の就労の拡大、外国人労働者の受け入れなど。これらは労働の供給曲線を右へ動かす。', check: 'もう一つの対策として、機械化やAIの活用で少ない人数でも生産できるようにする方法もあります。これは、企業が必要とする労働者の数を減らすので、需要曲線を左へ動かす動きとして表せます。どちらの曲線が動くのかを区別しましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '保険への加入を自由にすると、リスクの高い人ほど加入し、リスクの低い人は加入しなくなって、保険料が上がり続け、保険が成り立ちにくくなる現象を何という?', a: '逆選択', exp: '逆選択は、売り手と買い手(保険では、保険の運営者と加入者)の間で持っている情報に差があることから起こる、市場の失敗の一つです。加入者は自分の健康状態をよく知っていますが、保険の運営者はそれを十分には知りません。\nこのため、加入を自由にすると、病気になりやすい人ほど保険を選び、健康な人は入らなくなります。本来の「よい加入者を選びたい」という方向と逆の結果になるので、逆選択とよばれます。\n中古車の市場で、品質の悪い車ばかりが出回るようになる例も、同じしくみで説明されます。公的な医療保険や年金が強制加入なのは、これを防ぐためでもあります。' },
      { lv: 3, q: 'ある地域の労働市場で、時給をW円、労働者の人数をL人とすると、労働の需要は L=300−0.2W、労働の供給は L=0.1W で表される。(1)均衡の時給と雇用量を求めよう。(2)最低賃金を時給1100円にすると、働きたいのに雇われない人は何人になるか。', a: '(1)時給1000円、雇用量100人 (2)30人', exp: '(1)300−0.2W=0.1W より 0.3W=300、W=1000円。雇用量は L=0.1×1000=100人です。\n(2)時給1100円のとき、労働の需要は 300−0.2×1100=300−220=80人、供給は 0.1×1100=110人です。企業は需要の80人しか雇わないので、雇われない人は 110−80=30人です。\n均衡の時給1000円と比べると、雇われた80人は時給が上がって得をしますが、雇用は100人から80人に減り、さらに時給が上がったことで働きたいと考える人が110人に増えています。\nまちがえやすいのは、雇用される人数を供給の110人としてしまうことです。最低賃金のもとでは、雇う人数を決めるのは企業(需要側)なので、需要と供給のうち少ないほうが実際の雇用量になります。' },
      { lv: 3, q: '公的な医療保険が強制加入であることには、逆選択を防ぐことのほかに、どのような意義があるか。保険料の決め方と結びつけて説明しなさい。', a: '公的な医療保険では、保険料が所得に応じて決められ(所得の多い人ほど多く負担し)、病気になったときの給付はだれでも同じように受けられる。そのため、所得の多い人から少ない人へ、また健康な人から病気の人へと所得が再分配され、所得の少ない人でも必要な医療を受けられるようにするという意義がある。', exp: '民間の保険では、保険料は「その人がどれだけ病気になりやすいか」(リスク)に応じて決められるのがふつうです。これに対して公的な医療保険では、保険料は主に所得に応じて決まり、リスクの高さでは変わりません。\nもし加入が自由なら、所得の多い人は「自分は保険料が高いのに、受けられる医療は同じだ」と考えて、抜けてしまうかもしれません。強制加入にすることで、この再分配のしくみを保つことができます。\n社会保険は、「保険」の原理(リスクの分散)と、「社会保障」の原理(所得の再分配)の両方をあわせもつ制度だ、と整理しておきましょう。' }
    ],
    faq: [
      ['強制加入なら、保険料を払わない人はどうなるの?', '公的な保険では、保険料を払わないと、さまざまな不利益が生じます。たとえば国民年金の保険料を払わない期間があると、将来受けとる年金が減ったり、受けとれなくなったりすることがあります。国民健康保険の保険料を長く払わないと、医療費をいったん全額自分で払わなければならなくなる場合もあります。\n一方で、所得が少なく払うのが難しい人のために、保険料の免除や猶予の制度も用意されています。払えないときは、放置せずに手続きをすることが大切です。'],
      ['最低賃金を上げると、本当に失業が増えるの?', '単純な需要と供給のモデルでは、均衡より高い最低賃金は失業を生みます。しかし現実はそれほど単純ではありません。働く場所の選択肢が少ない地域などでは、企業が賃金を低くおさえる力をもっており、最低賃金を上げても雇用が減らないことがあると考えられています。\nまた、賃金が上がると働く人の意欲が高まり、消費も増えるという効果もあります。実際の研究でも結果は分かれており、上げ幅や地域の状況によって影響が異なる、というのが慎重な見方です。']
    ]
  });

  add('pk_kokusai', {
    secs: [
      { h: 'さらに深く:為替レートの「ものさし」──購買力平価', t: '1ドルが何円になるかは、毎日変わります。では、長い目で見たときに、為替レートは何によって決まるのでしょうか。その目安となる考え方が【購買力平価】です。\n購買力平価とは、【同じ商品が、どの国でも同じ値段で買えるような為替レート】のことです。たとえば、あるハンバーガーが日本で450円、アメリカで5ドルだとします。同じものが同じ値段になるには、450円=5ドル、つまり【1ドル=90円】でなければなりません。これが、このハンバーガーで見た購買力平価です。\nもし実際の為替レートが1ドル=150円なら、5ドルのハンバーガーは日本円で750円になり、日本で買う(450円)より高くなります。このとき円は、購買力平価に比べて【割安】(円安の状態)だといえます。外国人から見ると、日本の商品が安く買えることになります。\n購買力平価の考え方は、物価の変化にも使えます。日本の物価が変わらず、アメリカの物価が毎年3%上がるとすると、同じ1ドルで買えるものは毎年少なくなり、ドルの価値は下がります。そのため長い目で見ると、【物価上昇率の高い国の通貨は安くなる】傾向があります。\nただし、現実の為替レートは、短い期間では購買力平価から大きくはなれることがあります。国ごとの金利の差によってお金が動いたり、将来の予想にもとづく取引が行われたりするからです。また、家賃や散髪のように、国をこえて売り買いできないサービスの値段は、購買力平価に近づきにくいのです。', key: '購買力平価は「同じ商品が同じ値段になる為替レート」。長期的には、物価上昇率の高い国の通貨が安くなる傾向がある。', ex: [{ q: 'あるコーヒーが、日本では480円、アメリカでは4ドルで売られている。(1)このコーヒーで見た購買力平価を求めよう。(2)実際の為替レートが1ドル=150円のとき、円は購買力平価に比べて割高か割安か。アメリカ人旅行者にとって、日本のコーヒーは高く感じるか安く感じるか。', hint: '「480円=4ドル」となる為替レートを求めます。', steps: ['(1)480円=4ドルなので、1ドル=480÷4=120円。これが購買力平価である。', '(2)実際の為替レートは1ドル=150円で、購買力平価の120円より円の価値が低い(1ドルでより多くの円と交換できる)ので、円は割安である。', 'アメリカ人旅行者が日本のコーヒー480円を買うのに必要なドルは、480÷150=3.2ドル。', 'アメリカでは4ドルなので、日本のコーヒーは0.8ドル安く感じる。'], a: '(1)1ドル=120円 (2)円は割安。アメリカ人旅行者には、日本のコーヒーは安く感じる(3.2ドルで買えるため)。', check: '逆に日本人がアメリカで4ドルのコーヒーを買うと、4×150=600円で、日本の480円より高く感じます。円が割安のときは、外国からの旅行者が増えやすく、日本人の海外旅行は割高になる、という円安の影響とも一致します。' }] },
      { h: '実戦演習:国際収支の表を読み解く', t: '日本の国際収支は2014年から、次のような形で表されています。\n【経常収支】=貿易・サービス収支+第一次所得収支+第二次所得収支\n・貿易・サービス収支:モノの輸出入と、旅行・輸送などのサービスの取引。\n・第一次所得収支:外国に投資して得た利子や配当、外国で働いて得た給料など。\n・第二次所得収支:政府開発援助のうちの無償の資金協力、外国で働く人の本国への送金など、見返りのない資金の移転。\n【金融収支】:外国への直接投資や証券投資、外貨準備などの増減。日本の資産が増えるとプラスになります。\nこれらの間には、\n経常収支+資本移転等収支−金融収支+誤差脱漏=0\nという関係があります。\n戦略は、①取引をどの項目に入れるかを判断し、②この式を使って未知の項目を求めることです。落とし穴は、外国からの利子・配当を「サービス収支」に入れたり、旧来の「資本収支」と金融収支の符号の向きを混同したりすることです。', key: '経常収支=貿易・サービス収支+第一次所得収支+第二次所得収支。経常収支+資本移転等収支−金融収支+誤差脱漏=0。', ex: [{ q: 'ある国の1年間の国際収支は、貿易・サービス収支が−3兆円、第一次所得収支が+25兆円、第二次所得収支が−2兆円、資本移転等収支が−0.5兆円、誤差脱漏が+1.5兆円だった。(1)経常収支を求めよう。(2)金融収支を求めよう。(3)この国の経常収支の特徴を説明しよう。', hint: '経常収支は3つの収支の合計です。金融収支は、関係式を変形して求めます。', steps: ['(1)経常収支=−3+25+(−2)=+20兆円。', '(2)関係式 経常収支+資本移転等収支−金融収支+誤差脱漏=0 を変形すると、金融収支=経常収支+資本移転等収支+誤差脱漏。', 'よって金融収支=20+(−0.5)+1.5=+21兆円。プラスなので、この国の外国にある資産が増えた(外国への投資が増えた)ことを表す。', '(3)貿易・サービス収支は赤字だが、外国への投資から得る利子や配当などの第一次所得収支の黒字が大きいため、経常収支は大きな黒字になっている。'], a: '(1)+20兆円 (2)+21兆円 (3)貿易・サービス収支は赤字だが、外国への投資から得る利子・配当などの第一次所得収支の大きな黒字によって、経常収支が黒字になっている。', check: '求めた値を関係式にもどすと、20+(−0.5)−21+1.5=0 となり、式が成り立ちます。日本も近年、貿易で稼ぐ国から、過去に積み上げた外国への投資の収益で稼ぐ国へと変わってきたといわれ、この例と似た構造をもっています。' }] }
    ],
    drill: [
      { lv: 2, q: '国際収支のうち、外国への投資から得た利子や配当、外国で働いて得た給料などの受け取りと支払いを表す項目を何という?', a: '第一次所得収支', exp: '経常収支は、貿易・サービス収支、第一次所得収支、第二次所得収支の3つからなります。第一次所得収支は、「生産に使われたお金や労働への見返り」の受け払いを表します。日本の企業が外国の工場から受けとる配当や、日本人が持つ外国の債券の利子などが入ります。\nこれに対して、第二次所得収支は、無償の援助や外国で働く人の家族への送金など、「見返りのない」お金の移転を表します。\n「サービス収支」は、旅行や輸送、特許の使用料など、サービスそのものの取引です。利子や配当をサービス収支に入れてしまうのが、よくあるまちがいです。' },
      { lv: 3, q: 'ある本が日本では2000円、アメリカでは20ドルで売られている。(1)この本で見た購買力平価を求めよう。(2)今後10年間、日本の物価はほとんど変わらず、アメリカの物価だけが2倍になったとする。購買力平価はどのように変わるか。', a: '(1)1ドル=100円 (2)アメリカでの本の価格が40ドルになるので、購買力平価は1ドル=50円となり、円高・ドル安の方向に変わる。', exp: '(1)2000円=20ドルとなるのは、1ドル=2000÷20=100円のときです。\n(2)アメリカの物価が2倍になると、同じ本は40ドルになります。日本では2000円のままなので、2000円=40ドル、つまり1ドル=50円が新しい購買力平価です。\n1ドルで交換できる円が100円から50円に減ったので、ドルの価値が下がり、円の価値が上がったことになります。これは、物価上昇率の高い国の通貨(ここではドル)が安くなる、という購買力平価の考え方を表しています。\n「アメリカの物価が上がる=ドルが強くなる」と逆に考えないよう注意しましょう。物価が上がるということは、そのお金で買えるものが減る、つまりお金の価値が下がるということです。' },
      { lv: 3, q: 'ある国の経常収支が+15兆円、資本移転等収支が−1兆円、金融収支が+16兆円だった。誤差脱漏を求めよう。また、経常収支が黒字の国では、金融収支もプラスになりやすいのはなぜか説明しよう。', a: '誤差脱漏は+2兆円。経常収支の黒字でかせいだお金(外国の通貨)は、そのままでは使われず、外国の債券や株式の購入、外国への直接投資などに回されるので、外国にある資産が増え、金融収支がプラスになりやすいから。', exp: '関係式 経常収支+資本移転等収支−金融収支+誤差脱漏=0 に数字を入れると、15+(−1)−16+誤差脱漏=0 となり、−2+誤差脱漏=0 なので、誤差脱漏=+2兆円です。\n経常収支の黒字は、輸出や投資収益などで外国から受けとるお金が、支払うお金より多いことを意味します。そのお金は、最終的には外国の資産(外国の会社の株、国債、工場など)を持つ形で使われます。だから、経常収支の黒字と、金融収支のプラス(対外資産の増加)は、ほぼ同じ大きさになります。\n「金融収支のプラス=お金が国内に入ってくる」と思いこむと、符号を逆にしてしまいます。金融収支は「日本の資産が増えるとプラス」と覚えましょう。' }
    ],
    faq: [
      ['経常収支が黒字なら、その国は豊かで、赤字なら貧しいの?', 'そうとは限りません。経常収支は、国内の貯蓄と投資のバランスを表す面があります。国内の貯蓄が投資より多ければ、余ったお金が外国に向かい、経常収支は黒字になりやすくなります。\nアメリカは長く経常収支の赤字が続いていますが、世界最大級の経済大国です。外国からお金が集まり、それが国内の投資や消費を支えているともいえます。黒字か赤字かだけで、良い・悪いを決めることはできません。'],
      ['為替レートが、購買力平価からはなれることがあるのはなぜ?', '理由はいくつかあります。①国ごとの金利の差によって、より高い利子を求めてお金が国から国へと動き、為替レートを動かす。②将来の景気や政策についての予想にもとづいて、通貨の売り買いが行われる。③家賃・散髪・医療など、国をこえて売り買いできない商品やサービスがあり、その値段は国ごとにちがったままになる。\nそのため、購買力平価は、短期の為替レートを当てるものではなく、長い目で見たときの「目安」として使われます。']
    ]
  });

})(WPS.LESSONS);
